WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','junior','HTML5''te semantic elementler (`<article>`, `<section>`, `<nav>`) kullanmanın `<div>` kullanımına göre temel avantajı nedir?','Semantic elementler içeriğin amacını tarayıcı, arama motoru ve ekran okuyuculara açıkça bildirir. SEO puanını artırır, erişilebilirliği iyileştirir ve kodun okunabilirliğini yükseltir. `<div>` yalnızca stil kancası işlevi görürken semantic elementler anlam taşır.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Arama motorları ve ekran okuyuculara içerik hakkında anlamsal bilgi verir; SEO ve erişilebilirliği artırır' FROM q UNION ALL SELECT id,1,'Tarayıcı bu etiketleri önce işlediği için sayfa yüklenme hızını doğrudan artırır' FROM q UNION ALL SELECT id,2,'CSS stilleri yalnızca semantic elementlere uygulanabilir; div ile stil kullanımı kısıtlıdır' FROM q UNION ALL SELECT id,3,'JavaScript DOM sorgularında querySelector semantic elementleri daha hızlı bulur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','junior','CSS''te `box-sizing: border-box` ayarlandığında genişlik hesabı nasıl değişir?','Varsayılan `content-box`''ta `width` yalnızca içerik alanını kapsar; padding ve border ayrıca eklenir. `border-box`''ta ise `width` padding ve border dahil toplam genişliği temsil eder; içerik alanı otomatik küçülür. Düzenler daha öngörülebilir hale gelir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'width sadece margin''i kapsar; padding ve border ayrıca dışarıya eklenir' FROM q UNION ALL SELECT id,1,'width değeri padding ve border''ı kapsar; içerik alanı otomatik küçülür' FROM q UNION ALL SELECT id,2,'width ve height değerleri birbirine eşitlenir, kare element elde edilir' FROM q UNION ALL SELECT id,3,'width yalnızca margin ile padding toplamını temsil eder' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','junior','JavaScript''te `var`, `let` ve `const` arasındaki kapsam (scope) farkı nedir?','`var` fonksiyon kapsamlıdır ve hoisting ile undefined olarak başlatılır. `let` ve `const` blok kapsamlıdır; TDZ (Temporal Dead Zone) nedeniyle tanımlanmadan önce erişilemez. `const` yeniden atamaya izin vermez ancak nesne içeriği değiştirilebilir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Üçü de blok kapsamlıdır; yalnızca const yeniden atamayı engeller' FROM q UNION ALL SELECT id,1,'var ve let fonksiyon kapsamlıdır; const global kapsamda tanımlanır' FROM q UNION ALL SELECT id,2,'var fonksiyon kapsamlı ve hoisted''dır; let/const blok kapsamlı ve TDZ''ye tabidir' FROM q UNION ALL SELECT id,3,'let ve const arasında kapsam farkı yoktur; ikisi tamamen aynı davranır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','junior','React''ta `useRef` hook''u en yaygın hangi amaçla kullanılır?','`useRef`, render''lar arasında korunan değişken bir referans nesnesi döndürür. En yaygın kullanımı DOM elementine doğrudan erişimdir (focus, scroll, ölçüm). `.current` değiştirildiğinde yeniden render tetiklenmez; bu yönüyle `useState`''ten ayrılır.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Component''ler arası veri paylaşımı için global depo oluşturmak' FROM q UNION ALL SELECT id,1,'Asenkron API çağrılarını iptal etmek için AbortController yerine kullanmak' FROM q UNION ALL SELECT id,2,'CSS animasyonlarını JavaScript ile kontrol etmek için özel hook oluşturmak' FROM q UNION ALL SELECT id,3,'DOM elementine imperative erişim sağlamak veya render tetiklemeden değer saklamak' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','junior','JavaScript''te event bubbling nasıl çalışır?','Bubbling''de bir olay önce hedef elementte tetiklenir, ardından DOM ağacında yukarıya doğru parent elementlere iletilir. `event.stopPropagation()` ile durdurulabilir. Event delegation pattern''ı bubbling''e dayanır: tek parent listener ile tüm child''ları yönetmek mümkündür.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Olay önce hedef elementte oluşur, ardından parent elementlere doğru yukarı yayılır' FROM q UNION ALL SELECT id,1,'Olay en üst parent''tan başlar ve hedef elemente doğru aşağı iner' FROM q UNION ALL SELECT id,2,'Olay yalnızca hedef elementte tetiklenir, diğer elementlere yayılmaz' FROM q UNION ALL SELECT id,3,'Olay aynı anda tüm DOM ağacındaki dinleyicilere paralel gönderilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','junior','`localStorage` ile `sessionStorage` arasındaki temel fark nedir?','`localStorage` veriyi tarayıcı kapatılsa bile kalıcı olarak saklar; `sessionStorage` yalnızca sekme açık olduğu sürece geçerlidir ve kapanınca silinir. İkisi de origin''e göre izole edilir ve yaklaşık 5 MB depolama alanı sunar.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'localStorage şifreli depolar; sessionStorage şifresiz düz metin olarak saklar' FROM q UNION ALL SELECT id,1,'localStorage kalıcıdır; sessionStorage yalnızca sekme açık olduğu sürece geçerlidir' FROM q UNION ALL SELECT id,2,'localStorage 5 MB ile sınırlıdır; sessionStorage sınırsız depolama sunar' FROM q UNION ALL SELECT id,3,'localStorage yalnızca string saklar; sessionStorage JSON nesneleri doğrudan depolar' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','junior','CSS flexbox''ta `justify-content` ve `align-items` property''lerinin farkı nedir?','`justify-content` ana eksen (main axis) boyunca hizalamayı kontrol eder; `flex-direction: row`''da bu yataydır. `align-items` çapraz eksen (cross axis) boyunca hizalamayı yönetir. `flex-direction: column`''da bu ilişki yer değiştirir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'justify-content dikey, align-items yatay eksende hizalama yapar' FROM q UNION ALL SELECT id,1,'İkisi de yatay eksende çalışır; fark yalnızca yazım söz dizimidir' FROM q UNION ALL SELECT id,2,'justify-content ana ekseni (varsayılan: yatay), align-items çapraz ekseni (varsayılan: dikey) hizalar' FROM q UNION ALL SELECT id,3,'justify-content tüm container''ı, align-items yalnızca ilk öğeyi etkiler' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','junior','React''ta bir butona tıklama handler bağlamanın doğru yolu hangisidir?','JSX''te event handler''lar camelCase ile yazılır (`onClick`). `{handleClick}` referans olarak geçilir; `{handleClick()}` yazılırsa render sırasında hemen çalışır. Arrow function (`() => handleClick()`) parametre geçmek için uygundur ancak her render''da yeni fonksiyon oluşturur.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'HTML gibi onclick="handleClick()" string olarak yazılır' FROM q UNION ALL SELECT id,1,'addEventListener ile DOM elementine doğrudan bağlanır' FROM q UNION ALL SELECT id,2,'useEffect içinde event listener eklenir, cleanup''ta kaldırılır' FROM q UNION ALL SELECT id,3,'JSX''te onClick={handleClick} şeklinde fonksiyon referansı geçilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','junior','CSS''te `position: relative` ile `position: absolute` arasındaki fark nedir?','`position: relative` elementi normal akışta bırakır, koordinatlar orijinal pozisyona göredir. `position: absolute` elementi akıştan çıkarır ve en yakın positioned (non-static) ataya göre konumlanır. Child absolute için parent''a `position: relative` eklemek yaygın bir pattern''dır.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'relative elementi normal akışta tutar; absolute elementi akıştan çıkarır ve positioned parent''a göre konumlar' FROM q UNION ALL SELECT id,1,'relative sayfaya, absolute ise viewport''a göre konumlanır' FROM q UNION ALL SELECT id,2,'İkisi de aynı şekilde çalışır; fark yalnızca yazım tercihindendir' FROM q UNION ALL SELECT id,3,'relative z-index kullanımına izin vermez; absolute her zaman üstte görünür' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','junior','JavaScript''te `null` ile `undefined` arasındaki anlam farkı nedir?','`undefined`, bir değişkenin tanımlanmış ancak değer atanmamış olduğunu gösterir (JS''in varsayılan değeri). `null` ise kasıtlı olarak "boş değer" atamak için kullanılır; geliştirici tarafından bilinçli set edilir. `typeof null === "object"` bilinen bir JS quirk''üdür.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'undefined sayısal sıfırı, null ise boş string''i temsil eder' FROM q UNION ALL SELECT id,1,'undefined değer atanmamış durumu, null ise kasıtlı boşluğu temsil eder' FROM q UNION ALL SELECT id,2,'İkisi tamamen aynıdır; === ile karşılaştırıldığında true döner' FROM q UNION ALL SELECT id,3,'null yalnızca nesne değişkenlerine, undefined yalnızca primitive''lere atanabilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','junior','HTML''de `<meta name="viewport" content="width=device-width, initial-scale=1">` etiketi ne işe yarar?','Viewport meta etiketi olmadan mobil tarayıcılar sayfayı masaüstü genişliğinde (genellikle 980px) render eder ve küçültür. Bu etiket tarayıcıya cihaz genişliğinde render et talimatı verir; CSS media query''lerin doğru çalışması için zorunludur.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Sayfanın yalnızca masaüstü cihazlarda görüntülenmesini sağlar' FROM q UNION ALL SELECT id,1,'Tarayıcının otomatik zoom özelliğini tamamen devre dışı bırakır' FROM q UNION ALL SELECT id,2,'Mobil cihazlarda sayfanın cihaz genişliğinde render edilmesini sağlar; responsive tasarımın temelidir' FROM q UNION ALL SELECT id,3,'Yalnızca Safari''ye özel bir etiket olup diğer tarayıcılar tarafından görmezden gelinir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','junior','JavaScript''te `async/await` ile hataları yakalamak için önerilen yöntem nedir?','`async/await` ile hatalar `try/catch` bloğu içinde senkron kod gibi yakalanır. `await` edilen promise reject olursa `catch` bloğu çalışır. `.catch()` zinciri de geçerli olmakla birlikte, `try/catch` daha okunabilir ve birden fazla await''i tek blokta kapsar.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'window.onerror global handler ile yakalanır; try/catch async''de çalışmaz' FROM q UNION ALL SELECT id,1,'Promise.reject() çağrısı ile hata manuel fırlatılıp dışarıdan kontrol edilir' FROM q UNION ALL SELECT id,2,'useEffect içinde error state güncellenerek React error boundary''sine iletilir' FROM q UNION ALL SELECT id,3,'try/catch bloğu kullanılır; await edilen promise reject olduğunda catch bloğu devreye girer' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','mid','React''ta `useCallback` ile `useMemo` arasındaki fark nedir?','`useCallback(fn, deps)` fonksiyonu memoize eder; bağımlılıklar değişmediği sürece aynı fonksiyon referansını döndürür. `useMemo(fn, deps)` ise fonksiyonun dönüş değerini memoize eder. `useCallback(fn, deps)` ile `useMemo(() => fn, deps)` eşdeğerdir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'useCallback fonksiyon referansını, useMemo ise hesaplanan değeri memoize eder' FROM q UNION ALL SELECT id,1,'useCallback async, useMemo sync fonksiyonlar için kullanılır' FROM q UNION ALL SELECT id,2,'useMemo state''i, useCallback props''u önbelleğe alır' FROM q UNION ALL SELECT id,3,'İkisi aynı işi yapar; yalnızca söz dizimi farklıdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','mid','JavaScript''te `debounce` ve `throttle` arasındaki fark nedir?','`debounce` son çağrıdan itibaren belirli süre bekler; süre dolmadan yeni çağrı gelirse sayaç sıfırlanır. Arama kutusu önerisi için idealdir. `throttle` ise belirli aralıkta en fazla bir kez çalışır; scroll veya resize dinleyicileri için uygundur.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'debounce belirli aralıkta bir kez çalışır; throttle son çağrıyı geciktirir' FROM q UNION ALL SELECT id,1,'debounce son çağrı bittikten sonra geciktirir; throttle belirli aralıkta bir kez çalışır' FROM q UNION ALL SELECT id,2,'debounce Promise tabanlı, throttle callback tabanlı çalışır' FROM q UNION ALL SELECT id,3,'İkisi aynı sonucu üretir; fark yalnızca bekleme süresi hesaplama yöntemindedir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','mid','React Portal nedir ve ne zaman kullanılır?','Portal, bir component''i kendi DOM parent''ının dışındaki bir node''a render eder. Modal, tooltip, dropdown gibi bileşenlerde `z-index` sorunlarını ve `overflow: hidden` kısıtlamalarını aşmak için kullanılır. React event sistemi portalda da çalışmaya devam eder.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Farklı React uygulama örnekleri arasında veri aktarmak için kullanılan bir API''dir' FROM q UNION ALL SELECT id,1,'Component''lerin sunucu taraflı render edilmesini sağlayan özel bir React metodudur' FROM q UNION ALL SELECT id,2,'Component''i DOM hiyerarşisi dışına render eder; modal ve tooltip''lerde z-index sorunlarını çözer' FROM q UNION ALL SELECT id,3,'Redux Store ile React component''leri arasındaki bağlantıyı kuran özel bir hook''tur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','mid','CSS Grid''de `fr` birimi ne anlama gelir?','`fr` (fraction), kullanılabilir boş alanın oransal bir birimini temsil eder. `1fr 2fr` tanımında ikinci sütun birincinin iki katı alan kaplar. Sabit birimlerle karıştırılabilir; sabit alanlar ayrıldıktan sonra kalan alan `fr` ile bölüştürülür.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Frequency birimi olup animasyon hızını grid hücre sayısıyla orantılar' FROM q UNION ALL SELECT id,1,'Full-responsive kısaltması olup %100 genişlik anlamına gelir' FROM q UNION ALL SELECT id,2,'Font-relative birim olup em ile aynı şekilde çalışır' FROM q UNION ALL SELECT id,3,'Fraction (kesir) birimi olup kullanılabilir alanın oransal payını temsil eder' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','mid','JavaScript''te prototype chain nasıl çalışır?','Her JS nesnesinin dahili [[Prototype]] bağlantısı vardır. Property arandığında önce nesnenin kendisinde, bulunmazsa prototype''ında, zincir boyunca Object.prototype''a kadar aranır. null ile biten bu zincir inheritance mekanizmasının temelidir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Property arama nesnenin kendisinde başlar, bulunamazsa [[Prototype]] zinciri boyunca Object.prototype''a kadar ilerler' FROM q UNION ALL SELECT id,1,'Prototype chain yalnızca class keyword''ü ile tanımlanan nesnelerde çalışır' FROM q UNION ALL SELECT id,2,'Her nesne prototype''ını kopyalar; değişiklikler orijinal prototipi etkilemez' FROM q UNION ALL SELECT id,3,'Prototype chain yalnızca method aramasında çalışır; property aramasında devreye girmez' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','mid','TypeScript''te `interface` ve `type` ne zaman hangisi tercih edilmeli?','`interface` nesne şekillerini tanımlamak ve OOP kalıtımı (extends/implements) için idealdir; declaration merging destekler. `type` ise union, intersection, conditional ve mapped type gibi gelişmiş tip operasyonları için gereklidir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'interface React component''leri, type ise utility fonksiyonlar için tercih edilir' FROM q UNION ALL SELECT id,1,'interface nesne şekilleri ve sınıf kalıtımı için; type union/intersection gibi gelişmiş tipler için tercih edilir' FROM q UNION ALL SELECT id,2,'type daha hızlı derlenir; büyük projelerde interface yerine her zaman type kullanılmalıdır' FROM q UNION ALL SELECT id,3,'İkisi tamamen birbirinin yerine kullanılabilir; herhangi bir fark yoktur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','mid','Web Vitals metriklerinden LCP (Largest Contentful Paint) neyi ölçer?','LCP, viewport''taki en büyük içerik öğesinin (resim, video poster, blok metin) görünür olma süresini ölçer. 2.5 saniye altı iyi, 4 saniye üzeri kötü kabul edilir. Büyük resimlerin optimizasyonu, critical CSS ve sunucu yanıt süresi LCP''yi doğrudan etkiler.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Sayfadaki tüm DOM elementlerinin toplam yükleme süresini ölçer' FROM q UNION ALL SELECT id,1,'Kullanıcının ilk etkileşiminden tarayıcının yanıt vermesine kadar geçen süreyi ölçer' FROM q UNION ALL SELECT id,2,'Viewport''taki en büyük içerik öğesinin görünür hale gelme süresini ölçer' FROM q UNION ALL SELECT id,3,'Sayfa yaşam döngüsü boyunca gerçekleşen toplam layout kayması miktarını ölçer' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','mid','React''ta controlled ve uncontrolled component arasındaki fark nedir?','Controlled component''te form elemanının değeri React state tarafından yönetilir; her değişiklik onChange ile state''i günceller. Uncontrolled''da ise değer DOM''da saklanır ve `ref` ile okunur. Controlled yaklaşım doğrulama ve test için daha öngörülebilir yapı sağlar.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Controlled component kendi state''ini yönetir; uncontrolled ise parent''tan props alır' FROM q UNION ALL SELECT id,1,'Controlled TypeScript ile, uncontrolled ise vanilla JS ile çalışır' FROM q UNION ALL SELECT id,2,'Controlled sunucu taraflı, uncontrolled ise istemci taraflı render kullanır' FROM q UNION ALL SELECT id,3,'Controlled''da form değeri React state tarafından yönetilir; uncontrolled''da değer DOM''da saklanır, ref ile okunur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','mid','JavaScript event loop''ta macrotask ve microtask farkı nedir?','Microtask kuyruğu (Promise callbacks, queueMicrotask) her macrotask bittikten sonra tamamen tüketilir. setTimeout/setInterval macrotask''lardır. Dolayısıyla microtask''lar macrotask''lardan önce çalışır; bir microtask içinden sonsuz microtask üretmek event loop''u bloklar.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Microtask (Promise callback) her macrotask''tan sonra tamamen temizlenir; macrotask''lardan önce çalışır' FROM q UNION ALL SELECT id,1,'Macrotask ve microtask sıra gözetmeksizin FIFO düzeninde işlenir' FROM q UNION ALL SELECT id,2,'setTimeout her zaman Promise .then()''den önce çalışır' FROM q UNION ALL SELECT id,3,'Microtask yalnızca async/await kullanıldığında oluşur; .then() callback macrotask''tır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','mid','CSS specificity nasıl hesaplanır?','Specificity 4 bileşenden oluşur: inline style (1,0,0,0) > ID (0,1,0,0) > class/pseudo-class/attribute (0,0,1,0) > element/pseudo-element (0,0,0,1). !important tüm kuralları geçersiz kılar ancak kötü pratik sayılır. Aynı specificity''de son gelen kural kazanır.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Yalnızca seçici türleri sayılır; en fazla seçici içeren kural kazanır' FROM q UNION ALL SELECT id,1,'Inline > ID > class/pseudo-class > element sıralamasıyla 4 bileşen hesaplanır; yüksek bileşen kazanır' FROM q UNION ALL SELECT id,2,'CSS dosyasında en son yazılan kural her zaman en yüksek önceliğe sahiptir' FROM q UNION ALL SELECT id,3,'Specificity yalnızca aynı seçiciler çakıştığında hesaplanır; farklı türlerde geçersizdir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','mid','React.lazy() ve Suspense ne için kullanılır?','`React.lazy()` bir bileşeni dinamik import ile code splitting''e tabi tutar; ilk render''da chunk yüklenmemişse Suspense fallback gösterilir. Bu sayede ilk bundle boyutu azalır, yalnızca kullanıcının gittiği route''ların kodu indirilir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Bileşenin sunucu tarafında pre-render edilmesini ve hydration''ını yönetir' FROM q UNION ALL SELECT id,1,'Yavaş API çağrıları sırasında loading spinner göstermeyi otomatik hale getirir' FROM q UNION ALL SELECT id,2,'Bileşeni dinamik import ile kod parçasına böler; yüklenirken fallback UI gösterir' FROM q UNION ALL SELECT id,3,'Hatalı render eden bileşeni yakalar ve Error Boundary yerine kullanılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','mid','CSS custom properties ile Sass değişkenleri arasındaki temel fark nedir?','CSS custom properties (`--color: red`) runtime''da JavaScript ile değiştirilebilir ve cascade/inheritance kurallarına tabidir. Sass/Less değişkenleri derleme zamanında statik olarak yerine yazılır; JavaScript erişimi yoktur.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'CSS custom properties yalnızca renk tanımlamak için kullanılabilir; Sass her değer için geçerlidir' FROM q UNION ALL SELECT id,1,'Sass değişkenleri runtime''da değiştirilebilir; CSS custom properties yalnızca statiktir' FROM q UNION ALL SELECT id,2,'CSS custom properties yalnızca modern tarayıcılarda çalışır; Sass IE11 dahil desteklenir' FROM q UNION ALL SELECT id,3,'CSS custom properties runtime''da değiştirilebilir ve cascade''e tabidir; Sass/Less derleme zamanında statik olarak yazılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','senior','React Fiber mimarisinin getirdiği en önemli yenilik nedir?','React Fiber, render işini küçük birimlere (fiber) bölerek öncelik tabanlı, kesintiye uğrayabilen bir çalışma modeli sunar. Yüksek öncelikli güncellemeler (kullanıcı etkileşimi) düşük öncerikli olanları geciktirebilir. Concurrent Mode''un temeli budur.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Render işini kesintiye uğrayabilen öncelik tabanlı fiber birimlerine böler; Concurrent Mode''u mümkün kılar' FROM q UNION ALL SELECT id,1,'Virtual DOM''u tamamen ortadan kaldırarak doğrudan gerçek DOM üzerinde çalışır' FROM q UNION ALL SELECT id,2,'Tüm state yönetimini Web Worker''a taşıyarak main thread''i boşaltır' FROM q UNION ALL SELECT id,3,'Yalnızca class component''leri optimize eder; functional component''ler eski algoritmayı kullanır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','senior','XSS saldırılarına karşı frontend''de alınabilecek en etkili önlemler nelerdir?','XSS''e karşı: kullanıcı girdisi HTML''e yazılmadan encode/escape edilmeli, `innerHTML` yerine `textContent` kullanılmalı, Content-Security-Policy header ile script kaynakları kısıtlanmalı, `dangerouslySetInnerHTML` minimum tutulmalıdır. React varsayılan olarak JSX değerlerini escape eder.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Tüm HTTP trafiğini HTTPS''e yönlendirmek ve SameSite cookie flag eklemek yeterlidir' FROM q UNION ALL SELECT id,1,'Kullanıcı girdisini HTML''e yazmadan önce escape etmek, CSP header uygulamak ve innerHTML kullanmaktan kaçınmak' FROM q UNION ALL SELECT id,2,'SQL injection filtreleri XSS''i de kapsar; ayrıca frontend''de ek önlem gerekmez' FROM q UNION ALL SELECT id,3,'localStorage yerine sessionStorage kullanmak XSS etkisini tamamen ortadan kaldırır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','senior','Web Worker nedir ve main thread ile nasıl iletişim kurar?','Web Worker, tarayıcıda main thread''ten bağımsız background thread çalıştırır. Yoğun CPU işlemlerini offload eder ve UI''nin donmasını engeller. İletişim `postMessage`/`onmessage` API''si üzerinden asenkron mesaj geçişiyle sağlanır; DOM erişimi yoktur.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Tarayıcının ağ isteklerini paralel işleyen ve Service Worker''ın yerini alan bir API''dir' FROM q UNION ALL SELECT id,1,'Node.js Worker Threads''in tarayıcı karşılığı olup DOM''a tam erişim sağlar' FROM q UNION ALL SELECT id,2,'Main thread''ten bağımsız background thread''de çalışır; postMessage ile iletişim kurar, DOM''a erişemez' FROM q UNION ALL SELECT id,3,'React Concurrent Mode''u aktif eden ve render önceliklerini yöneten dahili bir mekanizmadır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','senior','React Server Components (RSC) ile Client Components arasındaki mimari fark nedir?','RSC sunucuda render edilir ve hiç JS bundle''a dahil edilmez; veri tabanına doğrudan erişebilir. Client Components ise tarayıcıda interaktiflik sağlar (state, event handler). RSC çıktısı serialized React tree''dir, HTML değil. RSC Client Component içine import edilemez.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'RSC yalnızca static sayfalarda kullanılabilir; dinamik veri gerektiren sayfalarda Client Component zorunludur' FROM q UNION ALL SELECT id,1,'RSC ile CSR arasındaki tek fark hydration adımıdır; bundle boyutları aynıdır' FROM q UNION ALL SELECT id,2,'RSC SSR ile aynıdır; fark yalnızca cache davranışında ortaya çıkar' FROM q UNION ALL SELECT id,3,'RSC sunucuda çalışır ve JS bundle''a eklenmez; Client Component tarayıcıda interaktiflik için gereklidir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','senior','React hook''larında memory leak''e yol açan yaygın bir senaryo ve çözümü nedir?','Unmount olan component''in async işlemi tamamlandığında setState çağrılmaya devam edebilir. `useEffect` cleanup fonksiyonunda AbortController ile fetch iptal edilmeli ya da isMounted flag kullanılmalıdır. AbortController tercih edilen yaklaşımdır; hem fetch''i hem de callback''i temizler.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Unmount sonrası async callback setState çağırır; cleanup''ta AbortController ile iptal edilmeli' FROM q UNION ALL SELECT id,1,'useState yerine useReducer kullanmak memory leak''in tek kaynağıdır' FROM q UNION ALL SELECT id,2,'Memory leak yalnızca class component''lerin componentDidMount metodunda oluşur' FROM q UNION ALL SELECT id,3,'React.StrictMode geliştirme ortamında ek render yaptığı için memory leak''e neden olur; production''da sorun yoktur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','senior','Service Worker ile HTTP cache (Cache-Control) arasındaki temel fark nedir?','HTTP cache tarayıcı tarafından otomatik yönetilir. Service Worker ise kendi yazdığınız JavaScript''tir; cache stratejisini tam kontrol edersiniz (network-first, cache-first, stale-while-revalidate). Offline destek, push notification ve background sync yalnızca Service Worker ile mümkündür.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'HTTP cache yalnızca GET isteklerini, Service Worker ise tüm HTTP metodlarını önbelleğe alır' FROM q UNION ALL SELECT id,1,'HTTP cache tarayıcı tarafından otomatik yönetilir; Service Worker özel cache stratejisi ve offline destek sağlar' FROM q UNION ALL SELECT id,2,'Service Worker yalnızca PWA''larda geçerlidir; normal web sitelerinde HTTP cache kullanılmalıdır' FROM q UNION ALL SELECT id,3,'Service Worker ve HTTP cache aynı Cache Storage''ı paylaşır; ikisi birbirinin yerine kullanılabilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','senior','TypeScript''te generic conditional type içinde `infer` ne işe yarar?','`infer`, conditional type içinde bir pattern''dan tür çıkarımı yapmak için kullanılır. Örneğin `ReturnType<T>`: `T extends (...args: any[]) => infer R ? R : never`. Başka türlü ifade edilemeyen tip çıkarımlarını mümkün kılar.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Generic''lerin çalışma zamanında tip bilgisini koruyarak reflection yapmayı sağlar' FROM q UNION ALL SELECT id,1,'TypeScript derleyicisine belirtilen tipin kesin (non-nullable) olduğunu garantiler' FROM q UNION ALL SELECT id,2,'Conditional type içinde bir pattern''dan otomatik tip çıkarımı yapar; ReturnType gibi utility tiplerin yapı taşıdır' FROM q UNION ALL SELECT id,3,'Template literal tiplerde dinamik string birleştirme işlemlerini tip güvenli hale getirir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','senior','React''ta `useTransition` hook''u hangi problemi çözer?','`useTransition` state güncellemelerini urgent ve non-urgent olarak ayırır. Kullanıcı etkileşimi (typing) urgent; sonuç listesi güncellemesi non-urgent işaretlenebilir. Böylece ağır render işlemleri kullanıcı girdisini bloklamaz.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Animasyon geçişlerini CSS transition''a gerek kalmadan JavaScript ile yönetir' FROM q UNION ALL SELECT id,1,'Route değişikliklerinde sayfa geçişlerini Suspense ile eşzamanlı hale getirir' FROM q UNION ALL SELECT id,2,'useState''in asenkron versiyonu olup Promise döndüren state güncellemeleri için kullanılır' FROM q UNION ALL SELECT id,3,'Non-urgent state güncellemelerini işaretler; ağır render''lar kullanıcı etkileşimini bloklamaz' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','senior','Tarayıcıda "layout thrashing" nedir ve nasıl önlenir?','Layout thrashing, JavaScript''in sıralı DOM yazma ve okuma işlemlerini karıştırması sonucu tarayıcının her okuma öncesinde layout hesaplamak zorunda kalmasıdır. Önlemek için tüm okumalar toplu yapılmalı, ardından yazmalara geçilmeli; `requestAnimationFrame` kullanılabilir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'JS''in DOM okuma/yazma işlemlerini karıştırması nedeniyle tarayıcının zoraki layout hesaplaması; toplu okuma/yazma ile önlenir' FROM q UNION ALL SELECT id,1,'Çok fazla CSS transition aynı anda çalışınca GPU katmanlarının tükenmesi ve render''ın yavaşlaması' FROM q UNION ALL SELECT id,2,'JavaScript heap''inin fragment olması ve GC''nin render pipeline''ını duraklayarak çöp toplaması' FROM q UNION ALL SELECT id,3,'CSS Grid ve Flexbox''ın aynı anda kullanılmasıyla ortaya çıkan çakışan layout hesaplamaları' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','senior','Micro-frontend mimarisinin temel avantajı ve dezavantajı nedir?','Micro-frontend''ler büyük ekiplerin bağımsız deploy etmesine, farklı framework kullanmasına ve failure isolation sağlamasına imkân tanır. Ancak bundle boyutu büyüyebilir, UI tutarsızlığı riski artar ve routing/state paylaşımı karmaşıklaşır.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Bundle boyutunu otomatik küçültür ve tek bir framework''e bağımlılığı tamamen ortadan kaldırır' FROM q UNION ALL SELECT id,1,'Ekiplerin bağımsız deploy etmesini sağlar; ancak artan bundle boyutu ve UI tutarsızlığı riski dezavantajdır' FROM q UNION ALL SELECT id,2,'SEO''yu iyileştirir ve monolith''e kıyasla her zaman daha düşük latency sağlar' FROM q UNION ALL SELECT id,3,'Yalnızca React 18+ ile çalışır; eski framework''lerde uygulanması teknik olarak imkânsızdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','senior','Content Security Policy (CSP) header inline script''leri nasıl etkiler?','CSP, tarayıcıya hangi kaynakların script/style yükleyebileceğini söyleyen bir HTTP header''dır. Varsayılan olarak inline script ve style''ları engeller; XSS vektörünü etkili biçimde kapatır. İzin vermek için `nonce` veya `hash` değeri kullanılır; `unsafe-inline` CSP''nin faydasını büyük ölçüde azaltır.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'CSP yalnızca CORS politikalarını uygular; inline script''leri etkilemez' FROM q UNION ALL SELECT id,1,'CSP tüm dış kaynak yüklemelerini engeller; yalnızca same-origin script''lere izin verir' FROM q UNION ALL SELECT id,2,'CSP izin verilen script kaynaklarını tanımlar; inline script''leri varsayılan olarak engeller, nonce/hash ile açılabilir' FROM q UNION ALL SELECT id,3,'CSP cookie''lerin Secure ve HttpOnly flag''lerini otomatik olarak ayarlar' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','mid','Webpack''te tree shaking nedir?','Tree shaking, kullanılmayan ES module export''larını bundle''dan çıkarmaktır. ES module statik yapısı sayesinde bundler derleme zamanında hangi export''ların kullanıldığını analiz eder. CommonJS dinamik olduğu için tree shaking desteklemez. `sideEffects: false` ayarı optimizasyonu güçlendirir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Büyük node_modules klasörlerini runtime''da kırpan disk alanı azaltan bir npm script''tir' FROM q UNION ALL SELECT id,1,'CSS seçicilerini otomatik temizleyip kullanılmayan stilleri silen PostCSS eklentisidir' FROM q UNION ALL SELECT id,2,'JavaScript''teki döngüleri optimize edip gereksiz iterasyonları kaldıran JIT compiler özelliğidir' FROM q UNION ALL SELECT id,3,'Kullanılmayan ES module export''larını statik analiz ile tespit edip bundle''dan çıkaran optimizasyon tekniğidir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','mid','CSS BEM metodolojisinde Block, Element ve Modifier ne anlama gelir?','BEM: Block (bağımsız UI bileşeni, örn `.card`), Element (block''un parçası, `__` ile ayrılır: `.card__title`), Modifier (farklı durum/varyant, `--` ile ayrılır: `.card--featured`). Sınıf çakışmalarını önler ve stillerin kapsamını netleştirir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Block bağımsız bileşen, Element block''un alt parçası (__), Modifier farklı durum veya varyantı (--) temsil eder' FROM q UNION ALL SELECT id,1,'Block HTML elementi, Element CSS sınıfı, Modifier JavaScript davranışını temsil eder' FROM q UNION ALL SELECT id,2,'Block margin/padding grubunu, Element iç içeriği, Modifier hover/focus gibi pseudo-state''leri temsil eder' FROM q UNION ALL SELECT id,3,'BEM yalnızca Sass ile kullanılabilir; pure CSS''te Block/Element/Modifier ayrımı yapılamaz' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','junior','`Array.prototype.map()` ile `Array.prototype.forEach()` arasındaki fark nedir?','`map()` her eleman için callback sonucunu toplayarak yeni dizi döndürür; orijinal dizi değişmez. `forEach()` ise yalnızca yan etki için kullanılır, `undefined` döndürür. Dizi dönüştürme için `map`, sadece iterasyon için `forEach` tercih edilmelidir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'map() orijinal diziyi değiştirir; forEach() yeni dizi döndürür' FROM q UNION ALL SELECT id,1,'map() yeni dizi döndürür; forEach() yalnızca yan etki için kullanılır ve undefined döner' FROM q UNION ALL SELECT id,2,'forEach() daha hızlıdır; map() yalnızca nesne dizilerinde kullanılır' FROM q UNION ALL SELECT id,3,'İkisi aynı işi yapar; map() sadece zincir kullanımında tercih edilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('frontend','tr','junior','React''ta `key` prop olarak array index kullanmanın sorunlu olduğu durum hangisidir?','Index key, liste sırası değişmediği sürece sorun yaratmaz. Ancak öğeler sıralandığında, filtrelendiğinde veya ortadan silindiğinde index''ler kayar ve React yanlış component''i eşleştirir. Form alanlarında veri kaybına ya da animasyonların hatalı çalışmasına yol açar.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Index kullanımı her durumda sorunludur; her zaman UUID gibi benzersiz değer kullanılmalıdır' FROM q UNION ALL SELECT id,1,'Index yalnızca 100''den fazla elemanlı listelerde sorun yaratır; küçük listelerde güvenlidir' FROM q UNION ALL SELECT id,2,'Liste öğeleri sıralandığında veya ortadan silindiğinde index kayar; React yanlış elemanla eşleşir' FROM q UNION ALL SELECT id,3,'Index key olarak kullanılamaz; React kesinlikle string veya UUID bekler' FROM q;

