-- BACKEND (+40 soru)
-- ══════════════════════════════════════════

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','junior','HTTP 4xx ve 5xx hata kodları arasındaki temel fark nedir?','4xx hataları istemci tarafı hataları olduğunu belirtir (yanlış istek, yetkisiz erişim, kaynak bulunamadı). 5xx hataları ise sunucu tarafında bir sorun olduğunu gösterir (iç hata, servis kullanılamıyor). Bu ayrım hata ayıklamada kritik yönlendirme sağlar.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'4xx istemci hatalarını, 5xx sunucu hatalarını ifade eder' FROM q UNION ALL SELECT id,1,'4xx sunucu hatalarını, 5xx istemci hatalarını ifade eder' FROM q UNION ALL SELECT id,2,'4xx geçici, 5xx kalıcı hatalar için kullanılır' FROM q UNION ALL SELECT id,3,'4xx ve 5xx aynı kategoridedir; yalnızca önem derecesi farklıdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','junior','REST API''de URL tasarımında doğru kaynak adlandırma kuralı hangisidir?','REST''te URL''ler kaynakları temsil eder ve isim olmalıdır (fiil değil). Çoğul isim kullanımı yaygındır: `/users`, `/orders`. Eylem HTTP metoduyla belirtilir: GET /users (listele), POST /users (oluştur). `/getUsers` veya `/createUser` gibi fiil içeren URL''ler RESTful değildir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'URL fiil içermelidir: /getUsers, /createOrder gibi endpoint isimleri tercih edilir' FROM q UNION ALL SELECT id,1,'URL kaynak ismi (çoğul isim) içermelidir: /users, /orders; eylem HTTP metoduyla belirtilir' FROM q UNION ALL SELECT id,2,'Her endpoint benzersiz olduğu sürece herhangi bir isimlendirme kabul edilebilir' FROM q UNION ALL SELECT id,3,'URL''ler tekil isim içermelidir: /user, /order; çoğul kullanım hata sınıfına girer' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','junior','JWT token üç bölümden oluşur. Bu bölümler hangileridir?','JWT (JSON Web Token) yapısı: Header (algoritma ve token tipi), Payload (claim''ler: kullanıcı id, rol, exp gibi veriler) ve Signature (header + payload''ın secret ile HMAC ya da RSA ile imzalanması). Nokta ile ayrılır: xxxxx.yyyyy.zzzzz.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Username, Password ve ExpiryDate bölümlerinden oluşur; base64 ile şifrelenir' FROM q UNION ALL SELECT id,1,'PublicKey, PrivateKey ve Signature bölümlerinden oluşur; RSA algoritması zorunludur' FROM q UNION ALL SELECT id,2,'Header (algoritma/tip), Payload (claim''ler) ve Signature (imza) bölümlerinden oluşur' FROM q UNION ALL SELECT id,3,'Token, RefreshToken ve SessionId bölümlerinden oluşur; sunucuda saklanır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','junior','Backend''de middleware nedir ve ne işe yarar?','Middleware, istek (request) ile yanıt (response) arasında çalışan, isteği işleyen veya dönüştüren fonksiyonlardır. Kimlik doğrulama, loglama, rate limiting, CORS başlıkları ekleme ve hata yönetimi gibi çapraz (cross-cutting) kaygılar middleware ile merkezi olarak yönetilir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Veritabanı ile uygulama katmanı arasındaki ORM bağlantısını yöneten katmandır' FROM q UNION ALL SELECT id,1,'Frontend ile backend arasındaki veri formatını (JSON/XML) dönüştüren servis katmanıdır' FROM q UNION ALL SELECT id,2,'Microservice''ler arasındaki mesaj iletişimini sağlayan mesaj kuyruğu aracıdır' FROM q UNION ALL SELECT id,3,'İstek ile yanıt arasında çalışan; kimlik doğrulama, loglama, CORS gibi çapraz kaygıları yöneten fonksiyonlardır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','junior','HTTP metodlarından GET ve POST arasındaki semantic fark nedir?','GET idempotent ve güvenlidir (safe): sunucu durumunu değiştirmez, parametreler URL''dedir, önbelleklenebilir. POST idempotent değildir: sunucuda kaynak oluşturur veya işlem tetikler, veriler body''de taşınır. GET ile veri değiştirme REST anti-pattern''idir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'GET okuma ve önbellekleme için kullanılır, idempotent ve safe''dir; POST sunucu durumunu değiştiren işlemler için kullanılır' FROM q UNION ALL SELECT id,1,'GET body taşıyabilir, POST ise yalnızca URL parametresi kabul eder' FROM q UNION ALL SELECT id,2,'GET ve POST aynı işlevi görür; tek fark veri transfer kapasitesidir' FROM q UNION ALL SELECT id,3,'POST güvenlidir ve önbelleklenir; GET ise her zaman sunucu durumunu değiştirir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','junior','HTTP''de idempotency ne demektir?','İdempotent bir istek, aynı parametrelerle birden fazla kez gönderildiğinde sunucu üzerinde aynı etkiyi üretir. GET, PUT ve DELETE idempotentdir. POST genellikle değildir (her çağrıda yeni kaynak oluşturabilir). Ödeme gibi kritik işlemlerde idempotency key kullanılır.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Her isteğin sunucuya yalnızca bir kez ulaşmasını garantileyen protokol özelliğidir' FROM q UNION ALL SELECT id,1,'Aynı isteğin birden fazla gönderilmesinin sunucu üzerinde tek seferlik etki bırakmasıdır' FROM q UNION ALL SELECT id,2,'İstemci ve sunucu arasındaki bağlantı kesilirse isteğin otomatik tekrar gönderilmesidir' FROM q UNION ALL SELECT id,3,'Yalnızca güvenli (HTTPS) bağlantılarda geçerli olan istek tekrarlama mekanizmasıdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','junior','Authentication (kimlik doğrulama) ve Authorization (yetkilendirme) arasındaki fark nedir?','Authentication "Sen kimsin?" sorusunu yanıtlar; kullanıcının kimliğini doğrular (login). Authorization "Ne yapabilirsin?" sorusunu yanıtlar; kimliği doğrulanmış kullanıcının hangi kaynaklara erişebileceğini belirler. Authentication her zaman authorization''dan önce gelir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Authentication yetki kontrolü, Authorization ise kimlik doğrulamadır' FROM q UNION ALL SELECT id,1,'İkisi aynı kavramdır; yalnızca farklı sistemlerde farklı terimler kullanılır' FROM q UNION ALL SELECT id,2,'Authentication kimlik doğrulama (kim olduğunu kanıtlama), Authorization ise erişim izin kontrolüdür' FROM q UNION ALL SELECT id,3,'Authentication sunucu tarafında, Authorization istemci tarafında gerçekleşir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','junior','Stateless API ne demektir ve REST ile ilişkisi nedir?','Stateless API''de sunucu, istekler arasında istemci durumunu saklamaz. Her istek, işlenmesi için gerekli tüm bilgiyi (token, parametreler) kendi içinde taşır. REST''in temel kısıtlamalarından biridir; yatay ölçeklendirmeyi kolaylaştırır çünkü herhangi bir sunucu herhangi bir isteği işleyebilir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Sunucunun hiçbir veri saklamaması ve veritabanı kullanmaması anlamına gelir' FROM q UNION ALL SELECT id,1,'Her istek için yeni bir TCP bağlantısı kurulması ve kapanması anlamına gelir' FROM q UNION ALL SELECT id,2,'İstemcinin sunucu hakkında hiçbir bilgi tutmaması ve her seferinde yeniden keşif yapması anlamına gelir' FROM q UNION ALL SELECT id,3,'Sunucunun istemci durumunu saklamadığı; her isteğin gerekli tüm bilgiyi kendi içinde taşıdığı mimaridir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','junior','HTTP 401 Unauthorized ve 403 Forbidden arasındaki fark nedir?','401: Kullanıcı kimliği doğrulanmamıştır (token eksik veya geçersiz); yeniden giriş yapılabilir. 403: Kimlik doğrulanmıştır ancak bu kaynağa erişim izni yoktur; giriş yapmak sonucu değiştirmez. Güvenlik açısından, kaynağın varlığını gizlemek için bazen 404 tercih edilir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'401 kimlik doğrulama eksikliğini (giriş yapılmamış), 403 ise kimlik doğrulanmış ama yetkisiz erişimi ifade eder' FROM q UNION ALL SELECT id,1,'401 sunucu hatası, 403 ise istemci hatası kategorisindedir' FROM q UNION ALL SELECT id,2,'401 geçici yasak, 403 ise kalıcı yasak anlamına gelir' FROM q UNION ALL SELECT id,3,'İkisi arasında teknik fark yoktur; tercih projenin konvansiyonuna bırakılmıştır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','junior','ORM (Object-Relational Mapping) nedir ve avantajları nelerdir?','ORM, uygulama nesneleri ile veritabanı tabloları arasındaki dönüşümü otomatikleştiren katmandır. SQL yazmadan nesne yönelimli kod ile sorgu yapılmasını sağlar. Avantajları: üretkenlik, veritabanı bağımsızlığı. Dezavantajları: N+1 sorunu riski ve karmaşık sorgularda ham SQL kadar esnek olmayabilir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Farklı veritabanları arasında gerçek zamanlı veri senkronizasyonu sağlayan bir araçtır' FROM q UNION ALL SELECT id,1,'Uygulama nesnelerini veritabanı tablolarına eşleştiren; SQL yazmadan nesne yönelimli sorgu yapılmasını sağlayan katmandır' FROM q UNION ALL SELECT id,2,'Veritabanı şemasını kod değişikliklerine göre otomatik güncelleyen migration aracıdır' FROM q UNION ALL SELECT id,3,'Yalnızca NoSQL veritabanlarıyla çalışan, şema gerektirmeyen veri erişim katmanıdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','junior','HTTPS''in HTTP''ye göre sağladığı temel güvenlik avantajı nedir?','HTTPS, HTTP trafiğini TLS (Transport Layer Security) ile şifreler. Üç temel güvence sağlar: gizlilik (veri şifreli), bütünlük (veri değiştirilmemiş) ve kimlik doğrulama (sunucu sertifika ile kanıtlanmış). Ortadaki adam (MITM) saldırılarını önler.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'HTTPS yalnızca sunucunun IP adresini gizler; veri içeriği hâlâ düz metin olarak iletilir' FROM q UNION ALL SELECT id,1,'HTTPS yalnızca kullanıcı şifrelerini şifreler; diğer veriler HTTP ile aynı şekilde iletilir' FROM q UNION ALL SELECT id,2,'TLS ile trafiği şifreler; gizlilik, bütünlük ve sunucu kimlik doğrulaması sağlar, MITM saldırılarını önler' FROM q UNION ALL SELECT id,3,'HTTPS yalnızca ödeme sayfalarında zorunludur; diğer sayfalarda HTTP ile fark yoktur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','junior','REST API''de veri döndürürken JSON''u XML''e göre tercih etmenin yaygın nedeni nedir?','JSON daha hafif (az byte), JavaScript ile doğal uyumlu ve daha okunabilirdir. XML daha verbose ve belirli durumlarda (SOAP, kurumsal sistemler, namespace gerektiren format) hâlâ tercih edilir. Modern REST API''lerin büyük çoğunluğu varsayılan olarak JSON kullanır.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'JSON şifreleme özelliği sayesinde XML''den daha güvenlidir' FROM q UNION ALL SELECT id,1,'JSON yalnızca GET isteklerinde çalışır; POST için XML zorunludur' FROM q UNION ALL SELECT id,2,'JSON veritabanı ile doğrudan uyumlu olduğu için ekstra dönüşüm gerektirmez' FROM q UNION ALL SELECT id,3,'JSON daha hafif, JavaScript ile doğal uyumlu ve okunabilirdir; modern REST API''lerin tercihi budur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','mid','JWT tabanlı auth ile session tabanlı auth arasındaki temel fark nedir?','JWT stateless''tir: token''ı istemci saklar, sunucuda session kaydı yoktur; yatay ölçeklendirme kolaylığı sağlar. Session tabanlı auth''da sunucu session''ı saklar (genellikle Redis); token iptal etmek kolaydır. JWT''de token''ı iptal etmek için kara liste (blacklist) veya kısa ömür gerekir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'JWT stateless olup istemcide saklanır; session based sunucuda session kaydı tutar, iptal etmek daha kolaydır' FROM q UNION ALL SELECT id,1,'JWT daha güvenlidir çünkü sunucuda şifreli olarak saklanır; session düz metin tutar' FROM q UNION ALL SELECT id,2,'Session tabanlı auth JWT''den daha hızlıdır çünkü veritabanı sorgusu yapmaz' FROM q UNION ALL SELECT id,3,'İkisi arasında teknik fark yoktur; yalnızca istemci tarafı implementasyon detayları farklıdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','mid','OAuth 2.0 Authorization Code flow''da neden client secret istemci tarafında saklanmamalıdır?','Client secret, authorization server ile token değişiminde kullanılan gizli anahtardır. Mobil uygulama veya SPA''da kaynak kodu incelenebilir veya reverse-engineer edilebilir; secret açığa çıkar. Bu nedenle bu client tipleri "confidential" değil "public" client sayılır; PKCE kullanılmalıdır.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Client secret yalnızca access token yenilemede kullanılır; istemcide saklanması güvenlidir' FROM q UNION ALL SELECT id,1,'Mobil/SPA kaynak kodu incelenebileceğinden secret açığa çıkar; bu client''lar public client olmalı, PKCE kullanmalıdır' FROM q UNION ALL SELECT id,2,'Client secret istemcide saklanmalıdır; sunucuda saklamak man-in-the-middle saldırısına açık hale getirir' FROM q UNION ALL SELECT id,3,'OAuth 2.0 client secret kavramı yalnızca SAML ile çalışır; modern sistemlerde kullanılmaz' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','mid','Backend''de Redis hangi durumlarda tercih edilir?','Redis bellek içi (in-memory) veri yapısı deposudur. Yaygın kullanım alanları: oturum (session) yönetimi, dağıtık önbellek (cache), rate limiting sayaçları, pub/sub mesajlaşma, iş kuyruğu (job queue) ve leaderboard. Yüksek okuma/yazma hızı ile düşük gecikme gerektiğinde tercih edilir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Büyük dosyaların depolanması için kullanılır; blob storage alternatifidir' FROM q UNION ALL SELECT id,1,'Yalnızca pub/sub mesajlaşma için kullanılır; önbellek işlevi yoktur' FROM q UNION ALL SELECT id,2,'In-memory hız gerektiren durumlarda kullanılır: oturum yönetimi, dağıtık önbellek, rate limiting, job queue' FROM q UNION ALL SELECT id,3,'PostgreSQL''in performansını artırmak için aynı şemayı paylaşarak çalışan bir replika aracıdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','mid','Rate limiting''de token bucket algoritması nasıl çalışır?','Token bucket: bir kova belirli kapasitede token tutar; her istek bir token tüketir. Token''lar sabit hızda yenilenir. Kova doluysa yeni token eklenmez; boşsa istek reddedilir. Burst trafiğe izin verir (kovada biriken token''lar) ama ortalama hız sınırlanır. Redis ile dağıtık implementasyonu kolaydır.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Her IP için sabit zaman penceresinde istek sayısını sayar; pencere bitince sıfırlar' FROM q UNION ALL SELECT id,1,'İstekler kuyruğa alınır; kuyruk dolunca yeni istekler hemen reddedilir' FROM q UNION ALL SELECT id,2,'Sliding window kullanır; her istek zaman damgası ile kaydedilir, eski kayıtlar temizlenir' FROM q UNION ALL SELECT id,3,'Kova sabit kapasitede token tutar; istek token tüketir, sabit hızda yenilenir; burst trafiğe izin verir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','mid','Message queue (RabbitMQ, Kafka) kullanmanın doğrudan HTTP çağrısına göre avantajı nedir?','Message queue: asenkron işlem (producer cevap beklemez), geçici yük artışını tamponlama, servisler arası gevşek bağlantı (loose coupling), hata durumunda retry mekanizması ve işlemlerin kalıcılığı (durability). Ödeme bildirimi, e-posta gönderimi gibi background işlemler için idealdir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Asenkron işlem, yük tamponlama, loose coupling ve hata durumunda otomatik retry sağlar' FROM q UNION ALL SELECT id,1,'HTTP''den daha hızlı veri transferi sağlar çünkü şifreleme yapmaz' FROM q UNION ALL SELECT id,2,'Mesajları şifreli gönderip istemci kimlik doğrulamasını otomatik yönetir' FROM q UNION ALL SELECT id,3,'Yalnızca aynı ağdaki servisler arasında kullanılabilir; internet üzerinden çalışmaz' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','mid','API versiyonlama stratejilerinden URI versiyonlama ve Header versiyonlama arasındaki fark nedir?','URI versiyonlama (/api/v1/users): URL''de açıkça görünür, önbelleklenebilir, tarayıcıda test kolaydır; URL kirliliği dezavantajı vardır. Header versiyonlama (Accept: application/vnd.api+v2+json): URL temiz kalır, ancak test etmesi ve keşfedilmesi zorlaşır. İkisi de geçerlidir; URI versiyonlama daha yaygındır.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'URI versiyonlama güvensizdir çünkü versiyon bilgisi URL''de açık görünür' FROM q UNION ALL SELECT id,1,'URI versiyonlama (/v1/users) URL''de açıktır ve önbelleklenir; header versiyonlama URL''i temiz tutar ama test zorlaşır' FROM q UNION ALL SELECT id,2,'Header versiyonlama RFC standardı olduğu için her zaman URI versiyonlamadan üstündür' FROM q UNION ALL SELECT id,3,'Versiyonlama yalnızca breaking change''lerde gereklidir; küçük güncellemelerde versiyon değiştirilmez' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','mid','Cursor tabanlı pagination ile offset tabanlı pagination arasındaki fark nedir?','Offset pagination (LIMIT/OFFSET): kolay implemente edilir ancak büyük offset değerlerinde performans düşer ve veri eklenince sayfa kayması oluşur. Cursor pagination: son görülen kaydın id/tarih değerini cursor olarak kullanır; büyük veri setlerinde tutarlı ve performanslıdır. Sosyal medya feed''leri cursor kullanır.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Offset pagination tutarlıdır; cursor pagination ise yalnızca MongoDB ile çalışır' FROM q UNION ALL SELECT id,1,'Cursor pagination sayfalar arası atlama (page jump) destekler; offset ise yalnızca sıralı gezinmeye izin verir' FROM q UNION ALL SELECT id,2,'Offset büyük veri setlerinde performans kaybı ve veri kayması yaşar; cursor tutarlı ve performanslıdır' FROM q UNION ALL SELECT id,3,'İkisi arasında performans farkı yoktur; cursor yalnızca UI kolaylığı için tercih edilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','mid','Circuit breaker pattern nedir ve ne zaman kullanılır?','Circuit breaker, bir servis çağrısındaki hata oranı eşiği aşınca "open" (devre açık) duruma geçer ve sonraki çağrıları hemen reddeder; bu sayede cascading failure önlenir. Belirli süre sonra "half-open" durumda test çağrısı yapar; başarılıysa "closed" (normal) duruma döner.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Gelen istekleri birden fazla servis örneğine eşit dağıtan yük dengeleme algoritmasıdır' FROM q UNION ALL SELECT id,1,'Veritabanı bağlantısı kesildiğinde isteği otomatik olarak önbelleğe yönlendiren mekanizmadır' FROM q UNION ALL SELECT id,2,'API rate limit aşıldığında istekleri kuyruğa alıp yavaşlatarak trafik şekillendiren algoritmadır' FROM q UNION ALL SELECT id,3,'Hata oranı eşiği aşınca sonraki çağrıları hemen reddeden; cascading failure''ı önleyen pattern''dir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','mid','Dependency injection (DI) ne sağlar?','DI, bir nesnenin bağımlılıklarını kendi oluşturmak yerine dışarıdan almasıdır. Avantajları: loose coupling, test edilebilirlik (mock enjeksiyonu), tek sorumluluk ilkesine uyum ve bağımlılıkların merkezi yönetimi. Spring, .NET Core, NestJS gibi framework''ler DI container sağlar.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Nesnelerin bağımlılıklarını dışarıdan almasını sağlar; loose coupling, test edilebilirlik ve merkezi yönetim kazanılır' FROM q UNION ALL SELECT id,1,'Veritabanı bağlantı havuzunu yöneterek her istekte yeni bağlantı açılmasını engeller' FROM q UNION ALL SELECT id,2,'Frontend''den gelen veriyi otomatik olarak doğrulayıp model nesnesine dönüştürür' FROM q UNION ALL SELECT id,3,'Servislerin birbirinin IP adresini bilmeden iletişim kurmasını sağlayan servis keşif mekanizmasıdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','mid','Webhook ile polling arasındaki fark nedir?','Polling: istemci belirli aralıkla sunucuyu sorgular (değişiklik var mı?); basit ama verimsiz. Webhook: olay gerçekleştiğinde sunucu istemcinin URL''ine HTTP POST gönderir; anlık bildirim sağlar, sunucu kaynaklarını korur. Webhook güvenilirliği için retry mekanizması ve imza doğrulaması gerekir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Polling gerçek zamanlı, webhook ise gecikmeli bildirim sağlar' FROM q UNION ALL SELECT id,1,'Polling istemcinin periyodik sorgulaması; webhook ise olay gerçekleşince sunucunun istemciyi bildirmesidir' FROM q UNION ALL SELECT id,2,'Webhook yalnızca ödeme sistemlerinde kullanılır; genel API''ler polling kullanmak zorundadır' FROM q UNION ALL SELECT id,3,'İkisi de aynı sonucu üretir; fark yalnızca implementasyon tercihidir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','mid','SOLID prensiplerinden Single Responsibility Principle (SRP) ne demektir?','SRP: Bir sınıf veya modülün değişmesi için yalnızca bir nedeni olmalıdır. Başka bir deyişle, bir sınıf yalnızca tek bir iş yapmalıdır. UserService hem kullanıcı işlemlerini hem e-posta göndermeyi yönetiyorsa SRP ihlal edilmiştir; email işlemleri ayrı servise taşınmalıdır.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Her sınıfın yalnızca bir public metodu olması gerektiği kuralıdır' FROM q UNION ALL SELECT id,1,'Bir interface''in yalnızca bir metot tanımlayabileceği kısıtlamasıdır' FROM q UNION ALL SELECT id,2,'Bir sınıfın değişmesi için yalnızca tek bir nedeninin olması; tek bir sorumluluğu kapsaması gerektiğidir' FROM q UNION ALL SELECT id,3,'Her veritabanı tablosunun yalnızca bir sınıf tarafından erişilebilir olmasını zorunlu kılan kuraldır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','mid','Veritabanı connection pooling neden önemlidir?','Her istek için yeni TCP bağlantısı açmak pahalıdır (TLS handshake, authentication). Connection pool önceden oluşturulmuş bağlantıları hazır tutar; istek gelince havuzdan alınır, biter bitmez geri verilir. Gecikmeyi azaltır, maksimum bağlantı sayısını sınırlar ve veritabanını korur.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Birden fazla veritabanını tek bağlantı noktasından yönetmek için kullanılır' FROM q UNION ALL SELECT id,1,'Veritabanı şifrelemesini yöneterek TLS handshake süresini ortadan kaldırır' FROM q UNION ALL SELECT id,2,'Farklı veritabanı sistemleri arasında veri senkronizasyonu sağlar' FROM q UNION ALL SELECT id,3,'Pahalı bağlantı kurma maliyetini azaltır; önceden oluşturulan bağlantıları havuzda tutarak yeniden kullanır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','senior','CQRS (Command Query Responsibility Segregation) pattern ne sağlar?','CQRS, okuma (Query) ve yazma (Command) modellerini birbirinden ayırır. Yazma modeli domain logic ve validasyon; okuma modeli ise performans için optimize edilmiş projeksiyonlar içerebilir. Farklı veritabanları kullanılabilir (write: normalized SQL, read: denormalized/NoSQL). Event sourcing ile sıkça birlikte kullanılır.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Okuma ve yazma modellerini ayırır; her biri bağımsız optimize edilebilir, farklı storage kullanılabilir' FROM q UNION ALL SELECT id,1,'SQL sorgularını otomatik olarak önbelleğe alıp tekrar gelen sorguları veritabanına iletmeyen bir proxy pattern''dir' FROM q UNION ALL SELECT id,2,'Yalnızca SELECT sorgularına izin verilen read-only veritabanı replikası kurulum stratejisidir' FROM q UNION ALL SELECT id,3,'API endpoint''lerini GET (query) ve POST/PUT/DELETE (command) olarak iki controller''a bölen MVC varyasyonudur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','senior','Event sourcing''de veri nasıl saklanır ve geleneksel CRUD''dan farkı nedir?','Event sourcing''de "mevcut durum" değil, "geçmişte neler oldu" saklanır. Her değişiklik immutable event olarak append-only log''a yazılır. Güncel durum eventlerin replay edilmesiyle elde edilir. Avantajları: tam audit trail, geçmişe dönük sorgulama, event reprocessing. Dezavantajları: sorgu karmaşıklığı, eventual consistency.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Event sourcing yalnızca güncel durumu saklar; CRUD''dan farkı şifreleme ve imzalama eklemesidir' FROM q UNION ALL SELECT id,1,'Her değişiklik immutable event olarak append-only log''a yazılır; durum event''lerin replay edilmesiyle elde edilir' FROM q UNION ALL SELECT id,2,'Event sourcing gerçek zamanlı veri akışı için kullanılır; CRUD ise batch işlemler için tercih edilir' FROM q UNION ALL SELECT id,3,'Event sourcing yalnızca mesaj kuyruğu (Kafka) ile kullanılabilir; SQL veritabanlarıyla uyumsuzludur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','senior','Distributed sistemlerde Saga pattern hangi problemi çözer?','Saga, mikroservisler arası uzun soluklu işlemlerde (distributed transaction) tutarlılığı sağlar. 2PC yerine her servis lokal transaction çalıştırır; hata durumunda compensating transaction (telafi işlemi) ile geri alınır. Choreography (event tabanlı) ve Orchestration (merkezi koordinatör) olmak üzere iki yaklaşımı vardır.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Aynı veritabanına birden fazla servisten eş zamanlı yazma yapılmasını kilitleme mekanizmasıyla yöneten pattern''dir' FROM q UNION ALL SELECT id,1,'Mikroservisler arasındaki ağ gecikmesini azaltmak için istekleri yerel cache''den yanıtlayan pattern''dir' FROM q UNION ALL SELECT id,2,'Mikroservisler arası işlemlerde tutarlılığı compensating transaction ile sağlayan; 2PC''ye alternatif pattern''dir' FROM q UNION ALL SELECT id,3,'Farklı veritabanı şemalarını tek bir model altında birleştiren ORM düzeyinde abstraction pattern''dir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','senior','API Gateway pattern hangi sorunları çözer?','API Gateway, tüm istemci isteklerinin tek giriş noktasından geçmesini sağlar. Kimlik doğrulama, rate limiting, SSL termination, request routing, aggregation ve caching gibi cross-cutting concern''leri merkezi olarak yönetir. BFF (Backend for Frontend) pattern ile birleşerek istemci tipine özel aggregation sağlanabilir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Yalnızca load balancing sağlar; diğer cross-cutting concern''ler her serviste ayrı implement edilmelidir' FROM q UNION ALL SELECT id,1,'Microservice''lerin birbirleriyle doğrudan iletişim kurmasını sağlayan servis keşif (service discovery) mekanizmasıdır' FROM q UNION ALL SELECT id,2,'Veritabanı sorgularını önbelleğe alarak her servisin SQL yazmak zorunda kalmamasını sağlayan katmandır' FROM q UNION ALL SELECT id,3,'Tüm isteklerin tek giriş noktasından geçmesini sağlar; auth, rate limit, routing gibi cross-cutting concern''leri merkezi yönetir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','senior','gRPC, REST ve GraphQL''in temel farkları nelerdir?','REST: HTTP/1.1 + JSON, yaygın, kolay; kaynak bazlı. GraphQL: istemci tam istediği alanları seçer; over/under-fetching çözülür; tek endpoint. gRPC: HTTP/2 + Protocol Buffers, binary format, streaming destekli, düşük gecikme; microservice arası iletişim için idealdir; tarayıcı desteği sınırlıdır.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'REST kaynak bazlı HTTP/JSON; GraphQL istemci kontrollü alan seçimi; gRPC binary Protocol Buffers ile yüksek performanslı RPC''dir' FROM q UNION ALL SELECT id,1,'GraphQL yalnızca frontend için, gRPC yalnızca backend için, REST ise her iki taraf için uygundur' FROM q UNION ALL SELECT id,2,'gRPC ve REST aynı teknolojidir; GraphQL ise yalnızca Facebook projelerinde kullanılan bir standartır' FROM q UNION ALL SELECT id,3,'REST en yavaş, GraphQL orta, gRPC en hızlı olduğu için her zaman gRPC tercih edilmelidir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','senior','CAP teoremi mikroservis mimarisinde neyi ifade eder?','CAP: Consistency (tüm node''lar aynı veriyi görür), Availability (her istek yanıt alır), Partition tolerance (ağ kesintisine rağmen sistem çalışır). Dağıtık sistemde P kaçınılmazdır; C veya A arasında seçim yapılır. CP sistemler (HBase, ZooKeeper) tutarlılığı, AP sistemler (Cassandra, CouchDB) kullanılabilirliği önceliklendirir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'CAP yalnızca veritabanı replikasyon konfigürasyonunu etkiler; uygulama katmanı bu tradeoff''tan bağımsızdır' FROM q UNION ALL SELECT id,1,'Dağıtık sistemde C (tutarlılık), A (kullanılabilirlik) ve P (bölünme toleransı) aynı anda sağlanamaz; ağ bölünmesinde C ya da A seçilir' FROM q UNION ALL SELECT id,2,'CAP teoremi yalnızca NoSQL veritabanları için geçerlidir; SQL sistemler her üç garantiyi sunar' FROM q UNION ALL SELECT id,3,'CAP teoremi pratikte geçersizdir; modern veritabanları üç özelliği de tam olarak sağlar' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','senior','Outbox pattern hangi problemi çözer?','Outbox pattern, veritabanı transaction ve mesaj kuyruğu yayınının atomik olmasını sağlar. Önce veritabanındaki outbox tablosuna yazılır (aynı transaction içinde), ardından ayrı bir poller/CDC bu kaydı okuyup mesaj kuyruğuna iletir. "At-least-once delivery" garantisi verir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'API yanıtlarını geçici olarak önbelleğe alan ve servis kapalıyken istemciye cached yanıt dönen pattern''dir' FROM q UNION ALL SELECT id,1,'Gelen istekleri geçici tabloda toplayıp batch halinde işleyen veri giriş optimizasyon pattern''idir' FROM q UNION ALL SELECT id,2,'DB transaction ve mesaj kuyruğu yayınını atomik hale getirir; outbox tablosuna yazıp poller ile iletir' FROM q UNION ALL SELECT id,3,'Microservice''lerin dışa açık API''lerini merkezi registry''de kaydeden servis keşif pattern''idir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','senior','Bulkhead pattern dağıtık sistemlerde nasıl çalışır?','Bulkhead, farklı servislere veya özelliklere ayrılmış bağlantı havuzu/thread havuzu gibi kaynakları izole eder. Bir servis yavaşlayınca diğer servisler için ayrılan kaynakları tüketmesini engeller; cascading failure''ı önler. Adını gemilerdeki su geçirmez bölmelerden alır.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'İstekleri ağır ve hafif olarak sınıflandırıp ayrı işlemci çekirdeklerine yönlendiren CPU affinity tekniğidir' FROM q UNION ALL SELECT id,1,'Veritabanı tablolarını şema bazında izole ederek farklı tenant''ların birbirinin verisine erişememesini sağlar' FROM q UNION ALL SELECT id,2,'Yalnızca sağlıklı node''lara istek gönderen ve sağlıksız node''ları geçici olarak devre dışı bırakan pattern''dir' FROM q UNION ALL SELECT id,3,'Servislere ayrılan kaynakları (thread/connection pool) izole eder; bir servis arızalanınca diğerleri etkilenmez' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','senior','12-Factor App metodolojisinden "Config" faktörü ne diyor?','12-Factor''ün III. faktörü: Konfigürasyon (veritabanı URL''leri, API key''leri, credentials) kod deposunda değil ortam değişkenlerinde (environment variables) saklanmalıdır. Bunun nedeni: güvenlik (credentials kod deposunda görünmemeli) ve ortam bağımsızlığı (dev/staging/prod aynı kodu farklı config ile çalıştırır).',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Konfigürasyon (API key, DB URL) kod deposuna değil ortam değişkenlerine taşınmalı; ortam bağımsızlığı sağlanmalıdır' FROM q UNION ALL SELECT id,1,'Tüm konfigürasyon bir merkezi YAML dosyasında toplanmalı ve versiyonlanmalıdır' FROM q UNION ALL SELECT id,2,'Konfigürasyon çalışma zamanında veritabanından okunmalı; environment variable kullanımı önerilmez' FROM q UNION ALL SELECT id,3,'Her ortam (dev/prod) için ayrı kaynak kodu branch''i oluşturulmalı ve ayrı deploy edilmelidir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','senior','Observability''nin üç temel bileşeni (metrics, logs, traces) arasındaki fark nedir?','Metrics: sayısal zaman serisi (istek sayısı, latency p99, hata oranı); alerting için idealdir. Logs: yapılandırılmış veya düz metin olaylar; debug için detay sağlar. Traces (distributed tracing): tek isteğin tüm servislerdeki yolculuğunu izler; bottleneck tespiti için kullanılır. OpenTelemetry üçünü destekler.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Üçü de aynı veriyi farklı formatta saklar; hangisi kullanılacağı tamamen tercih meselesidir' FROM q UNION ALL SELECT id,1,'Metrics sayısal zaman serisi (alerting), logs olayların detayı (debug), traces isteğin servisler arası yolculuğudur (bottleneck)' FROM q UNION ALL SELECT id,2,'Traces yalnızca frontend performansını ölçer; backend için metrics ve logs yeterlidir' FROM q UNION ALL SELECT id,3,'Metrics ve logs aynı şeydir; traces ise yalnızca Kubernetes ortamlarında kullanılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','senior','Zero-downtime deployment için hangi stratejiler kullanılır?','Zero-downtime için: Blue-Green (iki özdeş ortam; trafik anında yönlendirilir; rollback kolay), Canary (trafiğin küçük yüzdesi yeni versiyona; hata oranı izlenir), Rolling Update (örnek örnek güncellenir). Database migration''larda backward-compatible schema değişiklikleri (expand-contract pattern) kritiktir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Yalnızca çok çekirdekli sunucular zero-downtime sağlayabilir; tek çekirdekli sunucularda her deploy kesinti yaratır' FROM q UNION ALL SELECT id,1,'Zero-downtime için load balancer kapatılır, güncelleme yapılır, ardından tekrar açılır' FROM q UNION ALL SELECT id,2,'Blue-green (anlık trafik geçişi), canary (kademeli geçiş) ve rolling update; DB için expand-contract schema değişiklikleri gerekir' FROM q UNION ALL SELECT id,3,'Zero-downtime yalnızca stateless servislerde mümkündür; veritabanı servisleri her zaman kısa kesinti gerektirir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','senior','Service mesh nedir ve ne sağlar?','Service mesh (Istio, Linkerd), microservice''ler arası iletişimi yöneten altyapı katmanıdır. Her pod''a sidecar proxy eklenir; mTLS ile servisler arası şifreleme, traffic management, circuit breaking, retry, distributed tracing ve fine-grained authorization otomatik sağlanır. Uygulama kodu bu logic''i implement etmez.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Microservice''lerin paylaştığı merkezi bir veritabanı mesh''i olup veri tutarlılığını garanti altına alır' FROM q UNION ALL SELECT id,1,'Frontend ile backend arasındaki CDN katmanını yöneten ve static asset''leri dağıtan altyapı bileşenidir' FROM q UNION ALL SELECT id,2,'Birden fazla bulut sağlayıcısını tek bir API ile yöneten multi-cloud orchestration aracıdır' FROM q UNION ALL SELECT id,3,'Sidecar proxy ile servisler arası mTLS, traffic management, circuit break ve tracing sağlayan altyapı katmanıdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','mid','CORS preflight request ne zaman gönderilir?','Basit olmayan (non-simple) cross-origin isteklerde tarayıcı otomatik OPTIONS preflight gönderir. Non-simple istek: PUT/DELETE/PATCH metodları, JSON Content-Type, özel header''lar. Sunucu Access-Control-Allow-* header''larıyla yanıt verir; tarayıcı izin varsa asıl isteği gönderir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Non-simple cross-origin isteklerde (PUT/DELETE, JSON body, özel header) tarayıcı otomatik OPTIONS isteği gönderir' FROM q UNION ALL SELECT id,1,'Her cross-origin istekte preflight gönderilir; GET istekleri dahil tüm metodlar önce OPTIONS ile kontrol edilir' FROM q UNION ALL SELECT id,2,'Preflight yalnızca kullanıcı giriş yapmışsa gönderilir; anonim isteklerde atlanır' FROM q UNION ALL SELECT id,3,'Preflight yalnızca HTTPS bağlantılarda tetiklenir; HTTP istekler her zaman doğrudan gönderilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','mid','Backend''de N+1 sorunu nedir ve nasıl çözülür?','N+1: 1 sorgu ile N kayıt çekilir, ardından her kayıt için ayrı sorgu çalışır (toplam N+1 sorgu). ORM lazy loading''in tipik yan etkisidir. Çözüm: eager loading (JOIN veya IN clause ile tek sorguda tüm verinin çekilmesi), DataLoader (GraphQL), veya query batching.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'N+1, N adet sorgunun birden fazla transaction içinde çalışmasından kaynaklanan deadlock sorunudur' FROM q UNION ALL SELECT id,1,'1 sorgu ile N kayıt çekilip her kayıt için ayrı sorgu çalıştırılmasıdır; eager loading veya DataLoader ile çözülür' FROM q UNION ALL SELECT id,2,'N adet tabloya aynı anda yazılmaya çalışıldığında oluşan race condition problemidir' FROM q UNION ALL SELECT id,3,'N farklı API endpoint''inin aynı veriyi farklı formatlarda döndürmesinden kaynaklanan veri tutarsızlığıdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','junior','HTTP HEAD metodu ne işe yarar?','HEAD metodu GET ile aynıdır; fark response body dönmemesidir. Yalnızca header''ları döner. Kullanım alanları: dosya boyutunu (Content-Length) önceden öğrenmek, kaynağın var olup olmadığını kontrol etmek (404 mı?), son değişiklik tarihini (Last-Modified) sorgulamak.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Tüm mevcut HTTP metodlarının listesini döndürür; OPTIONS ile aynı işlevi görür' FROM q UNION ALL SELECT id,1,'Sunucudaki bir kaynağı kısmen güncellemek için kullanılır; PATCH ile eşdeğerdir' FROM q UNION ALL SELECT id,2,'GET ile aynıdır ancak response body dönmez; yalnızca header''ları döndürür; boyut/varlık kontrolü için kullanılır' FROM q UNION ALL SELECT id,3,'İstek body''sini sunucuya göndermeden header doğrulaması yapar; büyük dosya yükleme öncesi kullanılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('backend','tr','junior','REST ve SOAP arasındaki temel fark nedir?','REST: mimari stil, HTTP metodlarını kullanır, genellikle JSON, lightweight, stateless. SOAP: protokol, XML zorunlu, WSDL ile sözleşme tanımı, WS-Security ile enterprise güvenlik, işlem (transaction) desteği. Bankacılık ve eski kurumsal sistemler hâlâ SOAP kullanır.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'REST daha güvenlidir çünkü HTTPS zorunlu kılar; SOAP HTTP üzerinde çalışamaz' FROM q UNION ALL SELECT id,1,'SOAP yalnızca Java ile çalışır; REST ise dilden bağımsızdır' FROM q UNION ALL SELECT id,2,'REST ve SOAP aynı teknolojidir; SOAP daha eski bir REST implementasyonudur' FROM q UNION ALL SELECT id,3,'REST lightweight mimari stil (HTTP+JSON); SOAP XML tabanlı protokol (WSDL, WS-Security, işlem desteği)' FROM q;

-- ══════════════════════════════════════════
-- DEVOPS (+40 soru)
-- ══════════════════════════════════════════

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','junior','Docker container ile sanal makine (VM) arasındaki temel fark nedir?','Container''lar host OS çekirdeğini paylaşır; her biri yalnızca uygulama ve bağımlılıklarını içerir. VM''ler ise tam bir guest OS çalıştırır; daha fazla kaynak tüketir ancak daha güçlü izolasyon sağlar. Container''lar saniyeler içinde başlarken VM''ler dakika sürebilir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Container host OS çekirdeğini paylaşır, hızlı ve hafiftir; VM tam guest OS çalıştırır, daha güçlü izolasyon sağlar' FROM q UNION ALL SELECT id,1,'Container tam işletim sistemi içerir; VM ise yalnızca uygulama binary''sini çalıştırır' FROM q UNION ALL SELECT id,2,'Container yalnızca Linux''ta çalışır; VM ise her işletim sistemi üzerinde kullanılabilir' FROM q UNION ALL SELECT id,3,'Container ve VM aynı teknolojidir; yalnızca kullanılan araçlar (Docker vs VirtualBox) farklıdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','junior','Dockerfile''da `CMD` ve `ENTRYPOINT` arasındaki fark nedir?','`ENTRYPOINT` container''ın çalıştırılabilir komutunu belirler; geçersiz kılınmak için `--entrypoint` bayrağı gerekir. `CMD` varsayılan argümanları sağlar; `docker run` sonrası argüman verilirse `CMD` kolayca geçersiz kılınır. Shell ve exec form farkı da önemlidir; exec form PID 1 sinyal almayı sağlar.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'CMD container oluşturulurken, ENTRYPOINT ise container çalıştırılırken execute edilir' FROM q UNION ALL SELECT id,1,'ENTRYPOINT container çalıştırılabilir komutunu tanımlar; CMD ise kolayca override edilebilen varsayılan argümanları sağlar' FROM q UNION ALL SELECT id,2,'CMD Linux container için, ENTRYPOINT Windows container için kullanılır' FROM q UNION ALL SELECT id,3,'İkisi aynı işlevi görür; fark yalnızca syntax tercihidir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','junior','Docker image katmanları (layers) neden önemlidir?','Her Dockerfile talimatı (RUN, COPY, ADD) yeni bir katman oluşturur. Katmanlar immutable ve içerik hash''iyle tanımlanır. Değişmeyen katmanlar build ve pull sırasında yeniden kullanılır (cache). Bu nedenle sık değişen talimatlar (COPY kaynak kodu) Dockerfile''ın sonuna, nadiren değişenler (bağımlılık kurulum) başına konulmalıdır.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Katmanlar yalnızca görsel izleme içindir; build performansına etkisi yoktur' FROM q UNION ALL SELECT id,1,'Katmanlar container çalışırken oluşturulur; image build sırasında katman sayısı sabit kalır' FROM q UNION ALL SELECT id,2,'Her talimat katman oluşturur; değişmeyen katmanlar cache''den yeniden kullanılır, sık değişenler sona konulmalıdır' FROM q UNION ALL SELECT id,3,'Katmanlar yalnızca multi-stage build kullanan Dockerfile''larda oluşturulur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','junior','CI/CD pipeline nedir ve hangi adımlardan oluşur?','CI (Continuous Integration): kod değişiklikleri sık entegre edilir, otomatik build ve test çalışır. CD (Continuous Delivery/Deployment): testleri geçen kod otomatik staging''e veya prod''a dağıtılır. Tipik adımlar: checkout, build, test, static analysis, security scan, artifact publish, deploy, smoke test.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'CI sunucu bakım, CD ise veritabanı yedekleme süreçlerini otomatikleştiren araçlardır' FROM q UNION ALL SELECT id,1,'CI günlük build, CD ise haftalık deploy anlamına gelir; her ikisi de manuel onay gerektirir' FROM q UNION ALL SELECT id,2,'CI yalnızca unit test çalıştırır; CD yalnızca production deploy gerçekleştirir' FROM q UNION ALL SELECT id,3,'CI kod entegrasyonunu ve otomatik testleri, CD ise testleri geçen kodun otomatik dağıtımını kapsar' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','junior','Git''te merge ve rebase arasındaki fark nedir?','`git merge` iki branch''i birleştirir ve merge commit oluşturur; tarihçe korunur, paralel iş görünür. `git rebase` feature branch commit''lerini hedef branch''in ucuna taşır; doğrusal, temiz tarihçe sağlar ancak commit hash''leri değişir. Public branch''lerde rebase tarihçe bozar.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'merge tarihçeyi koruyup merge commit ekler; rebase commit''leri yeniden uygular, doğrusal tarihçe oluşturur ama hash değişir' FROM q UNION ALL SELECT id,1,'merge yalnızca fast-forward durumunda kullanılır; rebase tüm durumlarda geçerlidir' FROM q UNION ALL SELECT id,2,'rebase daha güvenlidir çünkü orijinal commit''leri silmez; merge ise commit''leri siler' FROM q UNION ALL SELECT id,3,'İkisi de aynı sonucu üretir; fark yalnızca araç arayüzüdür' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','junior','Konfigürasyon değerlerini (DB URL, API key) environment variable''da tutmanın avantajı nedir?','Environment variable''lar kod deposuna dahil edilmez; credentials güvenli kalır. Aynı image farklı ortamlarda (dev/staging/prod) farklı config ile çalışabilir. 12-Factor App''in III. faktörü olan "Config" prensibini uygular. Secrets manager (Vault, AWS Secrets Manager) ile entegrasyon kolaylaşır.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Environment variable''lar şifrelenerek saklanır; config dosyalarından daha güvenlidir' FROM q UNION ALL SELECT id,1,'Credentials kod deposuna girmez; aynı image farklı ortamlarda farklı konfigürasyonla çalışabilir' FROM q UNION ALL SELECT id,2,'Environment variable''lar yalnızca Docker ve Kubernetes ortamlarında desteklenir; yerel geliştirmede çalışmaz' FROM q UNION ALL SELECT id,3,'Environment variable kullanımı uygulamayı otomatik olarak 12-Factor uyumlu hale getirir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','junior','Docker''da port mapping (`-p 8080:80`) ne anlama gelir?','`-p host_port:container_port` sözdizimi host makinenin 8080 portunu container''ın 80 portuna yönlendirir. Dış dünyadan 8080 portuna gelen trafik container''ın 80 portuna iletilir. Container içinde uygulama 80''de dinlese de dışarıdan 8080 üzerinden erişilir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Container''ın 8080 portunu container''ın kendi 80 portuna yönlendirmek için kullanılır' FROM q UNION ALL SELECT id,1,'8080 protokol versiyonunu, 80 ise container instance sayısını ifade eder' FROM q UNION ALL SELECT id,2,'Host makinenin 8080 portunu container''ın 80 portuna yönlendirir; dışarıdan 8080 ile erişilir' FROM q UNION ALL SELECT id,3,'Yalnızca TCP 8080 trafiğini UDP 80''e dönüştürmek için kullanılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','junior','Docker image ile Docker container arasındaki fark nedir?','Image, uygulamanın çalıştırılabilir read-only şablonudur; katmanlardan oluşur ve bir blueprint''tir. Container, image''ın çalışan örneğidir; kendi yazılabilir katmanına sahiptir. Aynı image''dan birden fazla container başlatılabilir. Image silmeden önce bağlı tüm container''lar silinmelidir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Image çalışırken, container durağan haldeyken kullanılan terimdir; işlev aynıdır' FROM q UNION ALL SELECT id,1,'Image ağ konfigürasyonunu, container ise uygulama kodunu içerir' FROM q UNION ALL SELECT id,2,'Image Registry''de saklanan şifreli versiyon, container ise production''da çalışan şifresiz versiyondur' FROM q UNION ALL SELECT id,3,'Image read-only blueprint''tir; container image''ın çalışan örneğidir, kendi yazılabilir katmanına sahiptir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','junior','Load balancer nedir ve hangi problemi çözer?','Load balancer gelen trafiği birden fazla sunucu örneğine dağıtır. Faydaları: yüksek kullanılabilirlik (bir sunucu çökerse trafik diğerlerine yönlenir), ölçeklenebilirlik (yeni sunucu eklenerek kapasite artırılır), health check ile sağlıksız örnekleri devre dışı bırakma.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Gelen trafiği birden fazla sunucuya dağıtır; yüksek kullanılabilirlik ve yatay ölçeklenebilirlik sağlar' FROM q UNION ALL SELECT id,1,'Veritabanı sorgularını önbelleğe alarak sunucu yükünü azaltan bir caching mekanizmasıdır' FROM q UNION ALL SELECT id,2,'CDN ile sunucu arasında duran ve SSL sertifikasını yöneten bir güvenlik bileşenidir' FROM q UNION ALL SELECT id,3,'Farklı coğrafi konumlardaki sunucular arasında DNS yönlendirmesi yapan bir servistir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','junior','DNS (Domain Name System) nasıl çalışır?','DNS, alan adlarını (örn. google.com) IP adreslerine çevirir. Resolver sırayla: local cache, OS cache, recursive resolver (ISP), root nameserver, TLD nameserver (.com), authoritative nameserver''ı sorgular. TTL (Time to Live) değeri cache süresini belirler.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'DNS tüm web sitelerinin kaynak kodunu merkezi sunucuda depolar ve istekte bulunanlara gönderir' FROM q UNION ALL SELECT id,1,'Alan adlarını IP adreslerine çevirir; local cache''den başlayarak root/TLD/authoritative nameserver''a kadar sorgular' FROM q UNION ALL SELECT id,2,'DNS yalnızca web tarayıcıları için çalışır; diğer uygulamalar IP adreslerini doğrudan kullanmak zorundadır' FROM q UNION ALL SELECT id,3,'HTTP isteklerini şifreleyen ve güvenli tünel oluşturan bir protokoldür' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','junior','TLS (HTTPS) handshake sürecinde neler gerçekleşir?','TLS handshake: 1) Client hello (desteklenen TLS versiyonları, cipher suite''ler), 2) Server hello + sertifika gönderimi, 3) Client sertifikayı doğrular (CA chain), 4) Key exchange (asimetrik şifreleme ile session key oluşturulur), 5) Şifreli iletişim başlar. Simetrik session key ile veri şifrelenir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Yalnızca şifre kontrolü yapılır; sertifika doğrulaması ise yalnızca bankacılık sitelerinde gereklidir' FROM q UNION ALL SELECT id,1,'Client ve server birbirinin şifrelerini değiş tokuş eder; ardından her ikisi de aynı şifreyi kullanır' FROM q UNION ALL SELECT id,2,'Client hello, server sertifika gönderimi, sertifika doğrulaması ve asimetrik key exchange ile session key oluşturulur' FROM q UNION ALL SELECT id,3,'TLS yalnızca HTTP trafiğini şifreler; diğer protokoller (FTP, SMTP) TLS kullanamaz' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','junior','SSH''de key tabanlı kimlik doğrulama şifre tabanlıya göre neden tercih edilir?','SSH key pair: private key (istemcide saklanır, asla paylaşılmaz) ve public key (sunucuya eklenir). Brute force saldırılarına karşı dayanıklıdır çünkü key matematiksel olarak çok daha büyük anahtar uzunluğu kullanır. Otomasyon ve CI/CD pipeline''larında şifre gerektirmeden erişim sağlar.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Key tabanlı auth yalnızca root kullanıcı için zorunludur; normal kullanıcılar şifre kullanabilir' FROM q UNION ALL SELECT id,1,'Key tabanlı auth şifrenin ağ üzerinden hiç iletilmediği anlamına gelir; şifre ise her seferinde gönderilir' FROM q UNION ALL SELECT id,2,'SSH key''ler süresi dolmaz; şifreler ise 90 günde bir değiştirilmek zorundadır' FROM q UNION ALL SELECT id,3,'Brute force''a dayanıklı büyük anahtar kullanır; şifre gerektirmeden otomasyon ve CI/CD erişimi sağlar' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','mid','Docker multi-stage build neden kullanılır?','Multi-stage build: ilk aşamada derleme araçları (compiler, build dependencies) ile uygulama derlenir; son aşamaya yalnızca derleme çıktısı kopyalanır. Sonuç image''ı küçük ve güvenlidir; build araçları ve kaynak kodu son image''a dahil olmaz. Go, Java, .NET gibi derlenen diller için kritiktir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Derleme araçlarını son image''a dahil etmez; yalnızca çalışma zamanı binary''si kopyalanır, küçük ve güvenli image elde edilir' FROM q UNION ALL SELECT id,1,'Birden fazla Dockerfile''ı aynı anda paralel olarak build etmek için kullanılır' FROM q UNION ALL SELECT id,2,'Development, staging ve production için ayrı layer''lar oluşturup tek komutla hepsini deploy eder' FROM q UNION ALL SELECT id,3,'Multi-stage build yalnızca Kubernetes ortamında geçerlidir; Docker Compose ile uyumsuzludur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','mid','Kubernetes''te Pod, Deployment ve Service arasındaki hiyerarşik ilişki nedir?','Pod: bir veya birden fazla container''ı barındıran en küçük deploy birimidir; geçici (ephemeral) ve IP''si değişkendir. Deployment: Pod''ların istenen replica sayısını yönetir, rolling update ve rollback sağlar. Service: kararlı bir DNS adı ve IP ile Pod''lara erişim sağlar; Pod''lar yeniden başlasa da Service adresi değişmez.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Service en küçük birimdir; Deployment birden fazla Service barındırır; Pod ise tüm Deployment''ları gruplar' FROM q UNION ALL SELECT id,1,'Pod en küçük deploy birimi; Deployment replica sayısını ve güncellemeleri yönetir; Service kararlı ağ kimliği sağlar' FROM q UNION ALL SELECT id,2,'Pod kalıcı depolama, Deployment ağ konfigürasyonu, Service ise container çalıştırma sorumluluğunu taşır' FROM q UNION ALL SELECT id,3,'Üçü aynı kavramın farklı isimlendirilmesidir; hangisi kullanılacağı proje tercihine göre değişir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','mid','Kubernetes''te ClusterIP, NodePort ve LoadBalancer servis tipleri ne zaman kullanılır?','ClusterIP (varsayılan): yalnızca cluster içinden erişilebilir; servisler arası iletişim için. NodePort: her node''un belirli portunu açar; geliştirme/test için basit dış erişim. LoadBalancer: cloud provider''da harici load balancer oluşturur; production dış erişim için. Ingress tüm bu tipleri tek HTTP giriş noktasıyla yönetir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'ClusterIP dış trafik, NodePort cluster içi trafik, LoadBalancer ise yalnızca UDP trafiği için kullanılır' FROM q UNION ALL SELECT id,1,'Üç tip aynı işlevi görür; fark yalnızca servis adının uzunluğuyla alakalıdır' FROM q UNION ALL SELECT id,2,'ClusterIP cluster içi iletişim; NodePort her node''dan basit dış erişim; LoadBalancer cloud''da harici LB oluşturur' FROM q UNION ALL SELECT id,3,'NodePort yalnızca HTTP, LoadBalancer yalnızca TCP, ClusterIP ise yalnızca UDP trafiği için tasarlanmıştır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','mid','Kubernetes''te ConfigMap ve Secret arasındaki fark nedir?','ConfigMap: hassas olmayan konfigürasyon verilerini (feature flag, uygulama ayarları) key-value olarak saklar. Secret: base64 encode edilmiş hassas verileri (password, token, certificate) saklar; RBAC ile erişim kısıtlanabilir, etcd''de encryption at rest sağlanabilir. Secret''lar volume veya env var olarak Pod''lara enjekte edilir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'ConfigMap binary dosyaları, Secret ise yalnızca string değerleri saklayabilir' FROM q UNION ALL SELECT id,1,'ConfigMap geliştirme ortamı, Secret ise yalnızca production ortamı için kullanılır' FROM q UNION ALL SELECT id,2,'İkisi de aynı şekilde çalışır; aralarındaki tek fark nesne adı konvansiyonudur' FROM q UNION ALL SELECT id,3,'ConfigMap hassas olmayan konfigürasyonları saklar; Secret şifreli hassas verileri (password, token) saklar' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','mid','Horizontal scaling ile vertical scaling arasındaki fark ve tradeoff''lar nelerdir?','Vertical (scale up): mevcut sunucuya daha fazla CPU/RAM eklenir; uygulama değişikliği gerekmez ancak tek nokta arıza riski ve donanım limiti vardır. Horizontal (scale out): yeni sunucu/instance eklenir; yüksek kullanılabilirlik sağlar ancak distributed system karmaşıklığı ve stateless uygulama gerektirir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Vertical: mevcut sunucuya kaynak ekler (limit var, tek nokta arıza); horizontal: yeni instance ekler (dağıtık, HA)' FROM q UNION ALL SELECT id,1,'Horizontal: CPU artırma; vertical: yeni sunucu ekleme anlamına gelir' FROM q UNION ALL SELECT id,2,'İkisi de aynı sonucu üretir; vertical daha pahalıdır, horizontal daha ucuzdur' FROM q UNION ALL SELECT id,3,'Vertical scaling yalnızca veritabanları için; horizontal scaling yalnızca stateless web sunucuları için uygundur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','mid','Blue-green deployment ile canary deployment arasındaki fark nedir?','Blue-green: iki özdeş ortam (blue: mevcut, green: yeni). Trafik anında %100 green''e yönlendirilir; rollback hızlıdır ancak çift kaynak maliyeti vardır. Canary: trafiğin küçük yüzdesi (%5-10) yeni versiyona yönlendirilir; hata oranı izlenerek kademeli artırılır; riski minimize eder.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Blue-green kademeli, canary ise anlık trafik geçişi yapar; maliyet ve risk aynıdır' FROM q UNION ALL SELECT id,1,'Blue-green trafik anında %100 yeni versiyona geçer (çift kaynak maliyeti); canary kademeli yüzde ile test eder' FROM q UNION ALL SELECT id,2,'Blue-green yalnızca veritabanı, canary ise yalnızca frontend deployment için kullanılır' FROM q UNION ALL SELECT id,3,'Canary deployment yalnızca Kubernetes HPA ile birlikte çalışır; blue-green bağımsız kullanılabilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','mid','Terraform''da state dosyası ne işe yarar ve neden remote backend''de tutulmalıdır?','Terraform state, yönetilen altyapının güncel durumunu saklar; hangi kaynakların oluşturulduğunu, konfigürasyonla eşleşip eşleşmediğini belirler. Local state: takım çalışmasında state çakışması riski. Remote backend (S3, Terraform Cloud): state lock mekanizması sayesinde eş zamanlı değişiklik önlenir, erişim kontrol edilir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Terraform state, provider kimlik bilgilerini şifreli saklar; remote backend güvenliği artırır' FROM q UNION ALL SELECT id,1,'State dosyası yalnızca deployment loglarını tutar; altyapı durumu provider API''sinden her zaman canlı okunur' FROM q UNION ALL SELECT id,2,'State mevcut altyapı durumunu saklar; remote backend takım ortamında lock mekanizmasıyla çakışmayı önler' FROM q UNION ALL SELECT id,3,'State dosyası yalnızca destroy komutunda kullanılır; apply ve plan komutları state''e ihtiyaç duymaz' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','mid','GitHub Actions''ta workflow, job ve step hiyerarşisi nasıldır?','Workflow: `.github/workflows/*.yml` dosyasında tanımlı; event (push, PR, schedule) ile tetiklenir. Job: paralel veya sıralı çalışan bağımsız birim; kendi runner''ında çalışır. Step: job içindeki tek bir görev (action kullanma veya shell komutu). Farklı job''lar arasında artifact paylaşımı için upload/download-artifact kullanılır.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Step en büyük birim, job ortada, workflow en küçük birimdir; hepsi aynı runner''da çalışır' FROM q UNION ALL SELECT id,1,'Workflow yalnızca push event''i tetikler; diğer event''ler için ayrı GitHub Apps gerekir' FROM q UNION ALL SELECT id,2,'Job ve step aynı şeydir; workflow ise birden fazla repository''yi kapsayan üst yapıdır' FROM q UNION ALL SELECT id,3,'Workflow event ile tetiklenir; job kendi runner''ında paralel/sıralı çalışır; step job içindeki tek görevdir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','mid','Nginx''i reverse proxy olarak kullanmanın avantajları nelerdir?','Nginx reverse proxy: istemci isteklerini arkadaki uygulama sunucularına yönlendirir. Avantajları: SSL termination (TLS''i Nginx karşılar), load balancing, static file serving (uygulama sunucusunu boşaltır), rate limiting, caching, tek IP''de birden fazla domain barındırma (virtual hosts).',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'SSL termination, load balancing, static file serving ve rate limiting gibi cross-cutting sorumlulukları merkezi yönetir' FROM q UNION ALL SELECT id,1,'Nginx yalnızca static dosya sunmak için kullanılır; dinamik içerik için Apache zorunludur' FROM q UNION ALL SELECT id,2,'Reverse proxy yalnızca güvenlik duvarı işlevi görür; diğer özellikleri için ayrı araçlar gerekir' FROM q UNION ALL SELECT id,3,'Nginx reverse proxy kullanımı uygulama sunucusunu internet''ten tamamen gizler; bu nedenle SSL sertifikası gerekmez' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','mid','Kubernetes HPA (Horizontal Pod Autoscaler) nasıl çalışır?','HPA, CPU/memory kullanımı veya custom metrikler (örn. RPS) bazında Deployment''ın replica sayısını otomatik artırır veya azaltır. Metrics Server veya Prometheus Adapter''dan metrik okur. Minimum ve maksimum replica sayısı tanımlanır; aşırı scaling''i önlemek için cooldown süresi vardır.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'HPA Pod''ların CPU/RAM limitlerini otomatik artırarak mevcut instance''ları güçlendirir (vertical scaling)' FROM q UNION ALL SELECT id,1,'CPU/memory veya custom metriklere göre replica sayısını otomatik artırır/azaltır; min/max sınırları tanımlanır' FROM q UNION ALL SELECT id,2,'HPA yalnızca node ekleme/çıkarma yapar; Pod sayısını kendisi değiştirmez' FROM q UNION ALL SELECT id,3,'HPA yalnızca Deployment''larla çalışır; StatefulSet ve DaemonSet ile uyumsuzludur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','mid','Dockerfile''da HEALTHCHECK talimatı ne sağlar?','HEALTHCHECK, Docker''ın container''ın sağlıklı çalışıp çalışmadığını periyodik olarak kontrol etmesini sağlar. Başarısız kontrol sonrası container "unhealthy" durumuna geçer; orchestrator (Kubernetes, Swarm) bu container''a trafik göndermez ve yeniden başlatabilir. Uygulama process''i çalışsa bile servis gerçekten hazır olmayabilir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'HEALTHCHECK yalnızca build sırasında çalışır; çalışan container''larda etkisi yoktur' FROM q UNION ALL SELECT id,1,'HEALTHCHECK container''ın güvenlik açıklarını otomatik tarayıp raporlayan bir güvenlik özelliğidir' FROM q UNION ALL SELECT id,2,'Container''ın sağlığını periyodik kontrol eder; unhealthy durumunda orchestrator trafik kesmez ve yeniden başlatabilir' FROM q UNION ALL SELECT id,3,'HEALTHCHECK yalnızca HTTP endpoint kontrolü yapabilir; başka sağlık kontrolü desteklenmez' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','mid','Prometheus''ta Counter, Gauge, Histogram ve Summary metrik tipleri ne anlama gelir?','Counter: yalnızca artan sayaç (toplam istek sayısı, hata sayısı). Gauge: artıp azalabilen anlık değer (aktif bağlantı, bellek kullanımı). Histogram: gözlemleri bucket''lara dağıtır; quantile hesaplama ve SLO için (istek süre dağılımı). Summary: istemci tarafında quantile hesaplar; Histogram''dan daha az esnek.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Counter ve Gauge aynıdır; Histogram görsel grafik, Summary ise metin raporu için kullanılır' FROM q UNION ALL SELECT id,1,'Tüm tipler aynı veriyi farklı formatlarda sunar; hangisi kullanılacağı görselleştirme tercihine göre belirlenir' FROM q UNION ALL SELECT id,2,'Counter yalnızca hata sayımı, Gauge yalnızca CPU, Histogram yalnızca ağ için kullanılabilir' FROM q UNION ALL SELECT id,3,'Counter sadece artar; Gauge artıp azalır; Histogram bucket dağılımı sağlar; Summary istemci quantile hesaplar' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','senior','Kubernetes Ingress Controller nedir ve Service tipleriyle farkı nedir?','Ingress Controller, HTTP/HTTPS kurallarını (host, path yönlendirme, TLS termination) yöneten cluster bileşenidir (Nginx Ingress, Traefik, Istio Gateway). Tek bir LoadBalancer IP''si üzerinden birden fazla servise yönlendirme yapar; maliyet avantajı sağlar. Service tipi LoadBalancer her servis için ayrı cloud LB oluşturur.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'HTTP kural tabanlı yönlendirme yapar; tek LB IP''siyle birden fazla servise host/path bazlı trafik iletir' FROM q UNION ALL SELECT id,1,'Ingress Controller, Service tipinin gelişmiş versiyonudur; yalnızca isim farklıdır' FROM q UNION ALL SELECT id,2,'Ingress yalnızca cluster içi servisler için çalışır; dış trafik LoadBalancer Service kullanmalıdır' FROM q UNION ALL SELECT id,3,'Ingress Controller, Pod''lara container eklenmeden önce güvenlik taraması yapan admission webhook''tur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','senior','GitOps metodolojisi nedir?','GitOps: istenen altyapı/uygulama durumunu Git deposunda declarative olarak tanımlar; her commit otomatik reconciliation tetikler. ArgoCD veya Flux, Git''teki durumu cluster''da uygular. Avantajları: tek doğruluk kaynağı (Git), tam audit trail, PR ile değişiklik incelemesi, kolay rollback (git revert).',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'GitOps, tüm commit''lerin otomatik production''a deploy edildiği sürekli deployment stratejisidir' FROM q UNION ALL SELECT id,1,'Git deposu altyapının tek doğruluk kaynağıdır; otomatik reconciliation ile cluster Git durumuyla senkronize tutulur' FROM q UNION ALL SELECT id,2,'GitOps, birden fazla Git reposundaki değişiklikleri tek pipeline''da birleştiren CI/CD optimizasyonudur' FROM q UNION ALL SELECT id,3,'GitOps yalnızca Kubernetes için geçerlidir; VM tabanlı altyapıda uygulanması mümkün değildir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','senior','Service mesh (Istio) mTLS neden önemlidir?','mTLS (mutual TLS): hem istemci hem sunucu birbirini doğrular ve trafik şifrelenir. Service mesh''te her Pod''un sidecar proxy''si sertifika yönetimini otomatik yapar; uygulama kodu değişmez. Zero-trust network güvenliği için kritiktir: bir Pod ele geçirilse bile yan hareketi kısıtlar.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'mTLS yalnızca cluster dışından gelen trafiği şifreler; cluster içi pod iletişiminde etkisi yoktur' FROM q UNION ALL SELECT id,1,'mTLS uygulama katmanında implement edilir; service mesh bunu otomatize etmez, yalnızca izler' FROM q UNION ALL SELECT id,2,'Servisler arası iletişimde karşılıklı kimlik doğrulaması ve şifreleme sağlar; zero-trust güvenlik modelini mümkün kılar' FROM q UNION ALL SELECT id,3,'mTLS yalnızca ödeme servisleri gibi hassas bileşenler için kullanılır; diğer servisler normal TLS kullanmalıdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','senior','Kubernetes''te resource requests ve limits arasındaki fark nedir?','Request: Pod''un garanti istediği minimum kaynak; scheduler bu değere göre node seçer. Limit: Pod''un kullanabileceği maksimum kaynak. CPU throttle edilir (kill edilmez); memory limitini aşan Pod OOMKilled olur. Request > Limit geçersizdir. QoS sınıfları: Guaranteed (request=limit), Burstable (request<limit), BestEffort (tanımsız).',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Request ve limit aynıdır; resource ikisi için tek değer tanımlanır' FROM q UNION ALL SELECT id,1,'Request maksimum kullanım, limit ise minimum garanti anlamına gelir' FROM q UNION ALL SELECT id,2,'Request yalnızca memory için, limit yalnızca CPU için tanımlanır' FROM q UNION ALL SELECT id,3,'Request scheduler için minimum garanti; limit maksimum kullanım; CPU throttle edilir, memory aşılırsa OOMKilled olur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','senior','Kubernetes''te etcd''nin rolü nedir?','etcd, Kubernetes''in dağıtık key-value deposudur; tüm cluster durumunu (Pod, Service, Deployment tanımları, secrets) saklar. Raft consensus algoritması ile yüksek tutarlılık sağlar. etcd arızalanırsa cluster yönetimi durur; Pod''lar çalışmaya devam eder ancak yeni Pod başlatılamaz, Service güncellenemez.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Tüm cluster durumunu (nesne tanımları) saklayan dağıtık key-value deposudur; arızalanırsa cluster yönetimi durur' FROM q UNION ALL SELECT id,1,'Container image''larını cluster içinde dağıtan ve cache''leyen registry proxy bileşenidir' FROM q UNION ALL SELECT id,2,'Pod''lar arasındaki ağ trafiğini şifreleyen ve yönlendiren veri düzlemi bileşenidir' FROM q UNION ALL SELECT id,3,'Cluster''a yeni node eklendiğinde kubelet''i otomatik configure eden bootstrap bileşenidir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','senior','Chaos engineering nedir ve neden önemlidir?','Chaos engineering, production benzeri ortamda kasıtlı arıza enjekte ederek sistemin dayanıklılığını test eder. Netflix''in Chaos Monkey''si öncülüdür. Prensip: "Kontrollü ortamda sistemin başarısızlığını proaktif keşfetmek, beklenmedik arızadan iyidir." Blast radius kontrol edilir; gözlemlenebilirlik olgunluğu gerektirir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Chaos engineering, tüm servislerin eş zamanlı shutdown edilerek ne kadar hızlı recovery yapıldığını ölçer' FROM q UNION ALL SELECT id,1,'Production''da kontrollü arıza enjekte ederek sistemin beklenmedik durumlara dayanıklılığını proaktif test eder' FROM q UNION ALL SELECT id,2,'Geliştiricilerin kasıtlı olarak hatalı kod yazıp takım arkadaşlarının bunu bulmasını test eden pratiktir' FROM q UNION ALL SELECT id,3,'Chaos engineering yalnızca büyük şirketler için uygundur; startup''larda uygulanması tehlikelidir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','senior','Zero-trust güvenlik modelinin temel prensibi nedir?','Zero-trust: "Hiçbir zaman güvenme, her zaman doğrula." Network perimetresi (VPN) artık güvenlik sınırı sayılmaz. Her istek (iç ağdan bile gelse) kimlik doğrulama ve yetkilendirmeye tabidir. Mikro segmentasyon, least privilege, continuous verification, device health check ve encrypted traffic temel bileşenlerdir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Zero-trust, tüm dış trafiği reddetmek ve yalnızca VPN üzerinden erişime izin vermek anlamına gelir' FROM q UNION ALL SELECT id,1,'Zero-trust, her kullanıcının iki faktörlü kimlik doğrulama yapmasını zorunlu kılan bir IAM modelidir' FROM q UNION ALL SELECT id,2,'Hiçbir zaman güvenme, her zaman doğrula prensibiyle her isteği kaynak/konumdan bağımsız doğrular; mikro segmentasyon uygular' FROM q UNION ALL SELECT id,3,'Zero-trust yalnızca cloud ortamları için geçerlidir; on-premise sistemlerde VPN kullanımı yeterlidir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','senior','Kubernetes RBAC''de Role ve ClusterRole arasındaki fark nedir?','Role: belirli bir namespace içinde izin tanımlar. ClusterRole: cluster genelinde veya tüm namespace''lerde geçerlidir. RoleBinding ve ClusterRoleBinding ile kullanıcı/servis hesabına bağlanır. En az yetki (least privilege) prensibi için namespace''e özgü Role tercih edilir; yalnızca gerçekten gereken kaynaklar için ClusterRole verilir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Role ve ClusterRole aynıdır; fark yalnızca isimlendirme konvansiyonudur' FROM q UNION ALL SELECT id,1,'Role tüm cluster için, ClusterRole ise yalnızca belirli namespace''ler için izin tanımlar' FROM q UNION ALL SELECT id,2,'Role kullanıcılar için, ClusterRole ise yalnızca servis hesapları (ServiceAccount) için kullanılır' FROM q UNION ALL SELECT id,3,'Role namespace''e özgü izin; ClusterRole cluster genelinde geçerli izin tanımlar; least privilege için Role tercih edilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','senior','Disaster recovery''de RTO ve RPO nedir?','RTO (Recovery Time Objective): bir arızadan sonra sistemin ne kadar sürede ayağa kalkması gerektiğinin hedefidir. RPO (Recovery Point Objective): kabul edilebilir maksimum veri kaybı süresini ifade eder (son backup''tan bu yana). RTO düşükse aktif-aktif/aktif-pasif mimarisi; RPO düşükse sürekli replikasyon gerekir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'RTO arızadan recovery süresi hedefi; RPO kabul edilebilir veri kaybı süresidir; her ikisi de DR stratejisini belirler' FROM q UNION ALL SELECT id,1,'RTO toplam kesinti süresi, RPO ise kaç kez backup alındığını ifade eder' FROM q UNION ALL SELECT id,2,'RTO ve RPO yalnızca veritabanı sistemleri için geçerlidir; uygulama katmanında kullanılmaz' FROM q UNION ALL SELECT id,3,'RTO veri yedekleme periyodu, RPO ise yedekten restore etme süresi anlamına gelir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','senior','Container image güvenlik taraması neden önemlidir ve ne tür açıkları tespit eder?','Image tarama: OS paket açıkları (CVE), bilinen kötü amaçlı yazılımlar, hassas bilgi sızıntısı (secret, password), lisans ihlalleri. Trivy, Snyk, Clair gibi araçlar kullanılır. Shift-left güvenlik için CI pipeline''a entegre edilir; production''a açıklı image gönderilmesi engellenir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Image tarama yalnızca lisans uyumluluğunu kontrol eder; CVE tespiti farklı bir araçla yapılır' FROM q UNION ALL SELECT id,1,'OS paketi CVE''leri, secret sızıntısı ve lisans ihlallerini tespit eder; CI pipeline''a entegre edilerek shift-left güvenlik sağlar' FROM q UNION ALL SELECT id,2,'Container image tarama yalnızca Docker Hub''da public image''lar için geçerlidir; private registry''lerde desteklenmez' FROM q UNION ALL SELECT id,3,'Image tarama yalnızca production deploy öncesinde çalıştırılmalıdır; CI sırasında build süresini gereksiz uzatır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','senior','Kubernetes Operator pattern nedir?','Operator, Custom Resource Definition (CRD) ve custom controller birleşimidir. Domain-specific operasyonel bilgiyi (veritabanı yönetimi, backup, failover) Kubernetes API''sine kodlar. Stateful uygulama yaşam döngüsünü (PostgreSQL, Kafka, Elasticsearch cluster''ları) otomatik yönetir. Operator Framework veya Kubebuilder ile yazılır.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Operator, cluster''a yeni node eklendiğinde otomatik konfigürasyon yapan daemonset tabanlı bir bileşendir' FROM q UNION ALL SELECT id,1,'Operator, birden fazla Kubernetes cluster''ını tek pane of glass ile yöneten federation aracıdır' FROM q UNION ALL SELECT id,2,'CRD + custom controller ile domain operasyonel bilgisini Kubernetes API''ye kodlar; stateful uygulamaları otomatik yönetir' FROM q UNION ALL SELECT id,3,'Operator yalnızca Helm chart''larını otomatik güncelleyen bir GitOps bileşenidir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','senior','Cloud maliyetlerini optimize etmek için hangi stratejiler kullanılır?','Cost optimization: Reserved/Savings Plan (uzun süreli taahhüt indirimi), Spot/Preemptible instance (kesilebilir, ucuz), Right-sizing (kullanılan kaynağa göre boyutlandırma), Auto-scaling (kullanılmayan kapasite kapatma), S3 lifecycle policy (eski veriyi Glacier''a taşıma), idle resource temizleme.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Yalnızca tek bir cloud provider kullanmak maliyeti minimize eder; multi-cloud her zaman daha pahalıdır' FROM q UNION ALL SELECT id,1,'Tüm workload''ları aynı instance tipine taşımak en büyük maliyet düşüşünü sağlar' FROM q UNION ALL SELECT id,2,'Cloud maliyeti yalnızca compute''dan kaynaklanır; storage ve network maliyetleri optimize edilemez' FROM q UNION ALL SELECT id,3,'Reserved instance, Spot kullanımı, right-sizing, auto-scaling ve idle resource temizleme temel optimizasyon stratejileridir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','mid','Docker Compose''da servisler arasındaki ağ iletişimi nasıl sağlanır?','Docker Compose, varsayılan olarak tüm servisler için ortak bir bridge network oluşturur. Servisler birbirine servis adıyla (hostname) ulaşabilir: `db`, `redis` gibi. Port expose etmek dışa değil, yalnızca aynı network içindeki diğer servislere erişim içindir. Custom network ile servis izolasyonu yapılabilir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Ortak bridge network oluşturulur; servisler birbirine servis adı (hostname) ile ulaşır; port expose dış erişim içindir' FROM q UNION ALL SELECT id,1,'Servisler yalnızca IP adresiyle iletişim kurabilir; hostname çözümlemesi Docker Compose''da desteklenmez' FROM q UNION ALL SELECT id,2,'Her servis kendi izole network''ünde çalışır; servisler arası iletişim için links: tanımı zorunludur' FROM q UNION ALL SELECT id,3,'Docker Compose ağ yönetimi yapmaz; servisler arası iletişim için localhost kullanılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','mid','ELK/EFK stack''i log aggregation için nasıl kullanılır?','ELK: Elasticsearch (depolama/arama), Logstash (toplama/dönüştürme), Kibana (görselleştirme). EFK''da Logstash yerine Fluentd/Fluent Bit kullanılır; daha hafiftir, Kubernetes DaemonSet olarak çalışır. Structured logging (JSON) log kalitesini artırır. Kibana''da index pattern tanımlanarak sorgulama yapılır.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'ELK yalnızca uygulama logları için kullanılır; sistem ve Kubernetes loglarını toplama yeteneği yoktur' FROM q UNION ALL SELECT id,1,'Elasticsearch log depolar/arar, Logstash/Fluentd toplar/dönüştürür, Kibana görselleştirir; structured logging kaliteyi artırır' FROM q UNION ALL SELECT id,2,'ELK stack yalnızca on-premise ortamlar için uygundur; cloud''da managed logging servisleri tercih edilmelidir' FROM q UNION ALL SELECT id,3,'ELK ve EFK arasında teknik fark yoktur; isim farkı yalnızca pazarlama amaçlıdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','junior','Kubernetes''te namespace ne işe yarar?','Namespace, tek bir Kubernetes cluster''ını sanal olarak birden fazla ortama (dev, staging, prod) veya takıma böler. Kaynak isimleri namespace içinde benzersiz olmalıdır. ResourceQuota ile namespace başına CPU/memory limiti, NetworkPolicy ile ağ izolasyonu sağlanabilir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Namespace, farklı Kubernetes versiyonlarını aynı sunucuda çalıştırmak için kullanılan izolasyon katmanıdır' FROM q UNION ALL SELECT id,1,'Namespace, container''ların disk alanını izole ederek birbirinin dosyalarına erişimini engeller' FROM q UNION ALL SELECT id,2,'Cluster''ı sanal ortamlara böler; kaynak quota ve ağ izolasyonu sağlar; ortak kaynak isimleri içinde benzersiz olmalıdır' FROM q UNION ALL SELECT id,3,'Namespace yalnızca RBAC ile kullanıldığında anlam ifade eder; aksi halde boş bir klasör gibi çalışır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('devops','tr','junior','Dockerfile''da `.dockerignore` dosyasının amacı nedir?','`.dockerignore`, build context''e dahil edilmeyecek dosya ve klasörleri belirtir. `node_modules`, `.git`, test dosyaları, log''lar gibi büyük veya gereksiz dosyalar hariç tutularak: build context boyutu küçülür, build hızlanır ve `node_modules` gibi klasörlerin yanlışlıkla image''a kopyalanması önlenir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'.dockerignore, container çalışırken erişilemeyen dosyaları listeleyen güvenlik konfigürasyonudur' FROM q UNION ALL SELECT id,1,'.dockerignore, production image''dan kaldırılacak debug araçlarını tanımlayan deployment konfigürasyonudur' FROM q UNION ALL SELECT id,2,'.dockerignore, Dockerfile''daki IGNORE talimatının okunacağı kaynak dosyadır' FROM q UNION ALL SELECT id,3,'Build context''e dahil edilmeyecek dosyaları belirtir; context boyutunu küçültür ve gereksiz dosyaların image''a girmesini önler' FROM q;

