WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','junior','SQL''de INNER JOIN ve LEFT JOIN arasındaki fark nedir?','INNER JOIN: her iki tabloda da eşleşen satırları döndürür; eşleşme yoksa her iki taraf da sonuçta yer almaz. LEFT JOIN: sol tablonun tüm satırlarını döndürür; sağ tabloda eşleşme yoksa NULL değerleriyle doldurulur. Hangi JOIN türünün kullanılacağı iş mantığına göre belirlenir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'INNER JOIN yalnızca her iki tabloda eşleşen satırları döndürür; LEFT JOIN sol tablonun tüm satırlarını, eşleşmeyenleri NULL ile döndürür' FROM q UNION ALL SELECT id,1,'LEFT JOIN yalnızca eşleşen satırları, INNER JOIN ise tüm satırları döndürür' FROM q UNION ALL SELECT id,2,'INNER JOIN büyük tablolarda, LEFT JOIN ise yalnızca küçük tablolarda performanslı çalışır' FROM q UNION ALL SELECT id,3,'İkisi aynı sonucu döndürür; fark yalnızca yazım sırasındadır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','junior','PRIMARY KEY ile UNIQUE constraint arasındaki fark nedir?','PRIMARY KEY: tabloda yalnızca bir tane olabilir, NULL değer kabul etmez, otomatik clustered index (bazı DB''lerde) oluşturur. UNIQUE: bir tabloda birden fazla olabilir, NULL değere izin verir (bazı DB''lerde birden fazla NULL kabul edilir). Her ikisi de tekliği garanti eder.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'PRIMARY KEY NULL''a izin verir; UNIQUE constraint hiçbir zaman NULL kabul etmez' FROM q UNION ALL SELECT id,1,'PRIMARY KEY tabloda tek, NULL kabul etmez; UNIQUE birden fazla tanımlanabilir, NULL''a izin verebilir' FROM q UNION ALL SELECT id,2,'İkisi de aynıdır; PRIMARY KEY sadece sütuna verilen özel bir isimdir' FROM q UNION ALL SELECT id,3,'UNIQUE index otomatik oluşturur; PRIMARY KEY yalnızca logical kısıtlamadır, index oluşturmaz' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','junior','SQL''de WHERE ve HAVING arasındaki fark nedir?','WHERE, GROUP BY''dan önce uygulanır ve bireysel satırları filtreler; aggregate fonksiyon (SUM, COUNT) kullanamaz. HAVING, GROUP BY''dan sonra uygulanır ve grupları filtreler; aggregate fonksiyonlarla çalışır. Performans için önce WHERE ile satır sayısını azaltmak tercih edilir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'WHERE gruplara, HAVING ise bireysel satırlara uygulanır' FROM q UNION ALL SELECT id,1,'WHERE ve HAVING aynı işlevi görür; GROUP BY ile birlikte kullanıldığında HAVING tercih edilmesi sadece okunabilirlik içindir' FROM q UNION ALL SELECT id,2,'WHERE GROUP BY öncesi bireysel satırları, HAVING GROUP BY sonrası grupları filtreler; HAVING aggregate fonksiyon kullanabilir' FROM q UNION ALL SELECT id,3,'WHERE yalnızca string sütunlarda, HAVING ise yalnızca sayısal sütunlarda kullanılabilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','junior','Veritabanında index neden kullanılır?','Index, tablodaki verilerin hızlı bulunmasını sağlayan veri yapısıdır (genellikle B-tree). Index olmadan tablo taraması (full scan) yapılır: O(n). Index ile O(log n) arama mümkün olur. Ancak her index yazma işlemlerini (INSERT/UPDATE/DELETE) yavaşlatır ve disk alanı tüketir; doğru denge kurulmalıdır.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Index, tablodaki tüm verilerin sıkıştırılarak saklanmasını sağlar; bu disk alanı kazandırır' FROM q UNION ALL SELECT id,1,'Index, farklı tablolar arasındaki JOIN işlemlerini otomatik olarak gerçekleştirir' FROM q UNION ALL SELECT id,2,'Index, eş zamanlı okuma/yazma işlemlerinde veri tutarlılığını sağlayan kilit mekanizmasıdır' FROM q UNION ALL SELECT id,3,'Sorgu performansını artıran veri yapısıdır (B-tree); yazma işlemlerini yavaşlatır ve ek disk alanı gerektirir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','junior','SQL''de NULL değer nasıl kontrol edilir?','NULL, "bilinmeyen değer"i temsil eder. `= NULL` veya `!= NULL` kullanılamaz; her zaman `IS NULL` veya `IS NOT NULL` kullanılmalıdır. `NULL = NULL` ifadesi FALSE değil UNKNOWN döndürür. COALESCE(col, default) ile NULL yerine varsayılan değer döndürülebilir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'NULL için = NULL değil IS NULL kullanılmalıdır; NULL = NULL ifadesi UNKNOWN döndürür; COALESCE ile varsayılan değer verilir' FROM q UNION ALL SELECT id,1,'NULL sıfır ile eşdeğerdir; WHERE col = 0 ile NULL değerler sorgulanabilir' FROM q UNION ALL SELECT id,2,'NULL kontrol için her zaman ISNULL() fonksiyonu kullanılmalıdır; IS NULL operatörü standart değildir' FROM q UNION ALL SELECT id,3,'NULL, boş string ile aynıdır; WHERE col = '''' ifadesi NULL değerleri de bulur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','junior','ACID özelliklerinden Atomicity (Bölünmezlik) ne anlama gelir?','Atomicity: bir transaction''daki tüm işlemler ya tamamen başarılı olur ya da hiçbiri uygulanmaz. Banka transferi örneği: hesaptan para çıkma ve diğer hesaba yatma aynı transaction''da olmalıdır; biri başarısız olursa tüm transaction geri alınır (rollback).',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Atomicity, transaction''ların eş zamanlı çalışırken birbirinin verilerini göremeyeceğini garanti eder' FROM q UNION ALL SELECT id,1,'Transaction''daki tüm işlemler ya tamamen tamamlanır ya da hiçbiri uygulanmaz; kısmi sonuç kabul edilmez' FROM q UNION ALL SELECT id,2,'Atomicity, veritabanı bozulsa bile transaction verilerinin kurtarılabileceğini garanti eder' FROM q UNION ALL SELECT id,3,'Atomicity, aynı transaction''ın birden fazla kez çalıştırılmasının aynı sonucu üretmesini garantiler' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','junior','FOREIGN KEY kısıtlaması ne sağlar?','FOREIGN KEY, bir tablodaki sütunun başka bir tablonun PRIMARY KEY veya UNIQUE sütununa referans vermesini zorunlu kılar. Referential integrity sağlar: referans edilen kayıt yoksa insert reddedilir, referans edilen kayıt silinirse CASCADE/RESTRICT/SET NULL davranışı devreye girer.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'FOREIGN KEY, iki tablo arasındaki JOIN işleminin performansını artırmak için kullanılan bir optimizasyon ipucudur' FROM q UNION ALL SELECT id,1,'FOREIGN KEY, bir sütunun değerinin tablo içinde benzersiz olmasını zorunlu kılan kısıtlamadır' FROM q UNION ALL SELECT id,2,'Referential integrity sağlar; referans edilen kayıt yoksa insert reddedilir, CASCADE/RESTRICT/SET NULL ile silme davranışı tanımlanır' FROM q UNION ALL SELECT id,3,'FOREIGN KEY, iki tablo arasındaki veriyi otomatik senkronize eden bir trigger mekanizmasıdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','junior','SQL''de DELETE ve TRUNCATE arasındaki fark nedir?','DELETE: WHERE ile koşullu veya koşulsuz satır siler; her satır için trigger çalışır, transaction log''a yazılır, rollback edilebilir. TRUNCATE: tüm tabloyu siler; DDL işlemidir, log''a daha az yazar, auto-increment sıfırlanır, genellikle geri alınamaz (bazı DB''lerde transaction içinde kullanılabilir).',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'DELETE yalnızca WHERE ile kullanılabilir; koşulsuz silme için TRUNCATE zorunludur' FROM q UNION ALL SELECT id,1,'TRUNCATE tek satır siler; DELETE tüm tabloyu siler' FROM q UNION ALL SELECT id,2,'İkisi aynı sonucu üretir; TRUNCATE daha az yazılması gereken kısaltılmış DELETE sözdizimidir' FROM q UNION ALL SELECT id,3,'DELETE koşullu/koşulsuz satır siler, rollback edilebilir, trigger çalışır; TRUNCATE tüm tabloyu hızla siler, log azaltır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','junior','SQL''de GROUP BY ne işe yarar?','GROUP BY, belirtilen sütundaki aynı değere sahip satırları gruplar. Aggregate fonksiyonlarla (COUNT, SUM, AVG, MIN, MAX) birlikte kullanılır. SELECT''te GROUP BY''da olmayan sütunlar doğrudan kullanılamaz (aggregate fonksiyon olmadan). HAVING ile grup filtrelemesi yapılır.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Belirtilen sütuna göre satırları gruplar; COUNT, SUM, AVG gibi aggregate fonksiyonlarla birlikte grup bazında hesaplama yapar' FROM q UNION ALL SELECT id,1,'GROUP BY, sonuçları sıralayan ve DISTINCT ile aynı işlevi gören bir anahtar kelimedir' FROM q UNION ALL SELECT id,2,'GROUP BY, yalnızca JOIN''li sorgularda kullanılabilir; tek tablo sorgularında desteklenmez' FROM q UNION ALL SELECT id,3,'GROUP BY birden fazla tablodaki aynı verileri tek satırda birleştiren deduplikasyon işlemidir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','junior','SQL''de subquery (alt sorgu) nedir?','Subquery, başka bir SQL ifadesi içine yerleştirilmiş SELECT sorgusudur. WHERE, FROM (derived table), SELECT (scalar subquery) ve HAVING içinde kullanılabilir. Correlated subquery dış sorgunun her satırı için yeniden çalışır; CTE veya JOIN ile genellikle daha verimli alternatifi yazılabilir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Subquery, iki tabloyu JOIN yapmadan birleştiren özel bir SQL sözdizimdir' FROM q UNION ALL SELECT id,1,'Başka bir SQL ifadesi içine yerleştirilmiş SELECT sorgusudur; WHERE, FROM veya SELECT içinde kullanılabilir' FROM q UNION ALL SELECT id,2,'Subquery yalnızca DELETE ve UPDATE ifadelerinde kullanılabilir; SELECT ile uyumsuzludur' FROM q UNION ALL SELECT id,3,'Subquery, stored procedure içinde tanımlanan ve dışarıdan çağrılabilen yeniden kullanılabilir sorgudur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','junior','SQL''de transaction COMMIT ve ROLLBACK ne anlama gelir?','Transaction başlatıldıktan sonra yapılan değişiklikler geçici olarak saklanır. COMMIT ile değişiklikler kalıcı hale getirilir ve diğer transaction''lar görebilir. ROLLBACK ile tüm değişiklikler geri alınır, veritabanı transaction öncesi duruma döner. SAVEPOINT ile kısmi rollback mümkündür.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'COMMIT veritabanı bağlantısını kapatır; ROLLBACK yeni bağlantı açar' FROM q UNION ALL SELECT id,1,'COMMIT değişiklikleri siler; ROLLBACK değişiklikleri kalıcı hale getirir' FROM q UNION ALL SELECT id,2,'COMMIT değişiklikleri kalıcı yapar; ROLLBACK tüm değişiklikleri geri alarak transaction öncesi duruma döner' FROM q UNION ALL SELECT id,3,'COMMIT ve ROLLBACK yalnızca stored procedure içinde kullanılabilir; normal SQL sorgularında geçersizdir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','junior','VARCHAR ve TEXT veri tipleri arasındaki fark nedir?','VARCHAR(n): maksimum n karakter uzunluğunu kısıtlar; kısa ve değişken uzunluklu string''ler için uygundur. TEXT: teorik olarak sınırsız uzunlukta metin saklar. PostgreSQL''de ikisi de aynı depolama mekanizmasını kullanır. Uygulama katmanında validation için VARCHAR uzunluk limiti tercih edilir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'TEXT yalnızca tek satır metin, VARCHAR ise çok satırlı metin için kullanılır' FROM q UNION ALL SELECT id,1,'VARCHAR her zaman TEXT''ten daha hızlıdır; TEXT büyük veriler için zorunludur' FROM q UNION ALL SELECT id,2,'TEXT şifreli saklar; VARCHAR ise düz metin olarak depolar' FROM q UNION ALL SELECT id,3,'VARCHAR maksimum uzunluk kısıtlar (uygulama validasyonu için faydalı); TEXT teorik sınırsız; PostgreSQL''de depolama aynı' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','mid','Composite index''te sütun sırası neden kritiktir?','B-tree composite index en soldaki sütun(lar)dan başlayarak kullanılır (leftmost prefix rule). (a, b, c) index: WHERE a=1, WHERE a=1 AND b=2, ORDER BY a, b sorgularını destekler. WHERE b=2 yalnız başına bu index''i kullanamaz. Sık sorgulanan ve yüksek kardinaliteli sütun sola konulmalıdır.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Leftmost prefix rule''a göre en soldaki sütundan başlayarak kullanılır; ortadaki/sondaki sütun tek başına sorgulanırsa index devreye girmez' FROM q UNION ALL SELECT id,1,'Sütun sırası önemsizdir; query planner her zaman en uygun sütunu otomatik seçer' FROM q UNION ALL SELECT id,2,'Alfabetik sırayla tanımlanmalıdır; aksi halde index oluşturulur ama planner görmezden gelir' FROM q UNION ALL SELECT id,3,'Sütun sırası yalnızca ORDER BY sorgularını etkiler; WHERE koşullarında fark yaratmaz' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','mid','PostgreSQL''de EXPLAIN ANALYZE nasıl kullanılır ve nelere bakılır?','EXPLAIN ANALYZE sorguyu çalıştırır ve gerçek execution planını gösterir. Dikkat edilecekler: Seq Scan (full table scan - index yok mu?), yüksek cost tahmini, actual vs estimated row count farkı (istatistik güncel mi?), Hash Join vs Nested Loop vs Merge Join seçimi, toplam execution time.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'EXPLAIN ANALYZE yalnızca tahmini maliyet gösterir; gerçek çalışma süresi görüntülenmez' FROM q UNION ALL SELECT id,1,'Gerçek execution planını ve süreyi gösterir; Seq Scan, row count tahmini, Join tipi ve toplam süre incelenir' FROM q UNION ALL SELECT id,2,'EXPLAIN ANALYZE yalnızca SELECT sorgularında çalışır; INSERT/UPDATE/DELETE''de kullanılamaz' FROM q UNION ALL SELECT id,3,'EXPLAIN ANALYZE sorguyu çalıştırmadan tahmini plan gösterir; production''da güvenle kullanılabilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','mid','ORM kullanırken N+1 sorunu nasıl oluşur ve çözüm yolları nelerdir?','N+1: 1 sorgu ile N user çekilir, ardından her user için ayrı query ile orders sorgulanır (N sorgu = toplam N+1). Çözüm: eager loading (JOIN ile tek sorguda ilişkili veriyi getirme; JPA''da `@EntityGraph` veya `JOIN FETCH`), batch loading (IN clause), GraphQL DataLoader (N sorguyu 1''e indirme).',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'N+1 sorunu yalnızca NoSQL veritabanlarında oluşur; SQL ORM''ler otomatik optimize eder' FROM q UNION ALL SELECT id,1,'N+1 yalnızca birden fazla veritabanı kullanıldığında ortaya çıkar; single DB''de sorun oluşmaz' FROM q UNION ALL SELECT id,2,'1 ana sorgu + her kayıt için ek N sorgu çalışmasıdır; eager loading (JOIN FETCH, IN clause) veya DataLoader ile çözülür' FROM q UNION ALL SELECT id,3,'N+1, N adet tablonun tek sorguda JOIN edilmesinin yarattığı bellek sorunudur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','mid','Transaction isolation level''larından READ COMMITTED ve REPEATABLE READ arasındaki fark nedir?','READ COMMITTED: transaction boyunca aynı satır tekrar okunursa farklı değer gelebilir (non-repeatable read mümkün). REPEATABLE READ: transaction başında okunan satır değeri transaction boyunca değişmez; phantom read riski vardır (PostgreSQL''de MVCC sayesinde phantom read''e karşı da koruma sağlar).',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'READ COMMITTED daha düşük performans sağlar; REPEATABLE READ her zaman daha hızlıdır' FROM q UNION ALL SELECT id,1,'İki level arasında teknik fark yoktur; tercih yalnızca uygulama koduna bağlıdır' FROM q UNION ALL SELECT id,2,'READ COMMITTED tüm dirty read''lere izin verir; REPEATABLE READ phantom read''e de izin verir' FROM q UNION ALL SELECT id,3,'READ COMMITTED aynı satırın tekrar okunmasında farklı değer görebilir (non-repeatable read); REPEATABLE READ transaction boyunca aynı değeri garanti eder' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','mid','SQL''de window function nedir ve aggregate function''dan farkı nedir?','Window function (ROW_NUMBER, RANK, LAG, LEAD, SUM OVER) her satır için hesaplama yapar ancak satırları gruplamaz; tüm satırlar sonuçta kalır. Aggregate function (GROUP BY ile) satırları gruplar, grup başına tek satır döner. Window function ile her satır için kümülatif toplam, sıralama veya önceki satır değeri erişilebilir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Window function satır sayısını azaltmaz; her satır için OVER() ile tanımlı penceredeki hesaplamayı döndürür; aggregate gruplama yapar' FROM q UNION ALL SELECT id,1,'Window function yalnızca sıralama (ORDER BY) işlemleri için kullanılır; diğer hesaplamalar için aggregate tercih edilir' FROM q UNION ALL SELECT id,2,'Window function aggregate fonksiyonların alias''ıdır; yalnızca yazım şekli farklıdır' FROM q UNION ALL SELECT id,3,'Window function GROUP BY ile birlikte kullanılmak zorundadır; bağımsız kullanımı hata üretir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','mid','CTE (Common Table Expression) ile subquery arasında ne tercih edilmeli?','CTE (WITH clause): okunabilirliği artırır, aynı CTE birden fazla kullanılabilir, recursive sorgular mümkündür. Subquery: inline yazılır. PostgreSQL''de CTE optimizasyon fence olabilir (12 öncesi planner CTE''yi optimize etmezdi). Karmaşık sorgularda CTE okunabilirliği nedeniyle tercih edilir; performans kritikse EXPLAIN ile kontrol edilmelidir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'CTE her zaman subquery''den daha hızlıdır; production''da daima CTE tercih edilmelidir' FROM q UNION ALL SELECT id,1,'CTE okunabilirliği artırır, recursive sorgulara izin verir, aynı CTE birden fazla yerde kullanılabilir; performans EXPLAIN ile doğrulanmalıdır' FROM q UNION ALL SELECT id,2,'CTE yalnızca PostgreSQL''de desteklenir; diğer veritabanlarında subquery zorunludur' FROM q UNION ALL SELECT id,3,'Subquery her zaman CTE''den daha performanslıdır; CTE yalnızca okunabilirlik için kabul edilebilir bir seçimdir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','mid','PostgreSQL''de JSONB ve JSON veri tipleri arasındaki fark nedir?','JSON: metni olduğu gibi saklar, key sırasını ve tekrar eden key''leri korur, her sorguda yeniden parse edilir. JSONB: binary formatta saklar, key sırasını korumaz, tekrar eden key''lerin son değerini alır, sorgulama daha hızlıdır ve GIN index desteği vardır. Genel olarak JSONB tercih edilir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'JSON daha büyük dosyalar için, JSONB ise yalnızca küçük JSON nesneleri için uygundur' FROM q UNION ALL SELECT id,1,'JSON ve JSONB aynı veriyi saklar; fark yalnızca okuma hızında küçük farklılıktır' FROM q UNION ALL SELECT id,2,'JSONB binary formatta saklar, GIN index destekler, sorgulama hızlıdır; JSON orijinal formatı korur ama her sorguda parse edilir' FROM q UNION ALL SELECT id,3,'JSONB şifreli saklama yapar; JSON ise düz metin olarak depolar' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','mid','Partial index nedir ve ne zaman kullanılır?','Partial index (PostgreSQL: CREATE INDEX ... WHERE ...), tablonun yalnızca belirli koşulu sağlayan satırlarını indeksler. Avantaj: index boyutu küçülür, yalnızca sık sorgulanan subset indekslenir. Örnek: aktif kullanıcılar için `WHERE active = true` partial index, 90% pasif kullanıcıyı kapsam dışı bırakır.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Partial index, bir sütunun yalnızca ilk N karakterini indeksleyen prefix index türüdür' FROM q UNION ALL SELECT id,1,'Partial index, bölünmüş (partitioned) tablolarda her bölüm için ayrı index oluşturmayı otomatikleştirir' FROM q UNION ALL SELECT id,2,'Partial index, composite index''in ilk sütunu atlanarak ortadaki sütundan başlatılmasıdır' FROM q UNION ALL SELECT id,3,'WHERE koşuluyla tablonun bir alt kümesini indeksler; index boyutunu küçültür, sık sorgulanan subset için hız kazandırır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','mid','3NF (Üçüncü Normal Form) normalizasyonu ne zaman ihlal edilir?','3NF: her non-key sütun yalnızca primary key''e bağımlı olmalıdır; başka non-key sütuna (transitif bağımlılık) bağımlı olmamalıdır. Orders tablosunda city sütunu customer_id''ye değil, zip_code''a bağımlıysa 3NF ihlali vardır; zip_code ve city ayrı tabloya taşınmalıdır.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Non-key sütunun primary key''e değil başka non-key sütuna (transitif) bağımlı olmasıdır; bağımlı sütunlar ayrı tabloya taşınmalıdır' FROM q UNION ALL SELECT id,1,'3NF, bir tabloda birden fazla sütunun aynı değeri içermesiyle ihlal edilir' FROM q UNION ALL SELECT id,2,'3NF ihlali yalnızca composite primary key içeren tablolarda oluşur; tek sütun PK''da mümkün değildir' FROM q UNION ALL SELECT id,3,'3NF, tabloda NULL değer içeren sütun bulunduğunda ihlal edilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','mid','Veritabanı connection pooling neden gereklidir?','Her veritabanı bağlantısı kurulumu: TCP bağlantısı, TLS handshake, authentication = yüksek maliyet. Connection pool önceden kurulmuş bağlantıları hazır tutar; istek gelince pool''dan alınır, biter bitmez geri verilir. Max bağlantı sayısı sınırlanarak DB overload önlenir. PgBouncer, HikariCP yaygın pool''lardır.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Connection pooling yalnızca NoSQL veritabanları için gereklidir; SQL DB''ler kendi connection''larını yönetir' FROM q UNION ALL SELECT id,1,'Her bağlantı kurulumunun maliyetini ortadan kaldırır; önceden kurulu bağlantılar yeniden kullanılır, DB yük sınırı korunur' FROM q UNION ALL SELECT id,2,'Connection pooling yalnızca read replika konfigürasyonlarında gereklidir' FROM q UNION ALL SELECT id,3,'Connection pooling veritabanı şifrelemesini yöneterek bağlantı başına TLS overhead''ini azaltır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','mid','Sharding ile horizontal partitioning (table partitioning) arasındaki fark nedir?','Table partitioning: aynı veritabanında tek tablonun verisi mantıksal bölümlere ayrılır (range, list, hash); sorgu planner partition pruning yapar. Sharding: veri fiziksel olarak farklı veritabanı sunucularına (shard) dağıtılır; uygulama katmanı veya shard router hangi shard''ın sorgulanacağını belirler. Sharding operasyonel karmaşıklığı artırır.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Sharding ve partitioning aynı şeydir; yalnızca kullanılan veritabanı sistemine göre isim farklılığı vardır' FROM q UNION ALL SELECT id,1,'Partitioning yalnızca NoSQL, sharding ise yalnızca SQL veritabanlarında uygulanabilir' FROM q UNION ALL SELECT id,2,'Partitioning aynı DB''de mantıksal bölümleme; sharding farklı sunuculara fiziksel dağıtım; sharding operasyonel karmaşıklığı artırır' FROM q UNION ALL SELECT id,3,'Sharding tek veritabanında yapılır; partitioning ise birden fazla sunucu gerektirir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','mid','Read replica nedir ve ne zaman kullanılır?','Read replica: primary DB''nin asenkron veya senkron kopyasıdır; yalnızca okuma istekleri yönlendirilir. Avantajları: read yükünü primary''den alır, analytics/raporlama sorgularını izole eder. Dezavantaj: replication lag nedeniyle replica üzerindeki veri biraz geride kalabilir (eventual consistency).',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Read replica, yazma hatalarında otomatik devralma (failover) yapan backup sunucusudur' FROM q UNION ALL SELECT id,1,'Read replica, sorguları optimize ederek primary DB''nin 10x daha hızlı çalışmasını sağlar' FROM q UNION ALL SELECT id,2,'Read replica yalnızca tam özdeş bir yedekleme sunucusudur; erişim primary arıza yapana kadar kapalıdır' FROM q UNION ALL SELECT id,3,'Primary''nin kopyasıdır; read trafiğini dağıtır; replication lag nedeniyle eventual consistency söz konusudur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','senior','PostgreSQL''de MVCC (Multi-Version Concurrency Control) nasıl çalışır?','MVCC: her transaction kendi snapshot''ını görür. UPDATE işlemi eski satırı silmez; yeni tuple oluşturur ve eski tuple''ı geçersiz işaretler. Reader''lar writer''ları bloklamaz; writer''lar reader''ları bloklamaz. Bu sayede yüksek eş zamanlılık sağlanır. VACUUM eski tuple''ları temizler.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Her transaction kendi snapshot''ını görür; UPDATE yeni tuple oluşturur, eskisini geçersiz işaretler; reader/writer birbirini bloklamaz' FROM q UNION ALL SELECT id,1,'MVCC, birden fazla primary DB arasındaki version senkronizasyonunu yöneten replikasyon protokolüdür' FROM q UNION ALL SELECT id,2,'MVCC yalnızca SELECT sorgularında aktiftir; INSERT/UPDATE/DELETE işlemleri kilit kullanır' FROM q UNION ALL SELECT id,3,'MVCC, veritabanı yöneticisinin aynı şemada birden fazla versiyon tutmasını sağlayan migration aracıdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','senior','PostgreSQL''de WAL (Write-Ahead Log) nedir?','WAL: veri dosyasına yazmadan önce değişiklikler log''a yazılır. Crash recovery için kritiktir: DB çöktükten sonra WAL replay edilerek tutarlı durum geri yüklenir. Ayrıca streaming replication''ın (replica''ya log gönderme) ve point-in-time recovery (PITR)''nin temelidir. Write performance etkilenir ancak durability garanti edilir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'WAL, yalnızca transaction log kayıtlarını tutan ve billing/audit için kullanılan bir özelliğidir' FROM q UNION ALL SELECT id,1,'Değişiklikler veri dosyasına yazmadan önce log''a yazılır; crash recovery, streaming replication ve PITR''nin temelidir' FROM q UNION ALL SELECT id,2,'WAL, büyük sorguları paralel işlemek için kullanılan query parallelization mekanizmasıdır' FROM q UNION ALL SELECT id,3,'WAL yalnızca DDL işlemlerini (CREATE, ALTER, DROP) loglar; DML işlemleri loga yazılmaz' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','senior','B-tree index ile Hash index arasındaki fark ve kullanım senaryoları nelerdir?','B-tree: sıralı yapı, equality (=), range (<, >, BETWEEN) ve LIKE ''prefix%'' sorgularını destekler; çoğu durum için varsayılan seçim. Hash: yalnızca equality (=) sorgularını destekler, range sorgusuna uygun değildir, PostgreSQL''de WAL loglanmıyordu (artık destekleniyor). B-tree genel amaçlı; Hash yalnızca exact match için marginal avantaj.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Hash index her durumda B-tree''den daha hızlıdır; SQL standardı Hash index kullanımını zorunlu kılar' FROM q UNION ALL SELECT id,1,'B-tree yalnızca text sütunlar için, Hash ise yalnızca sayısal sütunlar için kullanılabilir' FROM q UNION ALL SELECT id,2,'B-tree equality ve range sorgularını destekler, genel amaçlıdır; Hash yalnızca equality için uygundur, range desteği yoktur' FROM q UNION ALL SELECT id,3,'Hash index daha az disk alanı kullandığı için her zaman B-tree yerine tercih edilmelidir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','senior','PostgreSQL''de VACUUM neden gereklidir?','MVCC nedeniyle UPDATE/DELETE işlemleri eski tuple''ları fiziksel olarak silmez; dead tuple birikir ve bloat oluşur. VACUUM dead tuple''ları temizler ve alanı yeniden kullanıma açar. AUTOVACUUM daemon bunu otomatik yapar. VACUUM ANALYZE istatistikleri de günceller. Transaction ID wraparound''u önlemek için VACUUM FREEZE kritiktir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'VACUUM yalnızca disk alanı geri kazanmak için kullanılır; sorgu performansı üzerinde etkisi yoktur' FROM q UNION ALL SELECT id,1,'VACUUM yalnızca manuel olarak çalıştırılır; PostgreSQL otomatik vacuum özelliği sunmaz' FROM q UNION ALL SELECT id,2,'VACUUM tüm tabloyu yeniden yazarak fragmentasyonu giderir; büyük tablolarda kesintiye neden olur' FROM q UNION ALL SELECT id,3,'MVCC''nin bıraktığı dead tuple''ları temizler; bloat''u azaltır, istatistik günceller, transaction ID wraparound''u önler' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','senior','Distributed transaction''larda Two-Phase Commit (2PC) nasıl çalışır ve dezavantajı nedir?','2PC: Prepare aşaması (coordinator tüm katılımcılara "hazır mısın?" sorar; hepsi PREPARED yanıtı verirse), Commit aşaması (coordinator COMMIT gönderir). Bir katılımcı hazır değilse ABORT. Dezavantaj: coordinator çöktüğünde katılımcılar indefinitely locked kalabilir (blocking protocol); yüksek latency.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Prepare (hepsi hazır mı?) + Commit aşamasından oluşur; coordinator çöktüğünde katılımcılar kilitlenebilir (blocking protocol), yüksek latency' FROM q UNION ALL SELECT id,1,'2PC yalnızca NoSQL veritabanları arasında çalışır; SQL veritabanları distributed transaction desteklemez' FROM q UNION ALL SELECT id,2,'2PC tüm katılımcıların eş zamanlı commit yapmasını sağlar; coordinator olmadan peer-to-peer protokoldür' FROM q UNION ALL SELECT id,3,'2PC yalnızca mikroservis mimarisinde kullanılır; monolith uygulamalar 2PC gerektirmez' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','senior','Consistent hashing veritabanı sharding''de nasıl kullanılır?','Consistent hashing: hem veri hem node''lar bir ring üzerinde konumlanır; veri, clockwise''daki ilk node''a atanır. Node eklenip çıkarıldığında yalnızca komşu node''lardan veri taşınır (minimum rebalancing). Traditional modulo sharding''de node değişiminde neredeyse tüm veri taşınır. Redis Cluster consistent hashing tabanlıdır.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Consistent hashing, tüm node''lara eşit veri dağıtımı sağlamak için her shard''ın kapasitesini otomatik dengeler' FROM q UNION ALL SELECT id,1,'Veri ve node''lar ring üzerinde konumlanır; node değişiminde yalnızca komşu node''dan veri taşınır, rebalancing minimize edilir' FROM q UNION ALL SELECT id,2,'Consistent hashing yalnızca cache sistemlerinde (memcached) kullanılır; veritabanı sharding''de uygulanamaz' FROM q UNION ALL SELECT id,3,'Consistent hashing tüm shard''ların aynı hash fonksiyonunu kullanmasını zorunlu kılan bir protokoldür' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','senior','Columnar storage (sütun tabanlı depolama) row storage''dan ne zaman üstündür?','Columnar: her sütun ayrı depolanır; analitik sorgularda yalnızca ilgili sütunlar okunur (I/O azalır). Sütun değerleri benzer olduğundan sıkıştırma oranı yüksektir. OLAP, raporlama, büyük veri toplamları için idealdir. Row storage: tüm satır birlikte saklanır; OLTP (tek kayıt CRUD) için üstündür.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Columnar storage her durumda row storage''dan daha hızlıdır; modern DB''ler varsayılan olarak columnar kullanır' FROM q UNION ALL SELECT id,1,'Columnar storage yalnızca NoSQL sistemlerde desteklenir; SQL veritabanları row storage kullanmak zorundadır' FROM q UNION ALL SELECT id,2,'OLAP ve analitik sorgularda az sütun okunması ve yüksek sıkıştırma nedeniyle üstündür; OLTP tek kayıt CRUD''da row daha iyidir' FROM q UNION ALL SELECT id,3,'Columnar storage yazma işlemlerinde row storage''dan daha hızlıdır; okumada ise eşit performans sağlar' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','senior','Materialized view ile normal view arasındaki fark nedir?','Normal view: sorgu için bir kısayoldur; çalıştırıldığında her seferinde altta yatan sorgu çalışır. Materialized view: sorgu sonucu fiziksel olarak saklanır; sorgulama çok hızlıdır. REFRESH MATERIALIZED VIEW ile güncellenir; veri stale olabilir. Karmaşık aggregation sorgularını önbelleklemek için idealdir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Materialized view sadece belirli kullanıcıların görebileceği kısıtlı view oluştururken, normal view herkese açıktır' FROM q UNION ALL SELECT id,1,'Normal view şifreli, materialized view ise şifresiz veri saklar' FROM q UNION ALL SELECT id,2,'İkisi de aynı şekilde çalışır; fark yalnızca isimlendirme konvansiyonudur' FROM q UNION ALL SELECT id,3,'Normal view sorguyu çalıştırır, veri saklamaz; materialized view sorgu sonucunu fiziksel depolar, REFRESH ile güncellenir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','senior','OLTP ve OLAP arasındaki temel mimari fark nedir?','OLTP (Online Transaction Processing): çok sayıda kısa, eş zamanlı işlem (INSERT/UPDATE/DELETE); normalize şema; row storage; hızlı yanıt süresi. OLAP (Online Analytical Processing): az sayıda ağır analitik sorgu; denormalize/star schema; columnar storage; yüksek veri hacmi. Modern mimaride bunlar genellikle ayrı sistemlerde yönetilir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'OLTP çok sayıda kısa eş zamanlı işlem için normalize/row tabanlı; OLAP ağır analitik sorgu için denormalize/columnar tabanlıdır' FROM q UNION ALL SELECT id,1,'OLTP yalnızca finans, OLAP yalnızca e-ticaret uygulamaları için kullanılır' FROM q UNION ALL SELECT id,2,'OLAP ve OLTP aynı şeydir; fark yalnızca veri hacmine göre kullanılan terminoloji farkıdır' FROM q UNION ALL SELECT id,3,'OLAP SQL destekler, OLTP ise yalnızca NoSQL ile çalışabilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','senior','Bloom filter veritabanlarında nasıl kullanılır?','Bloom filter: bir elemanın set içinde kesinlikle olmadığını (false negative yok) veya muhtemelen olduğunu (false positive mümkün) söyleyen hafıza-verimli probabilistic veri yapısı. Cassandra ve RocksDB''de SSTable okumadan önce disk I/O önlemek için kullanılır. PostgreSQL''de partition pruning ve join optimization için entegre edilmiştir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Bloom filter, sorgu planner''ın en uygun index''i seçmesine yardımcı olan istatistiksel bir yapıdır' FROM q UNION ALL SELECT id,1,'Bir elemanın kesinlikle olmadığını veya muhtemelen olduğunu söyleyen probabilistic yapı; gereksiz disk okumalarını önler' FROM q UNION ALL SELECT id,2,'Bloom filter, büyük tabloları eşit parçalara bölen ve sorgu paralelleştirmesini sağlayan bir teknik şerittir' FROM q UNION ALL SELECT id,3,'Bloom filter yalnızca in-memory veritabanlarında (Redis) kullanılabilir; disk tabanlı DB''lerde desteklenmez' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','mid','Covering index nedir ve ne zaman faydalıdır?','Covering index, sorgunun ihtiyaç duyduğu tüm sütunları içerir; sorgu yalnızca index üzerinden yanıtlanır, tabloya erişim (table lookup) gerekmez. PostgreSQL''de `INCLUDE` clause ile non-key sütun eklenir. Çok sorgulanan read-heavy pattern''lerde query latency''yi önemli ölçüde düşürür.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Covering index, tüm sütunları indeksleyen ve tablonun tam bir kopyasını oluşturan özel bir index türüdür' FROM q UNION ALL SELECT id,1,'Covering index, birden fazla tablodaki sütunları kapsayan ve JOIN olmadan sorgulamayı sağlayan cross-table index''tir' FROM q UNION ALL SELECT id,2,'Sorgunun ihtiyaç duyduğu tüm sütunları kapsar; tabloya erişim gerektirmez, read-heavy sorgularda latency düşürür' FROM q UNION ALL SELECT id,3,'Covering index yalnızca composite index''lerin başka bir adıdır; tek sütun index covering olamaz' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','mid','Deadlock nasıl oluşur ve veritabanı nasıl çözer?','Deadlock: Transaction A, kaynak 1''i kilitler ve kaynak 2''yi bekler; Transaction B, kaynak 2''yi kilitler ve kaynak 1''i bekler. Circular wait oluşur. DB deadlock detector periyodik olarak döngü tespit eder; bir transaction''ı kurban (victim) seçip rollback eder. Önlem: kilitleme sırası tutarlı tutulmalı, transaction kısa tutulmalıdır.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Deadlock, aynı transaction''ın iki kez çalıştırılmasıyla oluşur; veritabanı duplicate commit''i otomatik reddeder' FROM q UNION ALL SELECT id,1,'Deadlock yalnızca SERIALIZABLE isolation level''da oluşur; diğer level''larda veritabanı kilitlenmeyi engeller' FROM q UNION ALL SELECT id,2,'Deadlock, veritabanı disk dolduğunda oluşur; storage boşaltılarak çözülür' FROM q UNION ALL SELECT id,3,'İki transaction karşılıklı birbirinin kilidini beklediğinde oluşur (circular wait); DB kurban transaction''ı rollback eder' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','junior','SQL''de COUNT, SUM ve AVG aggregate fonksiyonları nasıl kullanılır?','COUNT(*): NULL dahil tüm satırları sayar. COUNT(col): NULL değerleri atlar. SUM(col): sayısal sütun toplamı. AVG(col): ortalama (NULL atlanır). DISTINCT ile birlikte kullanılabilir: COUNT(DISTINCT col). GROUP BY olmadan tüm tablo için, GROUP BY ile grup bazında hesaplama yapılır.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'COUNT(*) tüm satırları sayar (NULL dahil); COUNT(col) NULL atlar; SUM ve AVG sayısal değerler için hesaplama yapar, NULL değerler görmezden gelinir' FROM q UNION ALL SELECT id,1,'COUNT yalnızca string, SUM yalnızca integer, AVG yalnızca float sütunlar için kullanılabilir' FROM q UNION ALL SELECT id,2,'AVG, NULL değerleri sıfır olarak işler ve toplam satır sayısına böler' FROM q UNION ALL SELECT id,3,'COUNT(*) ve COUNT(col) her zaman aynı sonucu döndürür; DISTINCT ile kullanım syntax hatası verir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('database','tr','junior','SQL''de DISTINCT anahtar kelimesi ne yapar?','DISTINCT, SELECT sonucundaki tekrar eden satırları (belirtilen sütunlardaki aynı değer kombinasyonu) tek satıra indirger. Birden fazla sütunla kullanıldığında tüm sütun kombinasyonu benzersiz olmalıdır. Full scan gerektirebileceğinden büyük tablolarda GROUP BY alternatifi daha performanslı olabilir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'DISTINCT, NULL değerleri filtreleyen ve yalnızca dolu satırları döndüren bir filtre operatörüdür' FROM q UNION ALL SELECT id,1,'SELECT sonucundaki tekrar eden satırları kaldırır; birden fazla sütunda tüm kombinasyon benzersiz olmalıdır' FROM q UNION ALL SELECT id,2,'DISTINCT yalnızca tek sütun için kullanılabilir; birden fazla sütunla syntax hatası verir' FROM q UNION ALL SELECT id,3,'DISTINCT, sütundaki değerleri büyükten küçüğe sıralayan ve tekrarları gösteren bir raporlama özelliğidir' FROM q;

-- ══════════════════════════════════════════
-- ALGORITHMS (+40 soru)
-- ══════════════════════════════════════════

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','junior','Big O notasyonunda O(1) ve O(n) arasındaki fark nedir?','O(1): sabit zamanlı; girdi boyutundan bağımsız her zaman aynı adım sayısında tamamlanır (array index erişimi, hash table lookup). O(n): doğrusal zamanlı; girdi n büyüdükçe adım sayısı orantılı artar (array''i baştan sona taramak). Algoritma seçiminde bu fark kritik öneme sahiptir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'O(1) girdi boyutundan bağımsız sabit süre; O(n) girdi büyüdükçe doğrusal süre artar' FROM q UNION ALL SELECT id,1,'O(1) en yavaş, O(n) en hızlı algoritma karmaşıklığıdır' FROM q UNION ALL SELECT id,2,'O(1) yalnızca sıralı diziler için, O(n) ise yalnızca bağlı listeler için geçerlidir' FROM q UNION ALL SELECT id,3,'O(1) ile O(n) arasında pratik bir fark yoktur; yalnızca akademik bir ayrımdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','junior','Binary search algoritmasının çalışabilmesi için ön koşul nedir?','Binary search, her adımda arama alanını yarıya böler; O(log n) zaman karmaşıklığı. Bunun çalışabilmesi için dizi sıralı (sorted) olmalıdır; aksi halde ortadaki elemanı bulma ve hangi yarıya gidileceğine karar verme mantığı çalışmaz.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Dizinin yalnızca pozitif sayılardan oluşması zorunludur' FROM q UNION ALL SELECT id,1,'Dizi sıralı olmalıdır; sırasız dizide hangi yarıda aranacağı belirlenemez' FROM q UNION ALL SELECT id,2,'Dizinin çift eleman sayısına sahip olması zorunludur' FROM q UNION ALL SELECT id,3,'Dizi yalnızca unique elemanlar içermelidir; tekrar eden elemanlarda hatalı sonuç döner' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','junior','Stack (yığın) veri yapısı ve LIFO prensibi ne anlama gelir?','Stack, Last In First Out (LIFO) prensibine göre çalışır: en son eklenen eleman ilk çıkar. Temel operasyonlar: push (ekleme), pop (çıkarma), peek (üstü görme). Kullanım alanları: fonksiyon çağrı yığını, geri al (undo) işlevi, parantez eşleştirme, DFS iteratif implementasyon.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Stack, ilk eklenen elemanın ilk çıktığı (FIFO) veri yapısıdır; queue ile aynı davranışı gösterir' FROM q UNION ALL SELECT id,1,'Stack, elemanların her iki uçtan eklenebildiği ve çıkarılabildiği çift uçlu veri yapısıdır' FROM q UNION ALL SELECT id,2,'Stack, son eklenen elemanın ilk çıktığı (LIFO) veri yapısıdır; fonksiyon çağrı yığını ve DFS''de kullanılır' FROM q UNION ALL SELECT id,3,'Stack, elemanların öncelik sırasına göre çıkarıldığı priority queue ile eşdeğerdir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','junior','Linked list ile array arasındaki temel tradeoff nedir?','Array: O(1) index erişimi, bellekte bitişik; dinamik boyut için yeniden boyutlandırma (O(n) kopyalama) gerekir. Linked list: O(n) index erişimi (pointer takibi), bellek bitişik değil; başa/ortaya ekleme O(1) (node biliniyorsa), tail ekleme O(1) (tail pointer varsa). Kullanım senaryosuna göre seçilmelidir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Linked list her zaman array''den daha hızlıdır; array yalnızca basit programlar için uygundur' FROM q UNION ALL SELECT id,1,'Array yalnızca sabit boyutlu veri için, linked list ise her tür veri için kullanılabilir' FROM q UNION ALL SELECT id,2,'Linked list ve array aynı Big O değerlerine sahiptir; fark yalnızca bellek kullanımındadır' FROM q UNION ALL SELECT id,3,'Array O(1) index erişimi sağlar (bitişik bellek); linked list O(n) erişim, ancak başa ekleme O(1)' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','junior','Rekürsiyon (özyineleme) algoritmalarında base case neden zorunludur?','Base case, rekürsiyon için durma koşuludur. Base case olmadan fonksiyon sonsuza kadar kendini çağırır ve stack overflow''a neden olur. Her rekürsif çağrı call stack''e frame ekler; stack boyutu sınırlı olduğundan sonsuz rekürsiyonda bellek taşar.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Durma koşuludur; olmadan sonsuz rekürsif çağrı oluşur ve call stack taşar (stack overflow)' FROM q UNION ALL SELECT id,1,'Base case yalnızca performans optimizasyonu içindir; olmadan da algoritma doğru sonuç üretir' FROM q UNION ALL SELECT id,2,'Base case yalnızca binary tree rekürsiyonlarında zorunludur; diğer rekürsif algoritmalarda isteğe bağlıdır' FROM q UNION ALL SELECT id,3,'Base case, rekürsif fonksiyonun iteratif versiyona dönüştürülmesini sağlayan özel bir return ifadesidir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','junior','Hash table''da lookup işleminin ortalama zaman karmaşıklığı neden O(1)''dir?','Hash function, anahtarı sabit zamanda (O(1)) bir index''e dönüştürür. Bu index''teki bucket''a doğrudan erişim O(1)''dir. Collision olmadığında veya iyi dağılımlı hash ile collision azdır; zincirleme ortalama çok kısadır. En kötü durumda (tüm anahtarlar aynı bucket) O(n)''e düşebilir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Hash table binary search kullandığı için O(log n) değil O(1) karmaşıklık sağlar' FROM q UNION ALL SELECT id,1,'Hash function anahtarı O(1)''de index''e dönüştürür; doğrudan bucket erişimi O(1); iyi dağılımda ortalama O(1) korunur' FROM q UNION ALL SELECT id,2,'Hash table tüm anahtarları önceden sıraladığı için arama O(1) olur' FROM q UNION ALL SELECT id,3,'O(1) yalnızca tam sayı anahtarlar için geçerlidir; string anahtarlarda hash table O(n) karmaşıklığına düşer' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','junior','Bubble sort algoritmasının zaman karmaşıklığı nedir?','Bubble sort: komşu elemanları karşılaştırıp gerekirse yer değiştirir; her pass en büyük elemanı sona taşır. En kötü ve ortalama durum: O(n²). En iyi durum (dizi sıralı, optimize edilmiş): O(n). Küçük diziler dışında production''da kullanılmaz; daha iyi alternatifler mevcuttur.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Bubble sort her durumda O(n log n) karmaşıklığına sahiptir' FROM q UNION ALL SELECT id,1,'Bubble sort en kötü durumda O(n) karmaşıklığı ile en hızlı sıralama algoritmasıdır' FROM q UNION ALL SELECT id,2,'Bubble sort en kötü ve ortalama durumda O(n²); optimize edilmiş versiyonu sıralı dizide O(n) sağlar' FROM q UNION ALL SELECT id,3,'Bubble sort O(n!) karmaşıklığında çalışır ve yalnızca eğitim amaçlı kullanılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','junior','Binary tree nedir ve ikili arama ağacından (BST) farkı nedir?','Binary tree: her node''un en fazla 2 child''ı (sol ve sağ) olan hiyerarşik veri yapısı. BST (Binary Search Tree): binary tree + sıralama özelliği: sol alt ağaçtaki tüm değerler node''dan küçük, sağ alt ağaçtakiler büyük. BST''de search, insert, delete ortalama O(log n); dengesiz ağaçta O(n)''e düşer.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Binary tree ve BST aynı şeydir; fark yalnızca isimlendirmedir' FROM q UNION ALL SELECT id,1,'BST''de her node yalnızca bir child''a sahip olabilir; binary tree ise en fazla 2 child içerebilir' FROM q UNION ALL SELECT id,2,'Binary tree yalnızca tam sayıları, BST ise her veri tipini saklayabilir' FROM q UNION ALL SELECT id,3,'Binary tree en fazla 2 child''lı ağaç; BST ek olarak sol < root < sağ sıralama özelliğini korur, aramayı O(log n)''e indirir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','junior','BFS (Breadth-First Search) ve DFS (Depth-First Search) hangi durumlarda tercih edilir?','BFS: katman katman arama; en kısa yolu (ağırlıksız graf) garanti eder; Queue kullanır. DFS: derine gider; Stack (veya özyineleme) kullanır; tüm yolları keşfetme ve topological sort için uygun. En kısa yol → BFS; bellek kısıtlıysa ve derin ağaç → DFS.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'BFS ağırlıksız grafta en kısa yolu garanti eder (Queue); DFS tüm yolları keşfetmek ve bellek tasarrufu için uygundur (Stack)' FROM q UNION ALL SELECT id,1,'BFS yalnızca ağaçlarda, DFS ise yalnızca graflarda kullanılabilir' FROM q UNION ALL SELECT id,2,'DFS her zaman BFS''den daha hızlıdır; BFS yalnızca görsel gezinme için tercih edilir' FROM q UNION ALL SELECT id,3,'BFS ve DFS aynı sonucu üretir; fark yalnızca hangi veri yapısının kullanıldığıdır (Stack vs Queue)' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','junior','Selection sort ile insertion sort arasındaki pratik fark nedir?','Selection sort: her pass minimum elemanı bulup doğru konuma taşır; her zaman O(n²) karşılaştırma yapar, swap sayısı O(n). Insertion sort: her elemanı sıralı kısma doğru konuma ekler; neredeyse sıralı dizilerde O(n) iç döngü; gerçek dünya verisinde genellikle selection sort''tan hızlıdır.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Selection sort her zaman insertion sort''tan hızlıdır çünkü minimum elementi bulup tek swap yapar' FROM q UNION ALL SELECT id,1,'Insertion sort neredeyse sıralı dizilerde O(n)''e yaklaşır; selection sort her durumda O(n²) karşılaştırma yapar' FROM q UNION ALL SELECT id,2,'İkisi de aynı Big O değerine ve pratikte aynı performansa sahiptir' FROM q UNION ALL SELECT id,3,'Selection sort yalnızca küçük dizilerde, insertion sort ise yalnızca büyük dizilerde kullanılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','junior','Memoization nedir ve ne zaman kullanılır?','Memoization: rekürsif fonksiyonun hesapladığı sonuçları bir cache''de saklar; aynı argümanla tekrar çağrılınca cache''den döner. Fibonacci rekürsiyonunu O(2^n)''den O(n)''e indirir. Top-down dynamic programming yaklaşımıdır. Aynı alt problemlerin tekrar hesaplandığı overlapping subproblem yapısında etkilidir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Memoization, büyük dizileri küçük parçalara bölerek paralel işleyen bir optimizasyon tekniğidir' FROM q UNION ALL SELECT id,1,'Memoization yalnızca sıralama algoritmalarında kullanılır; tree/graph algoritmalarında etkisizdir' FROM q UNION ALL SELECT id,2,'Hesaplanan sonuçları cache''de saklar; aynı argümanla tekrar çağrılınca cache''den döner; overlapping subproblem''lerde etkilidir' FROM q UNION ALL SELECT id,3,'Memoization, fonksiyonun kaynak kodunu derleyicinin optimize edebileceği biçime dönüştüren bir tekniktir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','junior','Stack overflow neden oluşur?','Her fonksiyon çağrısı call stack''e yeni frame ekler; frame yerel değişkenler ve return address içerir. Rekürsif fonksiyonun base case''i yoksa veya çok derin rekürsiyonda stack boyutu aşılır ve stack overflow hatası oluşur. Iteratif yaklaşım veya tail call optimization ile önlenebilir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Stack overflow, sıralama algoritmasının ters sıralı dizide çalışmasından kaynaklanan sonsuz döngüdür' FROM q UNION ALL SELECT id,1,'Stack overflow, hash table''ın maksimum load factor''ünü aşması durumunda oluşan bellek hatasıdır' FROM q UNION ALL SELECT id,2,'Stack overflow, linked list''in sonuna NULL yerine kendine pointer eklemesiyle oluşan döngüsel yapıdır' FROM q UNION ALL SELECT id,3,'Her rekürsif çağrı call stack''e frame ekler; base case olmayan veya çok derin rekürsiyonda stack boyutu aşılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','mid','Merge sort''un quick sort''a karşı avantajı nedir?','Merge sort: her durumda O(n log n) garanti eder (worst case dahil); kararlı (stable) sıralama; linked list için idealdir; ek O(n) bellek gerektirir. Quick sort: ortalama O(n log n) ancak worst case O(n²) (kötü pivot seçimi); in-place (ek bellek az); cache-friendly; pratikte genellikle merge sort''tan hızlıdır.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Merge sort worst case dahil O(n log n) garantiler ve stabil sıralamadır; quick sort ortalama daha hızlı ama worst case O(n²)' FROM q UNION ALL SELECT id,1,'Merge sort her zaman quick sort''tan daha hızlıdır; production''da her zaman merge sort tercih edilmelidir' FROM q UNION ALL SELECT id,2,'Merge sort O(1) ek bellek kullanır; quick sort O(n) ek bellek gerektirir' FROM q UNION ALL SELECT id,3,'İkisi de aynı Big O değerlerine sahiptir; fark yalnızca implementasyon tercihidir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','mid','Quick sort''un en kötü durumu (worst case) ne zaman oluşur?','Quick sort worst case O(n²): pivot her seferinde en küçük veya en büyük eleman seçildiğinde (örn. sıralı dizi + always first element pivot). Partition her seferinde 1 ve n-1 elemanlı iki parçaya bölünür; n kez bölme × n karşılaştırma. Çözüm: random pivot, median-of-three, veya introsort (quick sort + heap sort hybrid).',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Quick sort worst case, dizinin tamamen rastgele sıralanmış olduğu durumda oluşur' FROM q UNION ALL SELECT id,1,'Pivot her seferinde en küçük/büyük eleman seçildiğinde (sıralı dizi + first element pivot); her bölme 1 ve n-1''e düşer, O(n²)' FROM q UNION ALL SELECT id,2,'Quick sort worst case yalnızca tüm elemanların aynı değere sahip olduğu dizilerde oluşur' FROM q UNION ALL SELECT id,3,'Quick sort her zaman O(n log n) karmaşıklığına sahiptir; worst case senaryosu yoktur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','mid','Hash collision nasıl çözülür: chaining ve open addressing farkı?','Chaining: her bucket bir linked list; collision olan elemanlar aynı bucket''taki listeye eklenir. Basit implementasyon; yüksek load factor''de performans düşer (liste uzar). Open addressing (linear/quadratic probing, double hashing): başka boş bucket aranır; cache-friendly ama silme karmaşıktır, yüksek load factor''de kümeleme sorunları çıkar.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Chaining tüm collisionları siler; open addressing ise çakışan elemanı rastgele başka bir hash table''a taşır' FROM q UNION ALL SELECT id,1,'Chaining yalnızca string anahtarlar için, open addressing ise yalnızca integer anahtarlar için geçerlidir' FROM q UNION ALL SELECT id,2,'Chaining aynı bucket''ta linked list kullanır (basit, load factor toleranslı); open addressing boş bucket arar (cache-friendly, silme karmaşık)' FROM q UNION ALL SELECT id,3,'İkisi de aynı performansı sağlar; seçim yalnızca programcının tercihine bağlıdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','mid','Dengesiz BST''nin search performansı neden kötüleşir?','BST''de search ortalama O(log n) (dengeli ağaç). Ama her eleman öncekinden büyük sırayla eklenirse ağaç sağa yatık zincire döner; aslında linked list gibi davranır ve search O(n) olur. Bu nedenle self-balancing tree''ler (AVL, Red-Black tree) denge korur ve worst case O(log n) garantiler.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Dengesiz BST yalnızca string değerlerde kötü performans gösterir; sayısal değerlerde her zaman O(log n) korunur' FROM q UNION ALL SELECT id,1,'BST''de dengesizlik yalnızca DELETE işlemlerinden sonra oluşur; INSERT dengeli yapıyı bozamaz' FROM q UNION ALL SELECT id,2,'Dengesiz BST''de yalnızca INSERT yavaşlar; search ve delete her zaman O(log n) kalır' FROM q UNION ALL SELECT id,3,'Sıralı ekleme ağacı zincire dönüştürür (linked list gibi); search O(n)''e düşer; AVL/Red-Black tree O(log n) garantiler' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','mid','Heap (Priority Queue) ne zaman kullanılır?','Heap, en büyük veya en küçük elemanı her zaman O(log n)''de insert/delete, O(1)''de peek eden veri yapısıdır. Kullanım: Dijkstra algoritması, Prim MST, k largest/smallest element, job scheduling, median maintenance (2 heap). Array üzerinde verimli implementasyonu için complete binary tree özelliği kullanılır.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'En küçük/büyük elemana O(1)''de erişim ve O(log n)''de insert/delete; Dijkstra, k-element problemleri ve scheduling''de kullanılır' FROM q UNION ALL SELECT id,1,'Heap yalnızca Dijkstra algoritmasında kullanılır; diğer algoritmalarda linked list tercih edilir' FROM q UNION ALL SELECT id,2,'Heap, sıralı veri saklamak için BST yerine her zaman tercih edilmelidir' FROM q UNION ALL SELECT id,3,'Heap, yalnızca tam sayı dizilerinde çalışan özel bir sıralama algoritmasıdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','mid','Sliding window tekniği hangi problem tiplerinde kullanılır?','Sliding window: sabit veya değişken boyutlu bir pencereyi dizide kaydırarak alt dizi/substring problemlerini O(n)''de çözer. Kullanım: maksimum/minimum alt dizi toplamı, belirli koşulu sağlayan en uzun/kısa substring, k büyüklüğündeki pencerede maksimum. Brute force O(n²) yerine O(n) sağlar.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Sliding window yalnızca sıralı dizilerde çalışır; sırasız dizilerde two pointers kullanılmalıdır' FROM q UNION ALL SELECT id,1,'Pencereyi kaydırarak alt dizi/substring problemlerini O(n)''de çözer; brute force O(n²) yerine geçer' FROM q UNION ALL SELECT id,2,'Sliding window yalnızca sabit boyutlu pencereler için kullanılabilir; değişken boyutlu problem tiplerinde çalışmaz' FROM q UNION ALL SELECT id,3,'Sliding window, circular dizileri doğrusal diziye dönüştüren bir teknik olup yalnızca queue veri yapısıyla çalışır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','mid','Two pointers tekniği hangi problem tiplerinde kullanılır?','Two pointers: iki pointer farklı hızda veya farklı uçlardan ilerler. Kullanım: sıralı dizide çift toplam (baştan/sondan), palindrome kontrolü, three sum, cycle detection (Floyd), partition (quick sort). Brute force O(n²) yerine O(n) çözüm sağlar. Sıralı dizi gerektiren problemlerde güçlüdür.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Two pointers yalnızca linked list''lerde kullanılır; array''lerde sliding window tercih edilir' FROM q UNION ALL SELECT id,1,'Two pointers yalnızca binary search için kullanılır; diğer problemlerde verimsizdir' FROM q UNION ALL SELECT id,2,'İki pointer farklı hız/yönde ilerleyerek O(n)''de çözüm sağlar; sıralı dizide çift toplam, palindrome, cycle detection için kullanılır' FROM q UNION ALL SELECT id,3,'Two pointers tekniği yalnızca çift sayı içeren dizilerde çalışır; tek sayılı dizilerde sonuç hatalıdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','mid','Binary tree traversal yöntemleri (inorder, preorder, postorder) nasıl farklılık gösterir?','Inorder (Sol-Root-Sağ): BST''de sıralı çıktı verir. Preorder (Root-Sol-Sağ): tree kopyalama, prefix expression. Postorder (Sol-Sağ-Root): tree silme, postfix expression, alt ağaç hesaplamaları. Level-order (BFS): katman katman; shortest path ağaç problemleri için.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'İnorder her zaman ağacı en hızlı geçen traversal; diğer ikisi yalnızca özel durumlar için kullanılır' FROM q UNION ALL SELECT id,1,'Üç traversal da aynı sırada eleman ziyaret eder; fark yalnızca işlem zamanlamasındadır' FROM q UNION ALL SELECT id,2,'Preorder yalnızca min-heap, postorder ise yalnızca max-heap için kullanılabilir' FROM q UNION ALL SELECT id,3,'Inorder: Sol-Root-Sağ (BST''de sıralı çıktı); Preorder: Root-Sol-Sağ (kopyalama); Postorder: Sol-Sağ-Root (silme, hesaplama)' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','mid','Graf temsili: adjacency list ile adjacency matrix karşılaştırması?','Adjacency matrix: V×V matris; edge varlığı O(1) kontrol; yoğun graflar için uygun; O(V²) bellek. Adjacency list: her vertex''in komşu listesi; seyrek graflar için verimli; O(V+E) bellek; edge kontrolü O(degree). Gerçek dünya grafları genellikle seyrek; adjacency list tercih edilir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Matrix O(1) edge kontrolü, O(V²) bellek (yoğun graf); list O(V+E) bellek (seyrek graf için verimli), edge kontrolü O(degree)' FROM q UNION ALL SELECT id,1,'Adjacency matrix her zaman adjacency list''ten daha hızlıdır; gerçek projelerde matrix tercih edilir' FROM q UNION ALL SELECT id,2,'İki temsil de aynı belleği kullanır; fark yalnızca kod yazım kolaylığıdır' FROM q UNION ALL SELECT id,3,'Adjacency list yalnızca yönlü (directed) graflar için, matrix ise yalnızca yönsüz graflar için kullanılabilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','mid','Topological sort ne zaman kullanılır?','Topological sort, DAG (Directed Acyclic Graph) üzerinde bağımlılık sırasını belirler: eğer A → B edge''i varsa A, B''den önce gelir. Kullanım: build system bağımlılıkları (Makefile), ders önkoşulları, task scheduling. DFS tabanlı (Kahn''ın algoritması BFS tabanlı). Döngü içeren grafta uygulanamaz.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Topological sort yalnızca ikili ağaçlarda kullanılır; genel graflarda uygulanamaz' FROM q UNION ALL SELECT id,1,'DAG''daki bağımlılık sırasını belirler; build bağımlılıkları ve task scheduling''de kullanılır; döngülü grafta uygulanamaz' FROM q UNION ALL SELECT id,2,'Topological sort, grafın tüm vertex''lerini sıralar ve otomatik olarak döngü kırar' FROM q UNION ALL SELECT id,3,'Topological sort yalnızca minimum spanning tree hesaplaması için kullanılan bir alt algoritmadır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','mid','Floyd''s cycle detection (kaplumbağa ve tavşan) algoritması nasıl çalışır?','İki pointer: yavaş (1 adım) ve hızlı (2 adım). Döngü varsa: hızlı pointer eninde sonunda yavaşa yetişir (buluşurlar). Döngü yoksa: hızlı pointer NULL''a ulaşır. O(1) ek bellek; linked list döngü tespiti ve list ortasını bulma için kullanılır.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Tüm node''ları bir hash set''e ekler; tekrar eden node bulunursa döngü tespit edilir; O(n) bellek gerektirir' FROM q UNION ALL SELECT id,1,'Her node için önceki node''a pointer eklenir; önceki node zaten işaretliyse döngü var demektir' FROM q UNION ALL SELECT id,2,'Yavaş (1 adım) ve hızlı (2 adım) pointer kullanır; buluşurlarsa döngü vardır; O(1) ek bellek gerektirir' FROM q UNION ALL SELECT id,3,'Her node tek tek ziyaret edilir ve ziyaret sayacı tutulur; sayaç n''yi geçerse döngü tespit edilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','mid','Trie veri yapısı hangi problem tiplerinde avantajlıdır?','Trie (prefix tree): string''leri karakter karakter saklar. Avantajlar: prefix arama O(m) (m = kelime uzunluğu, n bağımsız); autocomplete, spell check, IP routing (radix tree), dictionary implementasyonu. Hash table''da prefix aramak O(n×m); Trie''da O(m). Ek bellek gerektirir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Trie yalnızca tam eşleşme aramasında kullanılır; prefix aramasında BST tercih edilir' FROM q UNION ALL SELECT id,1,'Trie yalnızca sayısal verileri sıralı saklayabilen bir binary tree türevidir' FROM q UNION ALL SELECT id,2,'Trie hash table ile aynı performansı sağlar; yalnızca bellek tasarrufu için tercih edilir' FROM q UNION ALL SELECT id,3,'Prefix aramasında O(m) ile üstündür; autocomplete, spell check ve IP routing için idealdir; hash table prefix aramada O(n×m)' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','senior','Dijkstra algoritmasının zaman karmaşıklığı ve kısıtı nedir?','Dijkstra, ağırlıklı grafta tek kaynaktan en kısa yol bulur. Binary heap ile O((V+E) log V); Fibonacci heap ile O(E + V log V). Kısıt: negatif ağırlıklı edge''ler ile çalışmaz (negatif cycle varsa Bellman-Ford veya Johnson''s algoritması kullanılır). Greedy yaklaşım her adımda en yakın vertex seçer.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Binary heap ile O((V+E) log V); negatif edge''lerle çalışmaz; greedy en yakın vertex seçer' FROM q UNION ALL SELECT id,1,'Dijkstra tüm kaynaklardan tüm hedeflere en kısa yolu O(V²)''de bulur' FROM q UNION ALL SELECT id,2,'Dijkstra yalnızca ağırlıksız graflarda çalışır; ağırlıklı graflar için BFS kullanılmalıdır' FROM q UNION ALL SELECT id,3,'Dijkstra her durumda O(V + E) karmaşıklığıyla çalışır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','senior','Dynamic programming''de memoization (top-down) ile tabulation (bottom-up) arasındaki fark?','Memoization (top-down): rekürsif, sadece gereken alt problemleri hesaplar, call stack overhead. Tabulation (bottom-up): iteratif, tüm alt problemleri tablo olarak doldurur, stack overflow riski yok, genellikle daha hızlı (cache-friendly). İkisi de overlapping subproblems ve optimal substructure gerektirir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Memoization her zaman tabulation''dan daha hızlıdır; tabulation sadece basit DP problemleri için kullanılır' FROM q UNION ALL SELECT id,1,'Memoization rekürsif sadece gerekenleri hesaplar; tabulation iteratif tüm alt problemleri tablo olarak doldurur, genellikle daha hızlı' FROM q UNION ALL SELECT id,2,'İkisi arasında performans farkı yoktur; fark yalnızca kişisel kod yazım tercihidir' FROM q UNION ALL SELECT id,3,'Tabulation yalnızca doğrusal DP problemleri için kullanılabilir; 2D DP tablolarında memoization zorunludur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','senior','0-1 Knapsack problemi hangi algoritmik teknikle çözülür?','0-1 Knapsack: her item ya alınır (1) ya alınmaz (0). DP tablosu: dp[i][w] = i. eleman dahil, w kapasite ile max değer. Recurrence: dp[i][w] = max(dp[i-1][w], val[i] + dp[i-1][w-wt[i]]). O(n×W) zaman ve alan. Fractional knapsack (greedy) ile karıştırılmamalıdır.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Greedy algoritma ile her adımda ağırlık/değer oranı en yüksek item seçilerek O(n log n)''de çözülür' FROM q UNION ALL SELECT id,1,'BFS ile tüm kombinasyonlar keşfedilerek optimal çözüm garanti edilir; O(2^n) kaçınılmazdır' FROM q UNION ALL SELECT id,2,'Dynamic programming: dp[i][w] = max(al, alma) ile O(n×W) tablosu doldurulur; greedy burada optimal değil' FROM q UNION ALL SELECT id,3,'Binary search ile kapasiteyi ikiye bölerek her adımda en değerli item belirlenir; O(n log W)''de çözülür' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','senior','Union-Find (Disjoint Set Union) hangi problemlerde kullanılır?','Union-Find: birleşik bileşenler (connected components), Kruskal MST, cycle detection, dynamic connectivity. Find: bir elemanın kümesini bulur (path compression ile O(α(n)) amortize). Union: iki kümeyi birleştirir (union by rank/size). α (inverse Ackermann) pratikte sabit kabul edilir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Union-Find yalnızca sıralama problemleri için kullanılır; graf algoritmalarında DSU yerine BFS tercih edilir' FROM q UNION ALL SELECT id,1,'Union-Find yalnızca tam ağaç (complete tree) yapısında çalışır; genel graflarda uygulanamaz' FROM q UNION ALL SELECT id,2,'Union-Find, büyük kümeleri alfabetik sırada birleştiren string manipülasyon algoritmasıdır' FROM q UNION ALL SELECT id,3,'Connected components, Kruskal MST, cycle detection için kullanılır; path compression ile O(α(n)) amortize süre' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','senior','Segment tree ne zaman B-tree veya interval tree yerine tercih edilir?','Segment tree: bir dizi üzerinde range query (aralık toplam, min, max) ve point/range update''i O(log n)''de destekler. Lazy propagation ile range update de O(log n). Competitive programming ve static dizi range query''lerinde yaygın. Interval tree: örtüşen aralık aramasında (stabbing query) güçlüdür. Fenwick tree daha basit ama daha az esnektir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Dizi üzerinde range query ve range update işlemlerini O(log n)''de destekler; lazy propagation ile range update mümkün' FROM q UNION ALL SELECT id,1,'Segment tree yalnızca static dizilerde çalışır; update desteği yoktur' FROM q UNION ALL SELECT id,2,'Segment tree, B-tree''nin memory-efficient bir versiyonu olup veritabanı index işlemleri için kullanılır' FROM q UNION ALL SELECT id,3,'Segment tree yalnızca sayısal veri tiplerini destekler; string verilerde kullanılamaz' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','senior','NP, NP-Complete ve NP-Hard arasındaki fark nedir?','P: polynomial zamanda çözülebilen problemler. NP: polynomial zamanda doğrulanabilen problemler. NP-Complete: NP''de ve tüm NP problemleri polynomial reduce edilebilir (en zor NP problemi). NP-Hard: NP-Complete ile en az aynı zor ama NP''de olmak zorunda değil. Sat, Traveling Salesman decision version NP-Complete; TSP optimization NP-Hard.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'NP problemi polynomial zamanda çözülemeyen; NP-Complete ise çözülemeyeceği kanıtlanmış problem kategorisidir' FROM q UNION ALL SELECT id,1,'NP polynomial doğrulanabilir; NP-Complete NP''de ve en zor NP problemi; NP-Hard en az NP-Complete kadar zor ama NP''de olmak zorunda değil' FROM q UNION ALL SELECT id,2,'NP-Hard ve NP-Complete aynı şeydir; fark yalnızca kullanılan referans kitaba göre değişen terminolojidir' FROM q UNION ALL SELECT id,3,'P = NP olduğu kanıtlanmıştır; NP-Complete kategorisi artık teorik önemi olmayan tarihsel bir kavramdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','senior','Amortized analysis neden "gerçek" worst case analizinden farklıdır?','Amortized analysis, bir işlem dizisinin toplam maliyetini işlem sayısına bölerek ortalama maliyeti hesaplar. Dynamic array''de push: genellikle O(1), ancak kapasite dolunca O(n) yeniden boyutlandırma gerekir. n işlemde toplam maliyet O(n); amortized O(1). Worst case her push için O(n) derdi yanlış yönlendirir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Amortized analysis yalnızca sıralama algoritmaları için kullanılır; veri yapılarında worst case analiz zorunludur' FROM q UNION ALL SELECT id,1,'Amortized analysis, algoritmanın ortalama girdideki performansını ölçer; worst case girdide yanıltıcı olur' FROM q UNION ALL SELECT id,2,'Operasyon dizisinin toplam maliyetini operasyon sayısına böler; bazı pahalı işlemlerin maliyeti önceki ucuz işlemlere yayılır' FROM q UNION ALL SELECT id,3,'Amortized analysis yalnızca randomized algoritmalar için geçerlidir; deterministik yapılarda kullanılamaz' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','senior','Red-Black tree hangi dengeleme garantisini sağlar?','Red-Black tree 5 kural ile denge korur (root siyah, red node''un child''ları siyah, her yolda aynı sayıda siyah node...). Bu, en uzun yolun en kısa yolun en fazla 2 katı olmasını garantiler; height O(log n). Search, insert, delete en kötü durumda O(log n). Java TreeMap, C++ std::map Red-Black tree kullanır.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Red-Black tree her node''un tam olarak 2 child''a sahip olmasını zorunlu kılar' FROM q UNION ALL SELECT id,1,'Red-Black tree ağaç yüksekliğini her zaman O(1) olarak korur' FROM q UNION ALL SELECT id,2,'Red-Black tree yalnızca tam sıralı (already sorted) veri için O(log n) performans sağlar' FROM q UNION ALL SELECT id,3,'5 renk kuralı ile en uzun yol en kısa yolun en fazla 2 katı olur; height O(log n), tüm operasyonlar worst case O(log n)' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','senior','A* algoritması Dijkstra''dan nasıl farklıdır?','A*: f(n) = g(n) + h(n). g(n) = başlangıçtan n''e gerçek maliyet, h(n) = heuristic (n''den hedefe tahmini maliyet). Kabul edilebilir heuristic (h(n) <= gerçek maliyet) ile optimal çözüm garantidir. Dijkstra h(n) = 0 özel halidir. İyi heuristic ile A* çok daha az node keşfeder; oyun AI ve navigasyon sistemlerinde yaygındır.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'A* f(n)=g(n)+h(n) heuristic kullanır; kabul edilebilir h(n) ile optimal, daha az node keşfeder; Dijkstra h=0 özel halidir' FROM q UNION ALL SELECT id,1,'A* yalnızca ızgara (grid) yapılarında çalışır; genel graflarda Dijkstra kullanılmak zorundadır' FROM q UNION ALL SELECT id,2,'A* negatif ağırlıklı edge''lerde Dijkstra''dan üstündür; diğer durumlarda ikisi aynı performansı gösterir' FROM q UNION ALL SELECT id,3,'A* her zaman Dijkstra''dan daha yavaştır; heuristic hesaplama ek maliyet getirir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','senior','Bloom filter''ın false positive ve false negative özellikleri nelerdir?','Bloom filter: k hash fonksiyonu ile bir eleman m bit array''de k bit set eder. Arama: k bit hepsi set ise "muhtemelen mevcut" (false positive mümkün); herhangi biri 0 ise "kesinlikle mevcut değil" (false negative yok). Kullanım: veritabanı önünde gereksiz disk okumayı engellemek, spam filtresi, tarayıcı URL blacklist.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Bloom filter hem false positive hem false negative üretebilir; kesin cevap için ek doğrulama her zaman zorunludur' FROM q UNION ALL SELECT id,1,'False positive mümkün (muhtemelen var ama yok); false negative imkânsız (kesinlikle yok ise yok); disk I/O azaltmada kullanılır' FROM q UNION ALL SELECT id,2,'Bloom filter yalnızca false negative üretir; false positive hiçbir zaman oluşmaz' FROM q UNION ALL SELECT id,3,'Bloom filter yalnızca tam sayılar için çalışır; string elemanlar için hash collision nedeniyle her zaman hatalı sonuç verir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','senior','Skip list nedir ve B-tree ile karşılaştırması nasıldır?','Skip list: birden fazla düzeyli bağlı listeler; üst düzey katmanlar "ekspres hat" görevi görür. Probabilistic denge; search/insert/delete ortalama O(log n). Avantaj: implementasyon basitliği, concurrent erişim kolay (lock-free varyantları var). B-tree disk I/O optimize eder; skip list bellek içi. Redis sorted set skip list kullanır.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Skip list yalnızca immutable veri için uygundur; insert/delete desteklemez' FROM q UNION ALL SELECT id,1,'Skip list ve B-tree aynı amaca hizmet eder; fark yalnızca bellekte (skip list) ve diskte (B-tree) çalışmalarıdır' FROM q UNION ALL SELECT id,2,'Birden fazla katmanlı linked list; probabilistic O(log n); basit implementasyon ve concurrent erişim avantajı; Redis sorted set''te kullanılır' FROM q UNION ALL SELECT id,3,'Skip list yalnızca sıralı tam sayı dizilerinde çalışır; string ve nesne tipleri için uygun değildir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','senior','B-tree neden veritabanı indexlerinde binary search tree yerine kullanılır?','B-tree: her node birden fazla key ve child içerir; disk page boyutuna (4KB-16KB) uygun. Disk I/O''yu minimize eder: her I/O''da daha fazla key okunur, ağaç yüksekliği düşer. Binary tree''nin her node tek key içermesi binlerce disk read gerektirebilir. B+ tree''de tüm data leaf''lerde; internal node yalnızca routing key tutar.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'B-tree binary tree''den bellek kullanımı açısından daha verimlidir; disk I/O ile ilgisi yoktur' FROM q UNION ALL SELECT id,1,'B-tree yalnızca tam sayı key''ler için optimize edilmiştir; string key''ler için BST daha iyidir' FROM q UNION ALL SELECT id,2,'B-tree her node''da yalnızca bir key saklar; BST''den farkı dengeleme algoritmasıdır' FROM q UNION ALL SELECT id,3,'Disk page boyutuna uygun çok-key node ile disk I/O minimizeeder; ağaç yüksekliği BST''ye göre çok düşük' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','mid','Counting sort neden comparison sort''lardan (merge sort, quick sort) daha hızlı olabilir?','Counting sort: her elemanın kaç kez geçtiğini sayar, prefix sum ile orijinal konumları belirler. O(n + k); k = değer aralığı. Karşılaştırma yapmadığı için O(n log n) lower bound''u aşar. Kısıt: yalnızca tam sayılar (veya diskret değerler) için, k >> n ise verimsiz. Radix sort counting sort''u kullanır.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Karşılaştırma yapmadan O(n+k)''de çalışır; O(n log n) lower bound aşılır; yalnızca tam sayı/diskret değerler için geçerli' FROM q UNION ALL SELECT id,1,'Counting sort her durumda O(n)''dir; k değerinden bağımsız olarak en hızlı sıralama algoritmasıdır' FROM q UNION ALL SELECT id,2,'Counting sort, GPU paralel işleme için optimize edilmiş ve CPU tabanlı algoritmalardan her zaman üstün olan bir tekniktir' FROM q UNION ALL SELECT id,3,'Counting sort sadece n <= 1000 boyutundaki dizilerde hızlıdır; daha büyük dizilerde merge sort tercih edilmelidir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','mid','Backtracking tekniği hangi problem tiplerinde kullanılır?','Backtracking: geçerli bir çözüm adayı oluşturulur; kısıt ihlal edilirse bir adım geri dönülür (prune) ve başka dal denenir. N-queens, sudoku, maze solving, combination sum, permutasyon. Brute force''tan verimli çünkü ölü dallar erken kesilir. O(k^n)''e kadar sürebilir; uygun pruning kritik.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Backtracking yalnızca sıralama problemleri için kullanılır; diğer kombinatorial problemlerde BFS tercih edilir' FROM q UNION ALL SELECT id,1,'Kısıt ihlali durumunda geri dönerek farklı dal dener; N-queens, sudoku, permutasyon problemleri için; ölü dal pruning ile verimli' FROM q UNION ALL SELECT id,2,'Backtracking yalnızca binary tree yapılarında çalışır; genel problemlerde uygulanamaz' FROM q UNION ALL SELECT id,3,'Backtracking, dynamic programming''in iteratif versiyonudur ve her zaman DP''den daha hızlı sonuç üretir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','junior','Zaman karmaşıklığı (time complexity) ile alan karmaşıklığı (space complexity) arasındaki fark nedir?','Zaman karmaşıklığı, algoritmanın çalışma süresinin girdi büyüklüğüyle nasıl ölçeklendiğini ifade eder. Alan (space) karmaşıklığı ise kullanılan ek belleğin ölçeklenmesini gösterir. Çoğu zaman zaman-alan tradeoff vardır: memoization zamanı azaltır ama daha fazla bellek kullanır.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Zaman karmaşıklığı milisaniye cinsinden ölçülür; alan karmaşıklığı megabyte cinsinden ifade edilir' FROM q UNION ALL SELECT id,1,'Alan karmaşıklığı her zaman zaman karmaşıklığına eşittir; ikisi aynı Big O değerini paylaşır' FROM q UNION ALL SELECT id,2,'Zaman: çalışma süresinin girdi ile ölçeklenmesi; alan: kullanılan ek belleğin ölçeklenmesi; genellikle zaman-alan tradeoff mevcuttur' FROM q UNION ALL SELECT id,3,'Zaman karmaşıklığı yalnızca iteratif, alan karmaşıklığı ise yalnızca rekürsif algoritmalar için hesaplanır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('algorithms','tr','junior','Linear search''ün best case senaryosu nedir?','Linear search sırasız dizide baştan sona arar. Best case: aranan eleman ilk pozisyonda; O(1) karşılaştırma yeterli. Average case: O(n/2) ≈ O(n). Worst case: eleman son pozisyonda veya hiç yok; O(n). Sıralı dizilerde binary search (O(log n)) tercih edilir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Linear search best case O(n log n)''dir; sıralı dizilerde binary search ile aynı performansı sağlar' FROM q UNION ALL SELECT id,1,'Linear search best case O(n/2)''dir; her zaman dizinin yarısına kadar aramak zorundadır' FROM q UNION ALL SELECT id,2,'Linear search best case O(log n)''dir; her adımda arama alanını yarıya böler' FROM q UNION ALL SELECT id,3,'Aranan eleman ilk pozisyonda ise O(1) karşılaştırma yeterli; best case O(1)''dir' FROM q;

