-- HR (+40 soru)
-- ══════════════════════════════════════════

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','junior','Mülakatta "kendini tanıt" sorusunu yanıtlamanın en etkili yolu nedir?','Etkili tanıtım: mevcut rol/deneyim → ilgili başarılar/beceriler → neden bu pozisyon/şirkete ilgi duyulduğu. 60-90 saniye idealdir. Özgeçmiş özeti değil, pozisyonla ilgili vurgulanmış bir anlatı olmalıdır. Kişisel yaşam ayrıntılarına girmeden profesyonel bir çerçevede tutulmalıdır.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Mevcut deneyim ve beceriler → ilgili başarılar → neden bu pozisyon sıralamasıyla 60-90 saniyelik odaklı anlatı yapılır' FROM q UNION ALL SELECT id,1,'Doğum tarihinden itibaren tüm eğitim ve iş geçmişi kronolojik olarak eksiksiz aktarılır' FROM q UNION ALL SELECT id,2,'Yalnızca kişisel hobiler ve ilgi alanları paylaşılır; iş deneyimi zaten özgeçmişte mevcut olduğu için tekrar edilmez' FROM q UNION ALL SELECT id,3,'Soruyu soru ile yanıtlamak tercih edilir: "Hangi konuyu öğrenmek istersiniz?" diyerek mülakatçıyı yönlendirilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','junior','Neden bu şirketi seçiyorsunuz sorusunu yanıtlarken nelere dikkat edilmelidir?','Etkili yanıt: şirketin misyonu/değerleri, ürünleri veya teknik yaklaşımı hakkında araştırma yapıldığının gösterilmesi; kendi kariyer hedefleri ile şirketin yönünün nasıl örtüştüğünün açıklanması. "Yüksek maaş" veya "iş güvencesi" gibi içsel motivasyonları öne çıkarmak yerine şirkete özgü ilgi vurgulanmalıdır.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Başvurduğum tek şirket siz olduğunuz için" diyerek dürüstlük gösterilir' FROM q UNION ALL SELECT id,1,'Şirketi araştırdığını gösteren spesifik referanslar (ürün, değer, teknik karar) ile kariyer hedeflerinin örtüşmesi anlatılır' FROM q UNION ALL SELECT id,2,'"Sektörün en büyük şirketi olduğunuz için" diyerek şirketi pohpohlayan bir yanıt verilir' FROM q UNION ALL SELECT id,3,'Yalnızca maaş beklentilerinin karşılanıp karşılanmayacağı netleştirilir; diğer faktörler önemsiz gösterilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','junior','Güçlü yönleriniz sorusunda nasıl bir yanıt vermek etkilidir?','Etkili güçlü yön yanıtı: pozisyonla doğrudan ilgili 2-3 güçlü yön + her biri için somut örnek (STAR benzeri). "Takım oyuncusuyum" gibi jenerik ifadeler yerine "karmaşık teknik problemleri sistematik debug ederek ekibime yön verdiğim iki örnek..." gibi spesifik kanıt sunulmalıdır.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Mümkün olduğunca çok güçlü yön sıralanır; uzun liste mülakatçıyı etkiler' FROM q UNION ALL SELECT id,1,'Yalnızca zayıf yönler anlatılır; bu alçakgönüllülük göstergesi olarak değerlendirilir' FROM q UNION ALL SELECT id,2,'Pozisyonla ilgili 2-3 güçlü yön ve her biri için somut örnek sunulur; jenerik ifadeler kanıtla desteklenir' FROM q UNION ALL SELECT id,3,'Güçlü yönler olarak yalnızca teknik beceriler sıralanır; soft skills mülakatçıyı ilgilendirmez' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','junior','Zayıf yönünüz nedir sorusuna nasıl yaklaşılmalıdır?','Tuzak sorulardan biridir. Etkili yanıt: gerçek bir zayıf yönü dürüstçe kabul etmek (bu insan olduğunuzu gösterir) + bu konuda neler yaptığınızı/geliştirmekte olduğunuzu açıklamak. "Çok çalışkanlığım" gibi sahte zayıflıklar veya temel bir gereksinimi zayıf yön olarak sunmak kabul görmez.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Zayıf yönüm yok, sürekli kendimi geliştiriyorum" diyerek güçlü bir izlenim yaratılır' FROM q UNION ALL SELECT id,1,'Pozisyonun en kritik gereksinimi zayıf yön olarak sunulur; bu dürüstlük göstergesidir' FROM q UNION ALL SELECT id,2,'"Çok çalışkanlığım veya mükemmeliyetçiliğim" diyerek güçlü yönü zayıf yön gibi sunmak en iyi stratejidir' FROM q UNION ALL SELECT id,3,'Gerçek ama kritik olmayan bir zayıf yön kabul edilir ve bu konuda alınan somut gelişim adımları anlatılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','junior','5 yıl sonra kendinizi nerede görüyorsunuz sorusu neden sorulur?','Bu soru şunları ölçer: kariyer planlaması var mı, şirkette uzun vadeli mi kalacaksınız, pozisyon kariyer hedeflerinizle örtüşüyor mu. Etkili yanıt: gerçekçi büyüme hedefleri + şirketin büyümesiyle nasıl katkı sağlayacağınız. "CEO olmak istiyorum" veya "bilmiyorum" aşırı uçlar kaçınılmalıdır.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Kariyer hedeflerinin şirket büyümesiyle nasıl örtüştüğü gerçekçi şekilde anlatılır; somut büyüme adımları belirtilir' FROM q UNION ALL SELECT id,1,'"5 yıl sonrasını düşünmüyorum; bugüne odaklanmak daha mantıklı" diyerek pratik yaklaşım sergilenir' FROM q UNION ALL SELECT id,2,'"CEO veya CTO olmak istiyorum" diyerek yüksek hedefler ortaya konur; bu motivasyon göstergesidir' FROM q UNION ALL SELECT id,3,'"Tam olarak bilmiyorum; ne gelirse" diyerek esneklik vurgulanır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','junior','Bir deadline''ı kaçırdığınız durumu nasıl ele alırsınız?','STAR yapısı kullanın: neden kaçırıldığı (kök neden), paydaşlara proaktif iletişim (beklenti yönetimi), çözüm planı ve öğrenilen ders. "Hiç kaçırmadım" yanıtı inandırıcı değildir. Suçu başkasına yüklememek ve sorumluluk almak kritiktir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Mülakatçı görmeden gizlice tamamlarım" yaklaşımıyla çözüm odaklı olduğunuz kanıtlanır' FROM q UNION ALL SELECT id,1,'STAR yapısıyla: kök neden, paydaşlara erken iletişim, çözüm planı ve öğrenilen ders anlatılır' FROM q UNION ALL SELECT id,2,'"Hiç deadline kaçırmadım; bu benim en güçlü yönüm" diyerek güvenilirlik mesajı verilir' FROM q UNION ALL SELECT id,3,'Sorumluluğu ekip veya yöneticiye yüklenerek kişisel hatadan kaçınılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','junior','Takım çalışmasındaki rolünüzü nasıl tanımlarsınız?','Bu soruyla: takımda nasıl çalıştığınız, başkalarının katkısına nasıl yaklaştığınız ve conflict handling yetkinliğiniz ölçülür. Etkili yanıt: spesifik bir proje örneğiyle takıma nasıl katkı sağladığınız, iletişim tarzınız ve ortak başarıya nasıl sahip çıktığınız anlatılmalıdır.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Her zaman takım lideriyim; başkalarına yol göstermek doğal yeteneğimdir" diyerek liderlik vurgulanır' FROM q UNION ALL SELECT id,1,'"Yalnız çalışmayı tercih ederim; takım toplantıları verimliliği düşürür" diyerek bağımsızlık ifade edilir' FROM q UNION ALL SELECT id,2,'Spesifik proje örneğiyle takıma nasıl katkı sağlandığı, iletişim tarzı ve ortak başarıya sahip çıkma anlatılır' FROM q UNION ALL SELECT id,3,'"Takım çalışması hakkında teorik bilgim var; pratik deneyimim henüz az" diyerek dürüstlük sergilenir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','junior','Çalışma tarzınızı tanımlamanız istense ne söylersiniz?','Bu soru: öz farkındalık, öz yönetim ve pozisyon uyumunu ölçer. Şirket kültürü araştırılmış olmalı; yanıt şirket değerleriyle örtüşmeli. Hem güçlü yönleri hem de öğrenme alanlarını dürüstçe belirtmek, yalnızca "ideal" tarif etmekten daha inandırıcıdır.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Her türlü çalışma ortamına uyum sağlarım; tercihim yoktur" diyerek esneklik vurgulanır' FROM q UNION ALL SELECT id,1,'Mülakatçının beklediği cevabı tahmin ederek ona göre yanıt verilir' FROM q UNION ALL SELECT id,2,'"Çok disiplinli ve sabahları verimli çalışırım; akşamları ise tercih etmem" diyerek aşırı spesifik olunur' FROM q UNION ALL SELECT id,3,'Öz farkındalıkla gerçek çalışma tarzı anlatılır, şirket kültürüyle örtüşen yönler öne çıkarılır ve öğrenme alanları dürüstçe belirtilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','junior','Maaş beklentiniz nedir sorusunu nasıl ele alırsınız?','Etkili strateji: önce piyasa araştırması yapın (Glassdoor, LinkedIn Salary). Mümkünse karşı tarafın bütçesini sormak için soruyu yansıtın. Bir aralık verin ("X ile Y arasında, tecrübe ve toplam pakete bağlı"). Çok düşük aralık değerinizi düşürür; çok yüksek eleme riski taşır.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Piyasa araştırması yapılır, aralık olarak verilir; mümkünse önce şirketin bütçe aralığını sormak için soru yansıtılır' FROM q UNION ALL SELECT id,1,'"Maaş önemli değil; sadece öğrenmek ve gelişmek istiyorum" diyerek esneklik gösterilir' FROM q UNION ALL SELECT id,2,'Mümkün olan en yüksek rakam söylenir; müzakere payı bırakıldığı izlenimi verilir' FROM q UNION ALL SELECT id,3,'Mevcut maaşın %10 fazlası istenir; bu standart sektör pratiğidir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','junior','Mülakatın sonunda mülakatçıya ne sormak önemlidir?','Soru sormak: ilgini, araştırmanı ve profesyonelliğini gösterir. Etkili sorular: ekip kültürü, başarının ölçüm kriterleri, en büyük teknik zorluklar, onboarding süreci, büyüme fırsatları. Kaçınılacaklar: maaş/yan haklar (önceden belirtilmediyse ilk mülakatda), tatil ve erken çıkış politikaları.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Soru sormaya gerek yok; her şey net anlaşıldı" diyerek zaman kazandırılır' FROM q UNION ALL SELECT id,1,'Ekip kültürü, başarı kriterleri, teknik zorluklar, büyüme fırsatları gibi anlamlı sorular yöneltilir' FROM q UNION ALL SELECT id,2,'Yalnızca maaş ve yan haklarla ilgili detaylar sorulur; bunlar işin en önemli kriterleridir' FROM q UNION ALL SELECT id,3,'Şirketin mali durumu ve son çeyrek karı hakkında soru sorulur; bu due diligence göstergesidir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','junior','Uzaktan çalışma tercihini mülakatçıya nasıl ifade etmelisiniz?','Dürüstlük önemlidir: tercihinizi belirtin ancak şirketin politikasına uyum sağlayabileceğinizi de gösterin. Şirket politikasını önceden araştırın. Hibrit veya tam ofis şirketi için uzaktan çalışma ısrarı olumsuz izlenim yaratır. Uyum kabiliyeti ve professionalism öne çıkarılmalıdır.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Yalnızca uzaktan çalışırım; ofise gelmem mümkün değil" diyerek net sınır koyulur' FROM q UNION ALL SELECT id,1,'"Tamamen ofis çalışmasını tercih ederim" diyerek her şirket politikasına uygun yanıt verilir' FROM q UNION ALL SELECT id,2,'Tercihinizi dürüstçe belirtip şirket politikasına uyum sağlayabileceğinizi ve esnekliğinizi gösterirsiniz' FROM q UNION ALL SELECT id,3,'"Bu konuda hiç düşünmedim; siz ne önerirsiniz?" diyerek karar mülakatçıya bırakılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','junior','Kariyerinizde en gurur duyduğunuz başarınız nedir?','STAR yapısı: Situation (bağlam) → Task (görev/zorluk) → Action (aldığınız spesifik aksiyonlar) → Result (ölçülebilir sonuç). Pozisyonla ilgili bir başarı seçin. Ölçülebilir sonuçlar (% artış, maliyet düşüşü, süre kısalması) anlatıyı güçlendirir. Takım başarısında kendi katkınızı net ifade edin.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"En büyük başarım şu an burada olmak; bu mülakata çağrılmak zaten bir başarıdır" diyerek alçakgönüllülük gösterilir' FROM q UNION ALL SELECT id,1,'En eskiden en yeniye tüm başarılar kronolojik sırayla anlatılır; liste mülakatçıyı etkiler' FROM q UNION ALL SELECT id,2,'Yalnızca takım başarıları anlatılır; bireysel katkıyı öne çıkarmak kibir göstergesidir' FROM q UNION ALL SELECT id,3,'STAR yapısıyla pozisyonla ilgili en anlamlı başarı; spesifik aksiyonlar ve ölçülebilir sonuçlarla anlatılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','mid','Bir meslektaşınızla yaşadığınız çatışmayı nasıl çözdünüz?','STAR yapısı + çatışma çözüm becerileri. İdeal yanıt: çatışmanın kişisel değil konu odaklı olduğunu göstermek, aktif dinleme, ortak zemin bulma, gerektiğinde esnek tavır. Karşı tarafı suçlayan, müdüre şikâyet eden veya "hiç çatışmam olmadı" yanıtları olumsuz işaretlerdir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'STAR yapısıyla: konu odaklı yaklaşım, aktif dinleme ve ortak zemin bulma süreci anlatılır; kişi suçlanmaz' FROM q UNION ALL SELECT id,1,'"Hiçbir zaman meslektaşımla çatışmadım; iyi bir takım oyuncusuyum" diyerek çatışmasız profil sunulur' FROM q UNION ALL SELECT id,2,'Müdürün müdahalesiyle çözüldüğünü anlatmak; bu otoritenin doğru kullanılmasının göstergesidir' FROM q UNION ALL SELECT id,3,'"Karşı taraf tamamen hatalıydı; benim yaklaşımım kanıtlandı" diyerek haklı çıkma deneyimi anlatılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','mid','Eleştiriyle karşılaştığınızda nasıl tepki verirsiniz?','Eleştiriyi büyüme fırsatı olarak çerçevelemek: önce dinlemek ve anlamak (defansif olmamak), geri bildirimin doğru olup olmadığını değerlendirmek, yapıcıysa uygulamak ve teşekkür etmek. Eğer haksızsa saygılı şekilde farklı bakış açısı paylaşmak. Somut örnek verilerek anlatılmalıdır.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Eleştiriye hiç açık değilim; güçlü görüşlerim vardır ve fikrimi nadiren değiştiririm" diyerek kararlılık gösterilir' FROM q UNION ALL SELECT id,1,'Önce aktif dinleme, değerlendirme; yapıcı ise uygulama ve teşekkür; haksızsa saygılı farklı bakış açısı paylaşmak anlatılır' FROM q UNION ALL SELECT id,2,'"Her eleştiriyi derhal kabul ederim; tartışmaktan kaçınırım" diyerek çatışmadan kaçınma gösterilir' FROM q UNION ALL SELECT id,3,'"Eleştiriyi kişisel alırım ve motivasyonum düşer; bu benim en büyük zayıf yönüm" diyerek dürüst yanıt verilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','mid','Kariyerinizde yaşadığınız bir başarısızlığı STAR yöntemiyle anlatın.','STAR yapısı burada kritik: gerçek bir başarısızlık seçin (önemsizmiş gibi görünen değil), kendi rolünüzü ve neden başarısız olduğunu dürüstçe anlatın, sonra öğrenilen ders ve bu dersin uygulandığı sonraki deneyimi ekleyin. "Hiç başarısız olmadım" veya suçu dışarıya yüklemek büyük hata.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Hiçbir zaman başarısız olmadım; her projem başarıyla tamamlandı" diyerek güven gösterilir' FROM q UNION ALL SELECT id,1,'Başarısızlığın ekip hatası olduğu, kendi katkısının minimal olduğu özellikle vurgulanır' FROM q UNION ALL SELECT id,2,'Gerçek başarısızlık, kendi rolü ve öğrenilen ders STAR yapısıyla anlatılır; dersin uygulandığı sonraki deneyim eklenir' FROM q UNION ALL SELECT id,3,'"Maaş beklentilerim karşılanmadığı için ayrıldığım şirketteki proje başarısızlıktı" diyerek somut örnek verilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','mid','Birden fazla öncelikli görevi aynı anda yönetmek zorunda kaldığınızda ne yaparsınız?','Etkili zaman/öncelik yönetimi: 1) Görünürlük: tüm görevler listelenir. 2) Önceliklendirme: etki ve aciliyet (Eisenhower matrisi). 3) İletişim: paydaşlarla beklenti yönetimi. 4) Odaklanma: çoklu görev yerine sıralı tamamlama. Somut araç/yöntem örneği (Jira, Kanban, zaman blokları) güvenilirlik katar.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Hepsini eş zamanlı yaparak hızımı artırırım; multitasking en büyük güçlüm" diyerek hız vurgulanır' FROM q UNION ALL SELECT id,1,'"Yöneticim hangisi önce derse onu yaparım; karar vermek benim işim değil" diyerek hiyerarşiye saygı gösterilir' FROM q UNION ALL SELECT id,2,'"Görevi reddederim; aşırı yük kalite düşürür" diyerek sınır koyma gösterilir' FROM q UNION ALL SELECT id,3,'Görevleri listele, etki/aciliyet bazlı önceliklendir, paydaşlarla beklenti yönet, sıralı tamamlamaya odaklan; somut araç örneği verilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','mid','Yöneticinizle fikir ayrılığı yaşadığınızda nasıl davranırsınız?','Dengeli yanıt: 1) Yöneticinizin bakış açısını tam anlayın (aktif dinleme). 2) Veriye ve gerekçelere dayalı farklı görüşünüzü saygılı şekilde sunun. 3) Nihai karar yöneticininde ise kabul edin ve tam destek verin. Patrona karşı her zaman itaat veya hiç itiraz etmeme iki aşırı uçtur.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Önce tam anlamaya çalışılır, veri ve gerekçeyle saygılı farklı görüş sunulur; nihai karar yöneticideyse tam destekle hayata geçirilir' FROM q UNION ALL SELECT id,1,'"Yönetici her zaman haklıdır; tartışmak zaman kaybıdır" diyerek itaat vurgulanır' FROM q UNION ALL SELECT id,2,'"Pes etmem; haklı olduğumu kanıtlayana kadar tartışmaya devam ederim" diyerek kararlılık gösterilir' FROM q UNION ALL SELECT id,3,'"Sessiz kalıp kendi görüşümü yavaşça hayata geçiririm" diyerek inisiyatif kullanıldığı gösterilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','mid','Junior bir takım üyesine mentörlük yaparken nelere dikkat edersiniz?','Etkili mentörlük: ihtiyaçlarını dinlemek (ne öğrenmek istiyor, nerede takılıyor), çözümü vermek yerine soru sorarak keşfettirmek (Socratic yöntem), uygun zorlukta görev vermek, yapıcı geri bildirim vermek, güvenli alan oluşturmak. Öğrenmeyi hızlandırmak için kendi hatalarınızı da paylaşmak değerlidir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Tüm bilgimi aktarırım; ne kadar çok öğrenirlerse o kadar iyi" diyerek bilgi paylaşımı vurgulanır' FROM q UNION ALL SELECT id,1,'İhtiyaçlarını dinlemek, soru sorarak keşfettirmek, uygun zorlukta görev vermek ve güvenli alan oluşturmak anlatılır' FROM q UNION ALL SELECT id,2,'"Junior''lar kendi başlarına öğrenmeli; çok yardım bağımlılık yaratır" diyerek öz öğrenme teşvik edilir' FROM q UNION ALL SELECT id,3,'"Tüm kararları onlar adına alırım; deneyim kazandıkça bağımsız bırakırım" diyerek koruyucu yaklaşım sergilenir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','mid','Belirsiz veya eksik şartnameli bir göreve atandığınızda nasıl yaklaşırsınız?','Ambiguity tolerans becerisini ölçer. Etkili yaklaşım: önce mevcut bilgiyle hızlı analiz, kritik belirsizlikleri belirle, paydaşlarla netleştirici soru sor (hepsini değil, kritik olanları), varsayımları açıkça belgele, küçük adımlarla ilerle ve erken geri bildirim al. "Tüm detaylar netleşene kadar başlayamam" kaçınılmalıdır.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Tüm detaylar netleşene kadar başlamam; yanlış gitmenin maliyeti çok yüksek" diyerek dikkatli yaklaşım gösterilir' FROM q UNION ALL SELECT id,1,'"Her şeyi baştan kendim kararlaştırırım; soru sormak yetersizlik göstergesidir" diyerek bağımsızlık vurgulanır' FROM q UNION ALL SELECT id,2,'Kritik belirsizlikler tespit edilir, paydaşlara odaklı sorular sorulur, varsayımlar belgelenir, küçük adımlarla erken geri bildirim alınır' FROM q UNION ALL SELECT id,3,'"Proje tamamen biter, sonra geri bildirim alırım; önceden onay almak bürokratik yavaşlık yaratır" diyerek hız vurgulanır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','mid','Bozuk veya verimsiz bir süreci iyileştirdiğiniz bir deneyimi anlatın.','STAR yapısı + problem solving. Etkileyici yanıt unsurları: sorunu önce ölçmek (mevcut durum verileri), kök neden analizi, çözüm önerisi ve uygulama, sonuçları ölçmek (süre/maliyet/hata oranı iyileşmesi). Çözümü tek başınıza değil paydaşlarla birlikte tasarlamak "takım oyuncusu" izlenimi katar.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Böyle bir deneyimim yok; her süreç zaten optimal çalışıyordu" diyerek mevcut sisteme güven gösterilir' FROM q UNION ALL SELECT id,1,'"Tamamen yeniden inşa ettim; eski sistemi tamamen çöpe attım" diyerek radikal yaklaşım sergilenir' FROM q UNION ALL SELECT id,2,'"Sürecin iyileştirilmesi gerektiğini biliyor ama müdahale etmemeyi tercih ediyordum" diyerek gelecek planı açıklanır' FROM q UNION ALL SELECT id,3,'STAR yapısıyla: sorunu ölçmek, kök neden analizi, çözüm tasarlamak, uygulamak ve sonuçları ölçmek anlatılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','mid','Yeni bir teknolojiyi veya programlama dilini hızlıca öğrenmek zorunda kaldığınızda nasıl yaklaşırsınız?','Öğrenme stratejisi: 1) Mevcut bilgiyle analoji kurmak (ne biliyor musunuz?). 2) Official documentation + pratik proje. 3) Küçük toy project ile hands-on uygulama. 4) Community/topluluğa katılım. Süre tahmini ve milestone''lar vermek güvenilirlik katar. "Öğrenemem" veya "her şeyi anlarım" iki uçtan kaçınılır.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Mevcut bilgiyle analoji kurmak, doc + pratik proje, küçük toy project ve community; süre tahmini ile milestone''lar belirtilir' FROM q UNION ALL SELECT id,1,'"Tüm Stack Overflow sorularını okuyorum; bu yeterli" diyerek pratik yaklaşım gösterilir' FROM q UNION ALL SELECT id,2,'"Yeni teknoloji öğrenmeyi sevmiyorum; mevcut stack''imde kalıcı olmayı tercih ederim" diyerek uzmanlaşma vurgulanır' FROM q UNION ALL SELECT id,3,'"AI araçları her şeyi anında öğretir; ayrıca zaman harcamaya gerek yok" diyerek araç bağımlılığı gösterilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','mid','Bir ekip üyesine zor geri bildirim vermek zorunda kaldığınızda nasıl yaklaşırsınız?','Etkili geri bildirim: özel ortamda, zamanında, spesifik davranış odaklı (kişilik değil), etki odaklı ("bu hatanın sonucu şu oldu"), iyileştirme önerileriyle birlikte. SBI (Situation-Behavior-Impact) modeli. Amacın cezalandırma değil geliştirme olduğunu göstermek önemlidir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Geri bildirimi e-posta ile yazılı veririm; bu şeffaflık ve referans açısından önemlidir"' FROM q UNION ALL SELECT id,1,'Özel ortamda, zamanında, davranış-etki odaklı ve iyileştirme önerileriyle birlikte (SBI modeli); kişilik değil davranış hedeflenir' FROM q UNION ALL SELECT id,2,'"Takım toplantısında herkesin önünde söylersem diğerleri de duyar ve benzer hatadan kaçınır"' FROM q UNION ALL SELECT id,3,'"Geri bildirim vermekten kaçınırım; herkes kendi performansını kendisi değerlendirmeli"' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','mid','İş-özel hayat dengesini nasıl sağlıyorsunuz?','Bu soru: öz yönetim, sınır koyma ve sürdürülebilirlik hakkında bilgi toplar. Etkili yanıt: çalışma saatlerinde sınırlar (toplantısız saatler, bildirim kapatma), fiziksel aktivite/hobiler, enerji yönetimi. Şirkete zarar vermeden kişisel sınırları nasıl koruduğunuzu göstermek profesyonelliktir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"İş-özel hayat dengesi diye bir şey yoktur; başarı için tam adanma şarttır" diyerek yüksek motivasyon sergilenir' FROM q UNION ALL SELECT id,1,'"Saat 17:00''de her zaman çalışmayı bırakırım; hiçbir şey bu sınırı geçemez" diyerek net sınır konur' FROM q UNION ALL SELECT id,2,'Sürdürülebilir çalışma pratiği (sınırlar, enerji yönetimi, hobiler) anlatılır; bu verimliliği ve uzun vadeli performansı artırdığı vurgulanır' FROM q UNION ALL SELECT id,3,'"Şirkete bağlı olarak değişir; siz ne bekliyorsunuz?" diyerek beklentilere göre yanıt uyarlanır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','mid','Teknik borç (technical debt) ile yeni özellik geliştirme arasında denge nasıl kurulur?','Bu soru: teknik ve iş perspektifini bir arada yönetme becerisini ölçer. Etkili yanıt: teknik borcu görünür kılmak (backlog, sprint kapasitesinde %20 gibi), iş etkisiyle ilişkilendirmek (bug rate, deploy süresi), stakeholder iletişimi, büyük refactor yerine "boy scout rule" (dokunduğun yeri bıraktığından daha temiz bırak) gibi inkremental yaklaşım.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Her zaman yeni özellik geliştirme önce gelir; teknik borç ile kim ilgilenir?" diyerek iş odaklılık gösterilir' FROM q UNION ALL SELECT id,1,'"Her zaman teknik borç önce gelinir; özellik geliştirme sağlam altyapı gerektirir" diyerek mühendislik önceliklenir' FROM q UNION ALL SELECT id,2,'"Teknik borç ve özellik geliştirme arasında denge kurmak proje yöneticisinin sorumluluğudur" diyerek sorumluluk paylaşılır' FROM q UNION ALL SELECT id,3,'Teknik borcu görünür kılmak, iş etkisiyle ilişkilendirmek, sprint kapasitesinde yer açmak ve inkremental temizlik yaklaşımı anlatılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','senior','Resmi otoriteniz olmadan bir ekibi nasıl yönlendirirsiniz?','Otorite olmadan liderlik (influence without authority): güven inşa etmek (teknik yetkinlik + yardımseverlik), ortak hedef çerçevelemek, veriye dayalı argüman sunmak, küçük kazanımlar elde ederek momentum yaratmak, takım üyelerinin ilgi/güçlü yönleriyle görev eşleştirme. Zorlama değil, çekicilik (pull) odaklı liderlik.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Güven inşa etmek, veri odaklı argüman, ortak hedef çerçeveleme ve küçük kazanımlarla momentum; zorlama değil pull liderlik' FROM q UNION ALL SELECT id,1,'"Otorite olmadan liderlik mümkün değildir; önce resmi pozisyon alınmalıdır" diyerek sınır netleştirilir' FROM q UNION ALL SELECT id,2,'"Ekip üyelerinin performansını yöneticilere raporlarım; bu dolaylı etki yaratır" diyerek strateji açıklanır' FROM q UNION ALL SELECT id,3,'"Kural koymak yerine herkese evet derim; bu şekilde popülerlik kazanılır" diyerek yumuşak liderlik tercih edildiği belirtilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','senior','Organizasyonda büyük bir değişikliği (süreç, teknoloji, kültür) nasıl yönetirdiniz?','Change management: 1) Why''ı net açıklamak (yanma hissi - burning platform). 2) Early adopter''ları bulmak ve onları değişim elçisi yapmak. 3) Küçük kazanımlarla güven inşa etmek. 4) Direnci empatiyle anlamak (kayıp duygusu). 5) Başarıyı kutlamak. Kotter''ın 8 adımı referans alınabilir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Değişimi zorunlu tutarım; insanlar uyum sağlar ya da ayrılır" diyerek kararlılık mesajı verilir' FROM q UNION ALL SELECT id,1,'"Neden" açıklanır, early adopter ile momentum yaratılır, direnç empatiyle anlaşılır, küçük kazanımlarla güven inşa edilir' FROM q UNION ALL SELECT id,2,'"Değişimi duyurur, süreyi belirler ve takibi müdürlere bırakırım; detaya inmek gerekmiyor" diyerek delegasyon gösterilir' FROM q UNION ALL SELECT id,3,'"Değişim iyi şeydir; insanlar kendiliğinden uyum sağlar; özel yönetim gerektirmez" diyerek optimizm sergilenir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','senior','Ekibinizdeki düşük performanslı bir çalışanla nasıl başa çıkarsınız?','Adil ve etkili yaklaşım: 1) Önce kök neden anla (motivasyon eksikliği mi, beceri mi, kişisel sorun mu?). 2) Net beklenti ve geri bildirim. 3) Geliştirme planı (PIP) ve destek. 4) İlerlemeyi izle. 5) Gerekirse rol değişikliği veya çıkış. Erkenden müdahale etmek hem çalışana hem ekibe daha adil.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Düşük performanslı çalışanı hemen işten çıkarırım; ekibin morali için bu en iyisi" diyerek kararlılık gösterilir' FROM q UNION ALL SELECT id,1,'"Görmezden gelirim; zaman içinde kendiliğinden iyileşir veya ayrılır" diyerek sabırlı yaklaşım sergilenir' FROM q UNION ALL SELECT id,2,'Kök neden analizi, net beklenti, geliştirme planı ile destek, ilerleme takibi; gerekirse rol değişimi veya çıkış süreci anlatılır' FROM q UNION ALL SELECT id,3,'"Diğer takım üyelerinin baskısıyla performansı artmasını beklerim; peer pressure işe yarar" diyerek dolaylı motivasyon gösterilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','senior','Güçlü bir mühendislik kültürü oluşturmak için ne gerekir?','Güçlü mühendislik kültürü unsurları: psikolojik güvenlik (hata yapmak öğrenmek), code review kültürü, öğrenme zamanı (hack day, konferans, kitap), teknik mükemmellik ve pragmatizm dengesi, teknik liderliğin takdiri, kapsayıcılık (diverse düşünce). Kültür top-down değil grassroots ile güçlenir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"İyi kültür ücretten gelir; yüksek maaş verin, kültür kendiliğinden oluşur" diyerek somut yatırım önerilir' FROM q UNION ALL SELECT id,1,'"Kültür dokümanları yazmak ve değer listesi hazırlamak yeterlidir" diyerek süreç vurgulanır' FROM q UNION ALL SELECT id,2,'"Her mühendis kendi kültürünü oluşturur; merkezi kültür dayatmak özerkliği kısıtlar" diyerek bireysellik savunulur' FROM q UNION ALL SELECT id,3,'Psikolojik güvenlik, öğrenme zamanı, code review kültürü, teknik mükemmellik ve kapsayıcılık; grassroots büyümesi vurgulanır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','senior','Takım üyeleri için kariyer gelişim yolunu nasıl tanımlarsınız?','Kariyer gelişim: 1) Bireysel güçlü yönler ve hedeflerini anlamak. 2) IC (Individual Contributor) ve management track seçenekleri sunmak. 3) Gelişim alanlarını stretch assignment''lar ile pratik etmek. 4) Düzenli 1:1 ve geri bildirim döngüsü. 5) Dış fırsatlar (konferans, mentorluk, eğitim). Tek yol haritası herkese uymaz.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Bireysel hedef anlamak, IC/management track sunmak, stretch assignment, düzenli 1:1 ve dış fırsatlar; tek şablon herkese uymaz' FROM q UNION ALL SELECT id,1,'"Yıllık performans değerlendirme yeterlidir; ek kariyer planlama toplantısı gereksizdir" diyerek verimlilik vurgulanır' FROM q UNION ALL SELECT id,2,'"Herkes seniority sırasına göre terfi eder; ayrı kariyer planı yapmaya gerek yok" diyerek sistem güvenilir bulunur' FROM q UNION ALL SELECT id,3,'"Kariyer gelişim HR''ın sorumluluğudur; mühendis yöneticisi yalnızca teknik konulara odaklanmalıdır" diyerek rol ayrımı netleştirilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','senior','İşe alım sürecinde bir adayı değerlendirirken nelere öncelik verirsiniz?','İşe alım kriterleri: teknik yetkinlik (temel problem çözme, mevcut bilgi) + öğrenme kapasitesi (hızlı adapte olabilir mi?) + kültürel uyum (değerlerle örtüşme, takım dinamiğine katkı) + iletişim (düşünce netliği). Yalnızca trivia knowledge sorgulamak yanıltıcıdır; nasıl düşündüklerini görmek daha değerlidir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Sadece teknik test puanı; diğer faktörler sübjektiftir ve güvenilmez" diyerek objektiflik vurgulanır' FROM q UNION ALL SELECT id,1,'Teknik yetkinlik + öğrenme kapasitesi + kültürel uyum + iletişim netliği; düşünce sürecini görmek trivia''dan değerlidir' FROM q UNION ALL SELECT id,2,'"Kaç yıl deneyimi var; deneyim her şeydir" diyerek deneyim odaklı değerlendirme yapılır' FROM q UNION ALL SELECT id,3,'"Üniversite adı ve GPA yeterli gösterge; diğer kriterler ikincil öneme sahip" diyerek akademik geçmiş önceliklendirilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','senior','Legacy sistemi modernize etme yaklaşımınız nedir?','Legacy modernizasyon stratejileri: Strangler Fig (sistemi dışarıdan saran yeni bileşenler kademeli olarak eski yerini alır), Big Bang (riskli, büyük kesinti), Branch by Abstraction (soyutlama katmanı arkasında kademeli değişim). Risk yönetimi: özellik dondurma, paralel çalıştırma, feature flag. İş hedefleriyle teknik hedefleri hizalamak kritiktir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Sistemi komple kapatır, 6 ayda yeniden yazarım; yarım iş olmaz" diyerek Big Bang yaklaşımı benimsenir' FROM q UNION ALL SELECT id,1,'"Legacy sisteme hiç dokunmam; risk çok yüksek" diyerek muhafazakâr yaklaşım sergilenir' FROM q UNION ALL SELECT id,2,'Strangler Fig (kademeli sarma), Branch by Abstraction; paralel çalıştırma ve feature flag ile risk yönetimi; iş hedefleriyle hizalama anlatılır' FROM q UNION ALL SELECT id,3,'"Legacy modernizasyon her zaman başarısız olur; yeni sistemle hayata geçirmek daha iyidir" diyerek yeniden başlama önerilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','senior','Teknik olmayan paydaşlarla (CEO, ürün yöneticisi, müşteri) iletişim kurarken nelere dikkat edersiniz?','Teknik olmayan paydaş iletişimi: 1) Jargondan kaçın, iş etkisi üzerinden konuş. 2) Görsel kullan (diyagram, metafor). 3) Onların önceliklerini dinle ve çözümü onların diliyle çerçevele. 4) Seçenek sun, öneride bulun. 5) Somut zaman ve sonuç tahmini ver. Çift yönlü dinleme kadar önemli.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Teknik detayları tam ve eksiksiz aktarırım; bilgisizlik kararları kötü yaptırır" diyerek şeffaflık vurgulanır' FROM q UNION ALL SELECT id,1,'"Teknik konuları onlara açıklayamazsınız; ara katman bırakılması gerekir" diyerek ayrıştırma önerilir' FROM q UNION ALL SELECT id,2,'"E-posta yeterli; toplantı zamanı çalmaz" diyerek asenkron iletişim savunulur' FROM q UNION ALL SELECT id,3,'Jargondan kaçın, iş etkisi diliyle çerçevele, görsel kullan, seçenek sun, somut zaman/sonuç tahmini ver; çift yönlü dinle' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','senior','İnovasyon ile istikrar arasındaki dengeyi nasıl sağlarsınız?','Bu gerilim her mühendis ekibinde vardır. Pratik denge: belirli kapasiteyi (20%) keşif/yenilik için ayırmak, risk seviyesine göre inovasyon alanı belirlemek (core sistemde düşük risk, kenar bileşende yüksek risk kabul), kill criteria önceden belirlemek, küçük deneyleri hızlı validate etmek (fail fast).',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Kapasite ayırmak (%20), risk seviyesine göre alan belirlemek, kill criteria önden tanımlamak, küçük deney + hızlı validasyon' FROM q UNION ALL SELECT id,1,'"İnovasyon ve istikrar karşıt değil; doğru mühendislik ikisini eş zamanlı sağlar" diyerek soruyu reddedilir' FROM q UNION ALL SELECT id,2,'"İstikrar her zaman önce gelir; büyüme dönemlerinde inovasyon yapılır" diyerek dönemsel yaklaşım benimsenir' FROM q UNION ALL SELECT id,3,'"İnovasyon ayrı bir takımın sorumluluğudur; ana mühendislik istikrara odaklanmalıdır" diyerek ayrışma önerilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','senior','Ekibin sağlığını ölçmek için hangi göstergelere bakarsınız?','Ekip sağlığı metrikleri: DORA metrikleri (deploy frequency, lead time, MTTR, change fail rate), cycle time, toil oranı, geri bildirim kalitesi. Soft göstergeler: psikolojik güvenlik (lider hatası kabul ediyor mu?), gönüllü ayrılma oranı, engagement score, bağımlılık haritası (tek kişilik bilgi siloları var mı?).',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Yalnızca kod satırı sayısı ve commit sıklığına bakarım; bunlar somut göstergelerdir" diyerek metrik odaklılık gösterilir' FROM q UNION ALL SELECT id,1,'DORA metrikleri + cycle time + toil; psikolojik güvenlik, gönüllü ayrılma oranı ve bilgi siloları soft göstergeler olarak izlenir' FROM q UNION ALL SELECT id,2,'"Ekip sağlığı sübjektif bir kavramdır; ölçülemez, yalnızca hissedilebilir" diyerek ölçüm reddedilir' FROM q UNION ALL SELECT id,3,'"Yalnızca müşteri memnuniyet skoru izlenir; diğer her şey araçsal değerdir" diyerek dışsal odak vurgulanır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','mid','Farklı ekiplerle ortak çalışırken (cross-team) yaşanan en büyük zorluk nedir?','Cross-team zorluklar: farklı öncelik ve takvimler, farklı teknik standartlar, iletişim overhead, bağımlılık yönetimi. Etkili yaklaşım: erken ve düzenli iletişim, API/interface sözleşmeleri önceden netleştirme, bağımlılıkları görünür kılma, karşılıklı anlayış için embed/rotation. Suçlama yerine sistem yaklaşımı.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Diğer ekipler her zaman daha az kaliteli iş çıkarır; kendi ekibimiz olmadan çalışmayı tercih ederim" diyerek bağımsızlık vurgulanır' FROM q UNION ALL SELECT id,1,'"Cross-team çalışma her zaman başarısızlıkla sonuçlanır; proje ekip sınırlarında yönetilmelidir" diyerek meydan okuma tanımlanır' FROM q UNION ALL SELECT id,2,'Farklı öncelik/takvim ve bağımlılık yönetimi; erken iletişim, API sözleşmeleri önceden netleştirme ve bağımlılıkları görünür kılmak anlatılır' FROM q UNION ALL SELECT id,3,'"Cross-team zorluk yaşamadım; herkes birbirine saygı duyduğu sürece sorun çıkmaz" diyerek iyimser profil sunulur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','mid','Kendinizde impostor syndrome (sahtekârlık sendromu) hissediyor musunuz ve bununla nasıl başa çıkıyorsunuz?','Impostor syndrome çok yaygındır; dürüstçe kabul etmek güç işaretidir. Başa çıkma yolları: geçmiş başarıları somut belgelemek, güvenilen kişilerle konuşmak, öğrenmenin doğası gereği bilinmezlik içerdiğini kabul etmek, "bilmiyorum, öğreneceğim" diyebilmek. Tamamen olmadığını iddia etmek inandırıcı değildir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Asla hissetmedim; kendime çok güvenirim" diyerek özgüven mesajı verilir' FROM q UNION ALL SELECT id,1,'"Sürekli hissediyorum ve bununla başa çıkamıyorum; bu pozisyona layık olup olmadığımı sorgulamak devam ediyor" diyerek dürüstlük sergilenir' FROM q UNION ALL SELECT id,2,'"Impostor syndrome bir bahane; herkes kendi değerini bilmeli" diyerek eleştirel yaklaşım sunulur' FROM q UNION ALL SELECT id,3,'Zaman zaman hissedildiği kabul edilir; geçmiş başarıları belgelemek, güvenilene konuşmak ve bilmemenin öğrenme sürecinin parçası olduğunu hatırlatmak anlatılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','junior','Stres altında çalışırken performansınızı nasıl korursunuz?','Stres yönetimi: önceliklendirme (ne gerçekten önemli?), parçalara bölme (büyük sorunları yönetilebilir adımlara ayırma), iletişim (gerektiğinde yardım istemek), fiziksel reset (kısa mola, yürüyüş). "Stres altında çok daha iyi çalışırım" genellikle inandırıcı değildir; gerçekçi stratejiler daha etkileyicidir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Önceliklendirme, parçalara bölme, iletişim ve kısa mola ile reset; stres yönetiminin gerçekçi stratejileri anlatılır' FROM q UNION ALL SELECT id,1,'"Stres altında en iyi versiyonumuza ulaşırız; stres olmadan verimlilik düşer" diyerek stres olumlu çerçevelenir' FROM q UNION ALL SELECT id,2,'"Stres hissetmem; çalışma ortamını her zaman sakin tutarım" diyerek sakinlik vurgulanır' FROM q UNION ALL SELECT id,3,'"Stres altında çalışmayı reddederim; sağlıksız ortamda üretken olunamaz" diyerek sınır koyma gösterilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('hr','tr','junior','Kısa vadeli ve uzun vadeli kariyer hedefleriniz nelerdir?','Bu soru: kariyer planlaması, şirkete uyum ve gerçekçi beklentileri ölçer. Etkili yanıt: kısa vade (1-2 yıl: hızlıca ürüne katkı, belirli teknik alanda derinleşme) + uzun vade (3-5 yıl: liderlik veya uzmanlaşma, spesifik alan). Mevcut pozisyonla örtüşmeli; çok belirsiz veya çok iddialı uç kaçınılmalı.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'"Uzun vadeli hedefim yok; kısa vadede para kazanmak yeterli" diyerek pragmatik yaklaşım sergilenir' FROM q UNION ALL SELECT id,1,'Kısa vade: hızlı katkı ve spesifik alan derinleşmesi; uzun vade: gerçekçi liderlik veya uzmanlaşma; pozisyonla örtüşen anlatı' FROM q UNION ALL SELECT id,2,'"Hedeflerim yok; fırsatlar ne getirirse ona giderim" diyerek esneklik vurgulanır' FROM q UNION ALL SELECT id,3,'"5 yıl içinde şirketinizin CEO''su olmak istiyorum" diyerek yüksek motivasyon sergilenir' FROM q;

-- ══════════════════════════════════════════
-- JAVASCRIPT (+40 soru)
-- ══════════════════════════════════════════

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','junior','JavaScript''te hoisting nedir?','Hoisting: `var` bildirimleri ve fonksiyon bildirimleri kapsam başına "yukarı taşınmış" gibi davranılır. `var` undefined ile başlatılır; `let`/`const` TDZ''de başlatılır (erişim ReferenceError). Fonksiyon bildirimleri tamamen hoisted olur; fonksiyon ifadeleri (var f = function) yalnızca değişken kısmı hoisted.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'var bildirimleri ve fonksiyon bildirimleri kapsam başına hoisted olur; var undefined başlatılır, let/const TDZ''de kalır' FROM q UNION ALL SELECT id,1,'Hoisting yalnızca class bildirimlerinde gerçekleşir; var ve let hoisted değildir' FROM q UNION ALL SELECT id,2,'Hoisting, tüm değişkenleri otomatik olarak global kapsama taşıyan bir JavaScript davranışıdır' FROM q UNION ALL SELECT id,3,'Hoisting bir hata mesajıdır; modern JavaScript''te kaldırılmıştır ve artık gerçekleşmez' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','junior','JavaScript''te `typeof null` neden "object" döndürür?','Bu, JavaScript''in ilk versiyonundan gelen tarihsel bir bug''dır. Değerlerin binary temsili: null değerinin bit temsili nesne pointer''larıyla aynı pattern''ı taşıyordu. Düzeltilmesi mevcut kodu bozacağı için kasıtlı olarak korunmaktadır. null kontrolü için `=== null` kullanılmalıdır.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'null, JavaScript''te özel bir object örneği olduğu için typeof "object" döndürür' FROM q UNION ALL SELECT id,1,'JavaScript''in ilk versiyonundan gelen tarihsel bir bug; null''un binary temsili object pointer ile aynı; kasıtlı korundu' FROM q UNION ALL SELECT id,2,'typeof null "object" döndürür çünkü null değerler heap''te saklanır ve reference tipidir' FROM q UNION ALL SELECT id,3,'ECMAScript standardı null''u object subtype olarak tanımlar; bu kasıtlı tasarım kararıdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','junior','Arrow function ile regular function arasındaki `this` bağlama farkı nedir?','Regular function: `this` çağrı bağlamına göre belirlenir (dynamic this). Arrow function: `this` tanımlandığı lexical kapsamdan miras alır; kendine ait `this` yoktur (lexical this). Bu nedenle arrow function prototype metodu veya object method olarak kullanılmamalıdır; event handler ve callback''lerde lexical this avantajlıdır.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Arrow function ve regular function arasında this bağlama farkı yoktur; ikisi de aynı şekilde çalışır' FROM q UNION ALL SELECT id,1,'Arrow function this''i her zaman window (global) nesnesine bağlar; regular function ise nesneye bağlar' FROM q UNION ALL SELECT id,2,'Regular function this''i çağrı bağlamına (dynamic) göre belirler; arrow function lexical kapsamdan (tanımlandığı yer) miras alır' FROM q UNION ALL SELECT id,3,'Arrow function this bağlamaz; her kullanımda ReferenceError fırlatır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','junior','IIFE (Immediately Invoked Function Expression) neden kullanılır?','IIFE: `(function() { ... })()` veya `(() => { ... })()`. Modül sistemleri öncesinde kapsam izolasyonu için kullanılırdı; tüm değişkenler IIFE içinde kalır ve global kapsam kirletilmez. Modern JavaScript''te ES modules aynı kapsam izolasyonunu sağlar. Ancak config başlatma gibi özel durumlarda hâlâ kullanılır.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'IIFE yalnızca async fonksiyonları senkron çalıştırmak için kullanılır' FROM q UNION ALL SELECT id,1,'IIFE, bir fonksiyonu belirli aralıklarla çalıştırmak için kullanılan setInterval alternatifidir' FROM q UNION ALL SELECT id,2,'IIFE, fonksiyonları memoize ederek aynı argümanla tekrar çağrılmasını önler' FROM q UNION ALL SELECT id,3,'Global kapsam kirliliğini önlemek için tanımlanır ve hemen çalıştırılır; ES module öncesinde kapsam izolasyonu sağlardı' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','junior','Spread operatörü (...) hangi durumlarda kullanılır?','Spread operatörü: dizi/nesneyi elemanlarına yayar. Kullanımlar: dizi kopyalama (`[...arr]`), dizi birleştirme (`[...a, ...b]`), fonksiyon argümanlarına yayma (`Math.max(...arr)`), nesne kopyalama/birleştirme (`{ ...obj1, ...obj2 }`). Shallow copy yapar; iç içe nesneler referans olarak kopyalanır.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Dizi/nesne elemanlarına yaymak için kullanılır: kopyalama, birleştirme ve fonksiyon argümanlarına yayma; shallow copy yapar' FROM q UNION ALL SELECT id,1,'Spread yalnızca sayısal dizilerde çalışır; string veya nesne dizilerinde TypeError fırlatır' FROM q UNION ALL SELECT id,2,'Spread derin kopyalama (deep clone) yapar; iç içe nesneler de bağımsız kopyalanır' FROM q UNION ALL SELECT id,3,'Spread yalnızca ES2015 öncesi tarayıcılarda çalışır; modern JavaScript''te kullanımı önerilmez' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','junior','JavaScript''te destructuring assignment nasıl çalışır?','Destructuring: dizi veya nesneden değerleri ayrıştırarak değişkenlere atar. Dizi: `const [a, b] = [1, 2]`. Nesne: `const { x, y } = point`. Varsayılan değer atama, alias ve nested destructuring mümkündür. Function parametrelerinde de kullanılabilir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Destructuring yalnızca nesne tipler için çalışır; primitive değerler destructure edilemez' FROM q UNION ALL SELECT id,1,'Dizi veya nesneden değerleri değişkenlere ayrıştırır; alias, varsayılan değer ve nested destructuring destekler' FROM q UNION ALL SELECT id,2,'Destructuring assignment, orijinal dizi veya nesneyi değiştirir; yeni değişken oluşturmaz' FROM q UNION ALL SELECT id,3,'Destructuring yalnızca const ile kullanılabilir; let veya var ile hata verir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','junior','Template literals (şablon değişmezleri) ne sağlar?','Template literals (backtick ``): çok satırlı string desteği, string interpolasyon (`${expression}`), tagged template literal (özel işleme). String birleştirme operatörüne (+) göre: daha okunabilir, multiline doğal, dinamik ifadeler (`${a + b}`) gömülebilir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Template literals yalnızca HTML şablon motorlarıyla çalışır; vanilla JavaScript''te backtick syntax desteklenmez' FROM q UNION ALL SELECT id,1,'Template literals yalnızca sabit değerler için kullanılabilir; dinamik ifade gömülemez' FROM q UNION ALL SELECT id,2,'Çok satırlı string, ${expression} ile interpolasyon ve tagged template literal desteği sağlar; + operatöründen daha okunabilir' FROM q UNION ALL SELECT id,3,'Template literals her zaman string birleştirme (+) operatöründen yavaştır; yalnızca okunabilirlik için tercih edilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','mid','JavaScript''te closure nasıl çalışır ve pratik kullanım örneği nedir?','Closure: iç fonksiyon, dış fonksiyonun değişkenlerine dış fonksiyon çalışmasını bitirdikten sonra da erişir. Çalışma prensibi: her fonksiyon çağrısında yeni bir execution context ve değişken environment oluşturulur; iç fonksiyon bu environment''ı referans tutar. Kullanımlar: counter fabrika, memoization, module pattern, React hooks state yönetimi.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Closure, bir fonksiyonun kendisini çağırması (özyineleme) için kullanılan özel sözdizimi ifade eder' FROM q UNION ALL SELECT id,1,'Closure yalnızca async/await ile birlikte kullanıldığında oluşur; senkron kod closure oluşturmaz' FROM q UNION ALL SELECT id,2,'Closure, iki farklı dosyadaki modüllerin birbirinin değişkenlerine erişmesini sağlayan ES module özelliğidir' FROM q UNION ALL SELECT id,3,'İç fonksiyon dış kapsamdaki değişkeni closure yoluyla tutar; dış fonksiyon bitse de referans korunur; counter, memoize, module pattern' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','mid','Generator function nedir ve ne zaman kullanılır?','Generator: `function*` ile tanımlanır, `yield` ile değer verir ve çalışmayı duraklatır. `next()` ile bir sonraki yield''a ilerler. Kullanımlar: lazy evaluation (büyük veri üretimi), infinite sequence, async akışlar (redux-saga), custom iterator implementasyonu. Symbol.iterator protokolü ile for...of ile kullanılabilir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'function* ile tanımlanır; yield ile duraklar ve değer üretir; lazy evaluation ve infinite sequence için kullanılır' FROM q UNION ALL SELECT id,1,'Generator, bir fonksiyonu belirli aralıklarla tekrar çalıştıran setInterval''in senkron versiyonudur' FROM q UNION ALL SELECT id,2,'Generator yalnızca TypeScript''te kullanılabilir; vanilla JavaScript''te hata verir' FROM q UNION ALL SELECT id,3,'Generator bir sınıfın constructor metodunun başka bir adıdır; nesne oluşturmada kullanılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','mid','Symbol veri tipinin temel kullanım amaçları nelerdir?','Symbol: her zaman benzersiz primitive değer; `Symbol("key")` farklı çağrılarda farklı değer üretir. Kullanımlar: nesne property anahtarı olarak collision-free anahtar, well-known symbols (Symbol.iterator, Symbol.toPrimitive ile dil davranışı özelleştirme), private property benzeri kapsülleme (tam private değil).',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Symbol yalnızca primitive sayı değerlerini benzersiz şekilde saklamak için kullanılır' FROM q UNION ALL SELECT id,1,'Her zaman benzersiz değer üretir; collision-free property anahtarı ve well-known symbol ile dil davranışı özelleştirme sağlar' FROM q UNION ALL SELECT id,2,'Symbol, JavaScript''teki enumeration (enum) benzeri sabitleri tanımlamak için kullanılan type''dır' FROM q UNION ALL SELECT id,3,'Symbol yalnızca node.js ortamında çalışır; tarayıcı ortamında Symbol desteği yoktur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','mid','WeakMap ve Map arasındaki temel fark nedir?','WeakMap: anahtarlar yalnızca nesne; zayıf referans (weak reference) — anahtar başka yerden referansı kalmayınca GC tarafından temizlenebilir; iterable değil; size özelliği yok. Map: her türlü anahtar; güçlü referans; iterable; size özelliği var. WeakMap: DOM elementlerine metadata ekleme, private data pattern.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'WeakMap ve Map tamamen aynıdır; sadece isim farklılığı vardır' FROM q UNION ALL SELECT id,1,'WeakMap thread-safe, Map ise single-thread için tasarlanmıştır' FROM q UNION ALL SELECT id,2,'WeakMap yalnızca nesne anahtar; zayıf referans (GC temizleyebilir), iterable değil; Map her anahtar, güçlü referans, iterable' FROM q UNION ALL SELECT id,3,'WeakMap daha hızlıdır; büyük koleksiyonlarda Map yerine her zaman WeakMap tercih edilmelidir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','mid','Proxy nesnesi ne için kullanılır?','Proxy: bir nesnenin temel operasyonlarını (get, set, has, deleteProperty...) intercept ve özelleştirmeye yarar. Kullanımlar: validasyon (set trap ile değer kontrolü), logging, lazy initialization, observable nesneler, Vue 3 reactivity sistemi. Reflect API ile birlikte kullanımı yaygındır.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Proxy, farklı origin''lerdeki API''lere CORS kısıtlaması olmadan erişmek için JavaScript''te kullanılan proxy sunucu konfigürasyonudur' FROM q UNION ALL SELECT id,1,'Proxy, nesne klonlamayı optimize eden ve derin kopyalama işlemini otomatikleştiren bir utility sınıfıdır' FROM q UNION ALL SELECT id,2,'Proxy, yalnızca class mirasını (inheritance) simüle etmek için prototype yerine kullanılan bir pattern''dir' FROM q UNION ALL SELECT id,3,'Nesne operasyonlarını (get, set, delete) intercept eder; validasyon, logging, observable nesne ve Vue reaktivitesi için kullanılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','mid','Promise.allSettled() ile Promise.all() arasındaki fark nedir?','Promise.all(): herhangi biri reject olursa hemen reject eder (fail fast). Promise.allSettled(): tümü tamamlanana kadar bekler (resolved veya rejected); her birinin sonucunu `{status, value/reason}` formatında döndürür. Bazı promise''lerin başarısız olabileceği durumda tüm sonuçları görmek için allSettled tercih edilir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Promise.all() herhangi biri reject olursa tüm chain reject eder; allSettled() tümünü bekler, her birinin sonucunu döndürür' FROM q UNION ALL SELECT id,1,'Promise.allSettled() her zaman resolve eder; hata asla fırlatmaz. Promise.all() ise hataları sessizce yutup devam eder' FROM q UNION ALL SELECT id,2,'Promise.all() paralel, allSettled() ise sıralı çalıştırır; performans farkı bu noktada ortaya çıkar' FROM q UNION ALL SELECT id,3,'İkisi aynıdır; allSettled() yalnızca daha yeni bir sözdizimi sunan alias''tır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','mid','async/await kullanımında yaygın bir hata hangisidir?','Yaygın hata: `await` kullanmayı unutmak (promise geri döner, resolved değeri değil); ardışık await yerine paralel await kullanmamak (sıralı bekleme gereksiz yavaşlatır, Promise.all ile paralel yapılabilir); try/catch olmadan await (unhandled rejection); for döngüsünde await (her iterasyonu bekler — genellikle istenmeyen).',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'async/await yalnızca class metodlarında kullanılabilir; standalone fonksiyonlarda syntax hatası verir' FROM q UNION ALL SELECT id,1,'await kullanmayı unutmak, paralel yerine sıralı await ve try/catch eksikliği en yaygın hatalardır' FROM q UNION ALL SELECT id,2,'async/await yalnızca HTTP isteklerinde kullanılabilir; genel asenkron işlemler için Promise.then tercih edilmelidir' FROM q UNION ALL SELECT id,3,'async fonksiyon tanımlamak onu her zaman yeni bir thread''de çalıştırır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','mid','CommonJS (require) ile ES Modules (import/export) arasındaki temel fark nedir?','CommonJS: synchronous require; çalışma zamanında değerlendirme; `module.exports`; Node.js default. ESM: static import; derleme zamanında analiz edilebilir (tree shaking mümkün); async import(); tarayıcı ve modern Node.js. ESM statik yapısı bundler''ların dead code elimination yapmasına imkân verir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'CommonJS ve ESM aynı şeydir; fark yalnızca sözdizimindedir (require vs import)' FROM q UNION ALL SELECT id,1,'ESM yalnızca TypeScript ile kullanılabilir; vanilla JS''de import/export syntax hatası verir' FROM q UNION ALL SELECT id,2,'CommonJS senkron runtime require; ESM statik import (tree shaking destekli, async dynamic import); ESM modern standart' FROM q UNION ALL SELECT id,3,'CommonJS daha hızlıdır; ESM yalnızca legacy browser uyumluluğu için geliştirilmiştir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','mid','Event delegation pattern nedir?','Event delegation: her child element yerine ortak parent element üzerine tek event listener eklemek. Çalışma prensibi: event bubbling. Avantajlar: az bellek (tek listener), dinamik eklenen child''lar otomatik desteklenir. `event.target` ile hangi child''ın tıklandığı belirlenir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Event delegation, birden fazla event türünü tek bir handler''a bağlamak için kullanılan bir pattern''dir' FROM q UNION ALL SELECT id,1,'Event delegation, asenkron event''leri sıraya koyarak sıralı işlenmesini sağlayan bir kuyruklama mekanizmasıdır' FROM q UNION ALL SELECT id,2,'Event delegation, React ve Vue gibi framework''lerin DOM event''lerini yönetmek için kullandığı framework-specific pattern''dir' FROM q UNION ALL SELECT id,3,'Parent elementte tek listener ile child event''leri bubble yoluyla yakalar; az bellek ve dinamik child desteği sağlar' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','mid','Object.freeze() ile Object.seal() arasındaki fark nedir?','Object.freeze(): nesneye yeni property eklenemez, var olanlar silinemez ve değerleri değiştirilemez (immutable). Object.seal(): yeni property eklenemez, var olanlar silinemez; ancak mevcut property değerleri değiştirilebilir. İkisi de shallow''dur; iç içe nesneler etkilenmez.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'freeze tam immutable (ekleme/silme/değiştirme yasak); seal yalnızca ekleme/silme yasak, mevcut değerler değiştirilebilir; ikisi de shallow' FROM q UNION ALL SELECT id,1,'freeze yalnızca array''lere, seal ise yalnızca nesne değişkenlerine uygulanabilir' FROM q UNION ALL SELECT id,2,'Object.freeze() deep clone yapar; Object.seal() ise yalnızca referansı korur' FROM q UNION ALL SELECT id,3,'İkisi arasında fark yoktur; freeze, seal''in daha kısa sözdizimli versiyonudur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','mid','Optional chaining (?.) ve nullish coalescing (??) operatörleri ne sağlar?','Optional chaining `?.`: zincirdeki değer null/undefined ise hata fırlatmak yerine undefined döner (`obj?.prop?.method()`). Nullish coalescing `??`: sol taraf null veya undefined ise sağ tarafı döndürür (0 veya "" sol değer olabilir; || ile fark burada ortaya çıkar). İkisi birlikte null-safe kod yazımını kolaylaştırır.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'?. async fonksiyonları await olmadan çağırmak, ?? ise promise değerinin boş olup olmadığını kontrol etmek için kullanılır' FROM q UNION ALL SELECT id,1,'?. null/undefined zincirde hata fırlatmak yerine undefined döner; ?? null/undefined için fallback verir (0 ve "" geçerli değer)' FROM q UNION ALL SELECT id,2,'?. yalnızca DOM elementlerine güvenli erişim, ?? ise yalnızca API yanıtları için kullanılır' FROM q UNION ALL SELECT id,3,'?. ve ?? aynı operatördür; farklı sözdizimi alternatif olarak sunulmuştur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','senior','V8 engine''inde hidden class (shape) optimizasyonu nasıl çalışır?','V8, nesne property''lerinin ekleme sırasını takip eden hidden class (shape/map) oluşturur. Aynı sırayla oluşturulan nesneler aynı hidden class''ı paylaşır; bu JIT optimizasyonuna izin verir. Bir nesnenin property sırası/yapısı değişirse yeni hidden class oluşturulur (deoptimizasyon). Bu nedenle nesne yapısını sabit tutmak ve dynamic property eklenmesini en aza indirmek performansı artırır.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'V8 hidden class, tüm JavaScript nesnelerini tek bir prototype zinciriyle birleştiren gizli bir sınıf sistemidir' FROM q UNION ALL SELECT id,1,'Hidden class, JavaScript class keyword''ünün çalışma zamanındaki iç temsilidir; new ile oluşturulan her instance paylaşır' FROM q UNION ALL SELECT id,2,'V8, aynı property sırası/yapısındaki nesneler için hidden class paylaşır; JIT optimizasyonu sağlar; yapı değişince deoptimizasyon olur' FROM q UNION ALL SELECT id,3,'Hidden class V8''in bellek şifrelleme mekanizmasıdır; dışarıdan erişimi önlemek için kullanılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','senior','JavaScript garbage collection nasıl çalışır ve memory leak nasıl oluşur?','V8: mark-and-sweep algoritması. GC erişilemeyen (unreachable) nesneleri toplar. Memory leak: closure ile büyük nesneyi beklenmedik süre canlı tutmak, unutulan event listener, circular reference (modern GC halleder), detached DOM node''ları, closure''da global değişken birikimi. Chrome DevTools Memory profiler ile tespit edilir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'JavaScript manuel bellek yönetimi gerektirir; GC yalnızca number ve string primitive''leri otomatik temizler' FROM q UNION ALL SELECT id,1,'GC yalnızca null atandığında çalışır; null atanmamış değişkenler asla temizlenmez' FROM q UNION ALL SELECT id,2,'JavaScript GC reference counting kullanır; circular reference her zaman memory leak oluşturur' FROM q UNION ALL SELECT id,3,'Mark-and-sweep ile erişilemeyen nesneler toplanır; closure, unutulan event listener ve detached DOM leak nedenidir; DevTools ile tespit edilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','senior','SharedArrayBuffer ve Atomics ne sağlar?','SharedArrayBuffer, birden fazla Worker arasında paylaşılan bellek tamponu sağlar (gerçek paylaşımlı bellek). Atomics, bu paylaşımlı bellekte race condition olmadan okuma/yazma operasyonları sağlar (compare-exchange, add, wait/notify). Spectre saldırısı nedeniyle cross-origin isolation (COOP/COEP header) zorunlu kılındı.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Birden fazla Worker arasında gerçek paylaşımlı bellek; Atomics ile race condition''sız okuma/yazma; COOP/COEP header zorunlu' FROM q UNION ALL SELECT id,1,'SharedArrayBuffer, localStorage''ın thread-safe versiyonu olup Service Worker ile paylaşım sağlar' FROM q UNION ALL SELECT id,2,'SharedArrayBuffer WebSocket üzerinden sunucu ve istemci arasında binary veri paylaşımı için kullanılır' FROM q UNION ALL SELECT id,3,'Atomics yalnızca sayı toplama işlemleri için kullanılır; karmaşık veri yapıları Atomics ile yönetilemez' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','senior','Async iterators ve for-await-of ne sağlar?','Async iterator: Symbol.asyncIterator ile tanımlanan ve `next()` metodundan Promise döndüren iterator. `for await...of` döngüsü her adımı await eder. Kullanım: Node.js stream, paginated API, database cursor. Tüm sayfalamayı belleğe almak yerine sayfa sayfa işleme imkânı sunar.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'for await...of yalnızca Promise dizilerinde kullanılabilir; Symbol.asyncIterator gerekmez' FROM q UNION ALL SELECT id,1,'Symbol.asyncIterator ile tanımlı nesnelerde for await...of ile asenkron öğeleri sıralı tüketir; stream ve paginated API için idealdir' FROM q UNION ALL SELECT id,2,'Async iterator, birden fazla promise''i paralel çalıştırıp sonuçlarını sıralı döndüren Promise.all alternatifidir' FROM q UNION ALL SELECT id,3,'for await...of yalnızca Node.js''de çalışır; tarayıcı ortamında async iterator desteği yoktur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','senior','Reflect API''nin Proxy ile birlikte kullanımındaki önemi nedir?','Reflect, nesne operasyonlarının (get, set, apply...) standart fonksiyon karşılıklarını sağlar. Proxy trap içinde orijinal davranışı çalıştırmak için `Reflect.get(target, key, receiver)` kullanılır; bu `target[key]` yazmaktan üstündür çünkü getter''lar için doğru `receiver` (this) bağlamasını korur. Trap''ların invariant''larını (değişmezlerini) da sağlar.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Reflect yalnızca class bildirimlerinde kullanılır; Proxy ile ilgisi yoktur' FROM q UNION ALL SELECT id,1,'Reflect, Proxy trap içinde günlük log yazmak için kullanılan özel bir logging API''sidir' FROM q UNION ALL SELECT id,2,'Proxy trap içinde orijinal operasyonu doğru receiver ile çalıştırmak için kullanılır; getter invariant''larını korur' FROM q UNION ALL SELECT id,3,'Reflect, nesneyi JSON''a dönüştüren ve JSON.stringify''ın gelişmiş versiyonu olan bir serializasyon aracıdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','senior','JavaScript''te tail call optimization nedir ve hangi koşulda gerçekleşir?','TCO: bir fonksiyonun son işleminin doğrudan başka bir fonksiyon çağrısı olması ve dönüş değerinin bu çağrı sonucu olması durumunda call stack frame yeniden kullanılır (stack büyümez). Strict mode ve gerçek tail position zorunludur. V8 TCO desteği kısıtlıdır (2024 itibarıyla); Safari/JavaScriptCore destekler. Rekürsif fonksiyonları O(n) stack yerine O(1) stack ile çalıştırır.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Tail call optimization, tüm fonksiyon çağrılarını inline''a çeviren derleyici optimizasyonudur; kodun daha hızlı çalışmasını sağlar' FROM q UNION ALL SELECT id,1,'Tail call, async fonksiyonun son return değerini doğrudan promise olmadan döndürmesine imkân tanıyan özelliktir' FROM q UNION ALL SELECT id,2,'Tail call optimization yalnızca arrow function''larda gerçekleşir; regular function''larda call stack her zaman büyür' FROM q UNION ALL SELECT id,3,'Son işlem doğrudan fonksiyon çağrısıysa stack frame yeniden kullanılır; rekürsif fonksiyonlar O(1) stack ile çalışabilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','mid','Array.prototype.reduce() doğru kullanım şekli ve güçlü kullanım örnekleri?','reduce(callback, initialValue): her adımda accumulator güncellenir. initialValue zorunlu değil ama güvenli pratik için verilmeli (boş dizi + no initial value = TypeError). Kullanım: toplama, gruplama (object), flatten, pipeline (fonksiyon zinciri), Map/Set oluşturma. Okunabilirlik için basit işlemlerde map+filter tercih edilebilir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Her adımda accumulator biriktirir; gruplama, flatten, pipeline için güçlü; initialValue vermek güvenli pratik, boş dizi + initialValue yok = TypeError' FROM q UNION ALL SELECT id,1,'reduce() yalnızca sayısal diziler için kullanılabilir; nesne ve string dizilerinde TypeError fırlatır' FROM q UNION ALL SELECT id,2,'reduce() her zaman map().filter() kombinasyonundan daha hızlıdır; her zaman tercih edilmelidir' FROM q UNION ALL SELECT id,3,'reduce() orijinal diziyi değiştirir ve in-place güncelleme yapar; yeni dizi döndürmez' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','mid','Map ve Object arasında key-value depolama için hangisi tercih edilmeli?','Map: her tipte key (nesne, fonksiyon dahil), insertion order garanti, size özelliği, iterable, prototype kirlilik yok. Object: string/Symbol key, prototip zinciri dikkat gerektirir, JSON serializasyonu kolay. Sık ekleme/silme ve non-string key için Map; JSON uyumluluğu için Object.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Object her zaman Map''ten daha hızlıdır; Map yalnızca okunabilirlik için tercih edilir' FROM q UNION ALL SELECT id,1,'Map her tipte key, insertion order garanti, size ve iterable; Object JSON uyumlu; sık ekleme/silme veya non-string key için Map' FROM q UNION ALL SELECT id,2,'Map ve Object tamamen aynıdır; yalnızca sözdizimi farklıdır' FROM q UNION ALL SELECT id,3,'Map yalnızca number key, Object ise yalnızca string key depolayabilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','junior','JavaScript''te `typeof` ve `instanceof` operatörleri arasındaki fark nedir?','typeof: primitive tip kontrolü (string, number, boolean, undefined, symbol, bigint, function); null için "object" bug. instanceof: prototype zincirini kontrol eder; nesne bir class''ın instance''ı mı? Primitives için instanceof çalışmaz (new String("x") instanceof String true ama "x" instanceof String false).',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'typeof ve instanceof her zaman aynı sonucu döndürür; fark yalnızca sözdizimindedir' FROM q UNION ALL SELECT id,1,'typeof yalnızca sayısal değerleri kontrol eder; diğer tipler için instanceof kullanılmalıdır' FROM q UNION ALL SELECT id,2,'typeof primitive tip döndürür (null bug dahil); instanceof prototype zincirini kontrol eder; primitives için instanceof çalışmaz' FROM q UNION ALL SELECT id,3,'instanceof yalnızca custom class''lar için kullanılabilir; built-in tipler (Array, Map) instanceof ile kontrol edilemez' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','junior','try/catch/finally bloklarının çalışma sırası nasıldır?','try: normal yürütme. catch: try''da exception fırlatılırsa çalışır. finally: exception olsun veya olmasın her zaman çalışır (return veya break olsa bile). finally içindeki return, try veya catch''teki return''ü geçersiz kılar. Kaynak temizleme (dosya kapatma, bağlantı kesme) için finally kullanılır.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'try → finally → catch sıralamasında çalışır; catch en sonda hataları toplar' FROM q UNION ALL SELECT id,1,'finally yalnızca catch bloğu çalışırsa execute edilir; try başarılıysa finally atlanır' FROM q UNION ALL SELECT id,2,'try ve catch paralel çalışır; finally ise her ikisi tamamlandıktan sonra execute edilir' FROM q UNION ALL SELECT id,3,'try çalışır, hata varsa catch çalışır, ardından finally her durumda çalışır; finally''deki return diğer return''leri ezer' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','senior','AbortController ile fetch isteğini nasıl iptal edersiniz?','AbortController: `const controller = new AbortController()`. fetch''e `{ signal: controller.signal }` geçilir. İptal için `controller.abort()` çağrılır; fetch promise "AbortError" ile reject olur. React: useEffect cleanup''ta iptal edilmelidir; unmount sonrası state update önlenir. Birden fazla fetch aynı controller paylaşabilir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'AbortController oluşturulur, signal fetch''e geçilir; controller.abort() ile iptal edilir; React''ta cleanup''ta çağrılmalıdır' FROM q UNION ALL SELECT id,1,'fetch iptal edilemez; AbortController yalnızca XMLHttpRequest için çalışır' FROM q UNION ALL SELECT id,2,'fetch().cancel() metodu ile iptal edilir; AbortController farklı bir API''dir ve fetch ile uyumsuzludur' FROM q UNION ALL SELECT id,3,'fetch timeout ile otomatik iptal edilir; manuel iptal için AbortController gerekli değildir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','mid','Promise constructor''ındaki executor fonksiyonu nasıl çalışır?','Promise constructor: `new Promise((resolve, reject) => { ... })`. Executor senkron olarak çalışır (hemen çalışır, mikrotask değil). resolve/reject birden fazla çağrılabilir ama yalnızca ilki etkili olur. Executor içinde throw edilen hata promise''i reject eder.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Executor asenkron çalışır; promise oluşturulduktan sonra event loop''un bir sonraki döngüsünde execute edilir' FROM q UNION ALL SELECT id,1,'Executor senkron olarak anında çalışır; resolve/reject yalnızca bir kez etkilidir; throw promise''i reject eder' FROM q UNION ALL SELECT id,2,'Executor yalnızca resolve çağrıldığında çalışır; reject çağrılırsa executor durdurulur' FROM q UNION ALL SELECT id,3,'Executor her .then() çağrısında yeniden çalışır; bu lazy evaluation sağlar' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','junior','Array destructuring''de varsayılan değer atama nasıl yapılır?','`const [a = 1, b = 2] = [10]` → a = 10, b = 2. Varsayılan değer yalnızca eleman undefined olduğunda kullanılır; null değeri varsayılan değeri tetiklemez. Nested destructuring ve default kombinasyon mümkündür: `const [{ x = 0, y = 0 } = {}] = []`.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Array destructuring''de varsayılan değer atanamaz; yalnızca nesne destructuring bu özelliği destekler' FROM q UNION ALL SELECT id,1,'Varsayılan değer null dahil herhangi bir falsy değer için devreye girer' FROM q UNION ALL SELECT id,2,'`[a = 1]` şeklinde tanımlanır; yalnızca undefined olduğunda varsayılan devreye girer; null varsayılanı tetiklemez' FROM q UNION ALL SELECT id,3,'Varsayılan değer atama yalnızca TypeScript''te desteklenir; vanilla JavaScript''te sözdizimi hatası verir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','mid','Computed property names ne sağlar?','Computed property names: `{ [expression]: value }`. Dinamik key ile nesne oluşturma; değişken veya expression ile property adı belirleme. Kullanım: action type bazlı reducer (Redux), dynamic form field, API response normalizer. ES2015+ özelliği; for...in ve Object.keys ile diğer property''ler gibi davranır.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Computed property names, nesnenin tüm property''lerini hesaplanmış (computed) değerlere dönüştüren bir getter/setter pattern''dir' FROM q UNION ALL SELECT id,1,'Computed property names yalnızca class tanımlamalarında kullanılabilir; literal nesne sözdiziminde desteklenmez' FROM q UNION ALL SELECT id,2,'Computed property names yalnızca sayısal değerleri property adı olarak kabul eder; string expression hata verir' FROM q UNION ALL SELECT id,3,'`{ [expr]: value }` ile dinamik property adı belirlenir; reducer action type, dynamic form ve API normalizasyon için kullanılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('javascript','tr','mid','structuredClone() ile JSON.parse(JSON.stringify()) arasındaki fark nedir?','JSON.parse(JSON.stringify()): undefined, Function, Symbol, RegExp, Date (string olur), Map, Set, circular reference desteklemez. structuredClone(): undefined, RegExp, Date, Map, Set, ArrayBuffer destekler; circular reference destekler; Function desteklemez; DOM node desteklemez. Derin kopyalama için structuredClone modern ve güvenli tercih.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'structuredClone Date, Map, Set, circular reference destekler; JSON dönüşümü bunları desteklemez; structuredClone modern tercih' FROM q UNION ALL SELECT id,1,'JSON.parse(JSON.stringify()) her zaman structuredClone''dan daha hızlıdır; karmaşık nesne yoksa JSON tercih edilir' FROM q UNION ALL SELECT id,2,'İkisi aynı sonucu üretir; structuredClone yalnızca daha yeni bir sözdizimdir' FROM q UNION ALL SELECT id,3,'structuredClone yalnızca Node.js 22+ ve tarayıcılar arası uyumsuzluk nedeniyle polyfill gerektirir' FROM q;

