-- PYTHON (+40 soru)
-- ============================================================

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','junior','Python''da mutable ve immutable veri tipleri arasındaki temel fark nedir?','Immutable tipler (int, str, tuple) oluşturulduktan sonra değiştirilemez; değişiklik yeni bir nesne yaratır. Mutable tipler (list, dict, set) yerinde değiştirilebilir. Bu fark fonksiyon argümanlarında ve bellek yönetiminde kritik önem taşır.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Immutable nesneler oluşturulduktan sonra değiştirilemez, mutable nesneler değiştirilebilir' FROM q UNION ALL SELECT id,1,'Immutable nesneler stack''te, mutable nesneler heap''te saklanır' FROM q UNION ALL SELECT id,2,'Immutable nesneler yalnızca sayısal değerleri, mutable nesneler string değerleri tutar' FROM q UNION ALL SELECT id,3,'Immutable nesneler thread-safe değildir, mutable nesneler thread-safe''dir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','junior','Python''da list ve tuple arasındaki temel fark nedir?','List değiştirilebilir (mutable) ve köşeli parantezle ([]) tanımlanır. Tuple değiştirilemez (immutable) ve normal parantezle (()) tanımlanır. Tuple''lar genellikle daha hızlı ve bellek açısından daha verimlidir.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'List hem sayısal hem string tutar, tuple yalnızca sayısal değerler tutar' FROM q UNION ALL SELECT id,1,'List değiştirilebilir (mutable), tuple değiştirilemez (immutable)' FROM q UNION ALL SELECT id,2,'List sıralıdır, tuple sırasızdır' FROM q UNION ALL SELECT id,3,'List maksimum 100 eleman tutar, tuple sınırsız eleman tutar' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','junior','Python''da *args ve **kwargs ne işe yarar?','*args, fonksiyona değişken sayıda pozisyonel argüman geçirmeyi sağlar ve tuple olarak gelir. **kwargs, değişken sayıda keyword argüman geçirmeyi sağlar ve dict olarak gelir. İkisi birlikte kullanılabilir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'*args liste döndürür, **kwargs tuple döndürür' FROM q UNION ALL SELECT id,1,'*args yalnızca string argümanlar için, **kwargs yalnızca sayısal argümanlar için kullanılır' FROM q UNION ALL SELECT id,2,'*args değişken sayıda pozisyonel argümanı tuple olarak, **kwargs keyword argümanları dict olarak alır' FROM q UNION ALL SELECT id,3,'*args ve **kwargs aynı işlevi görür, ikisi de keyword argümanları alır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','junior','Python''da __init__ metodu ne zaman çağrılır?','__init__ metodu, bir sınıftan yeni bir nesne oluşturulduğunda otomatik olarak çağrılır. Nesnenin ilk durumunu (initial state) ayarlamak için kullanılır. __new__ metodu çağrıldıktan sonra çalışır.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'__init__ yalnızca sınıf ilk kez import edildiğinde çağrılır' FROM q UNION ALL SELECT id,1,'__init__ her metod çağrısında otomatik olarak çağrılır' FROM q UNION ALL SELECT id,2,'__init__ yalnızca sınıf miras alındığında çağrılır' FROM q UNION ALL SELECT id,3,'__init__ sınıftan yeni bir nesne oluşturulduğunda otomatik olarak çağrılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','junior','Python''da list comprehension hangi durumda tercih edilmelidir?','List comprehension, döngü ile liste oluşturmanın daha Pythonic ve genellikle daha hızlı yoludur. Tek satırda okunabilir ve anlaşılır ifadeler için uygundur. Karmaşık mantık veya yan etkileri olan işlemler için normal döngü tercih edilmeli.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Kısa ve okunabilir liste dönüşümlerinde, karmaşık yan etkiler içermeyen ifadelerde' FROM q UNION ALL SELECT id,1,'Yalnızca sayısal listeler oluştururken, string listelerinde kullanılamaz' FROM q UNION ALL SELECT id,2,'10.000''den fazla eleman içeren listelerde performans için zorunludur' FROM q UNION ALL SELECT id,3,'Her zaman normal for döngüsüne göre daha hızlı olduğu için her durumda tercih edilmeli' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','junior','Python''da is ve == operatörleri arasındaki fark nedir?','== operatörü iki nesnenin değerinin eşit olup olmadığını kontrol eder. is operatörü iki nesnenin bellekte aynı nesneyi işaret edip etmediğini kontrol eder (identity). None karşılaştırmalarında is kullanılmalıdır.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'is yalnızca sayılar için, == yalnızca string''ler için kullanılır' FROM q UNION ALL SELECT id,1,'== değer eşitliğini, is nesne kimliği (identity) eşitliğini karşılaştırır' FROM q UNION ALL SELECT id,2,'is büyüktür/küçüktür karşılaştırması yapar, == eşitlik karşılaştırması yapar' FROM q UNION ALL SELECT id,3,'is ve == aynı sonucu döndürür, sadece yazım farkı vardır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','junior','Python''da try/except/finally bloğunda finally bloğu ne zaman çalışır?','finally bloğu her durumda çalışır: exception fırlatılsa da fırlatılmasa da, hatta return veya break ifadesi olsa bile. Kaynak temizleme (dosya kapatma, bağlantı kesme) için idealdir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'finally bloğu yalnızca exception fırlatıldığında çalışır' FROM q UNION ALL SELECT id,1,'finally bloğu yalnızca exception fırlatılmadığında çalışır' FROM q UNION ALL SELECT id,2,'finally bloğu exception olsun ya da olmasın her durumda çalışır' FROM q UNION ALL SELECT id,3,'finally bloğu yalnızca except bloğu çalıştıktan sonra çalışır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','junior','Python''da bir dictionary''de anahtarın var olup olmadığını kontrol etmenin önerilen yolu nedir?','in operatörü ile key in dict şeklinde kontrol etmek en Pythonic yoldur. dict.get(key) metodu da kullanılabilir. dict.has_key() Python 3''te kaldırılmıştır.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'dict.has_key(key) metodu kullanılmalıdır' FROM q UNION ALL SELECT id,1,'try/except KeyError bloğu her zaman en doğru yoldur' FROM q UNION ALL SELECT id,2,'dict.contains(key) metodu kullanılmalıdır' FROM q UNION ALL SELECT id,3,'key in dict ifadesi veya dict.get(key) metodu önerilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','junior','Python''da range() fonksiyonu ne tür bir nesne döndürür?','range() fonksiyonu bir liste değil, range nesnesi döndürür. Bu nesne lazy evaluation kullanır; tüm değerleri bellekte saklamaz, yalnızca ihtiyaç duyulduğunda hesaplar. Büyük aralıklar için bellek tasarrufu sağlar.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Bellek açısından verimli, lazy evaluation kullanan bir range nesnesi döndürür' FROM q UNION ALL SELECT id,1,'Tüm sayıları içeren bir liste döndürür' FROM q UNION ALL SELECT id,2,'Sayıları üretecek bir generator fonksiyonu döndürür' FROM q UNION ALL SELECT id,3,'Bir iterator nesnesi döndürür, list()''e gerek kalmadan direkt kullanılamaz' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','junior','Python''da sort() ve sorted() arasındaki temel fark nedir?','sort() metodu listeyi yerinde (in-place) sıralar ve None döndürür; yalnızca list nesneleri üzerinde çalışır. sorted() yeni bir liste döndürür ve herhangi bir iterable üzerinde çalışır.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'sort() büyükten küçüğe, sorted() küçükten büyüğe sıralar' FROM q UNION ALL SELECT id,1,'sort() listeyi yerinde değiştirir ve None döndürür, sorted() yeni liste döndürür ve her iterable''a uygulanabilir' FROM q UNION ALL SELECT id,2,'sort() yalnızca sayısal listelerde, sorted() yalnızca string listelerinde çalışır' FROM q UNION ALL SELECT id,3,'sort() ve sorted() aynı işlevi görür, yalnızca sözdizimi farklıdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','junior','Python''da string formatlama için f-string (f"") ne zaman tercih edilmelidir?','f-string (Python 3.6+) en okunabilir ve genellikle en hızlı formatlama yöntemidir. Değişkenleri ve ifadeleri doğrudan string içine {} ile yerleştirmeyi sağlar. .format() ve % operatöründen daha modern ve tercih edilen yöntemdir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'f-string yalnızca Python 2''de kullanılabilir, Python 3''te .format() tercih edilmeli' FROM q UNION ALL SELECT id,1,'f-string yalnızca tek değişken yerleştirmek için uygundur, çok değişkende .format() kullanılmalı' FROM q UNION ALL SELECT id,2,'Python 3.6+ için okunabilirlik ve performans açısından en modern ve tercih edilen yöntemdir' FROM q UNION ALL SELECT id,3,'f-string ve .format() aynı performansı gösterir, tercih tamamen kişisel zevke bağlıdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','junior','Python''da global scope''taki bir değişkeni fonksiyon içinden değiştirmek için ne yapılmalıdır?','Fonksiyon içinde global bir değişkeni değiştirmek için global keyword''ü kullanılmalıdır. global x bildirimi yapılmazsa, fonksiyon içinde x = değer ifadesi yeni bir yerel değişken oluşturur.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Fonksiyon parametresi olarak geçirmek yeterlidir, global keyword gerekmez' FROM q UNION ALL SELECT id,1,'Python''da fonksiyon dışı değişkenler otomatik olarak tüm fonksiyonlardan erişilebilir ve değiştirilebilir' FROM q UNION ALL SELECT id,2,'import globals() komutu ile fonksiyon başında global değişkenler yüklenir' FROM q UNION ALL SELECT id,3,'Fonksiyon içinde global x bildirimi yaparak global scope''taki değişkene atama yapılabilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','junior','Python''da bir listeden belirli bir değere sahip tüm elemanları kaldırmanın Pythonic yolu nedir?','List comprehension ile [x for x in lst if x != val] kullanmak en Pythonic yoldur. Bu yaklaşım yeni bir liste oluşturur. filter() fonksiyonu da kullanılabilir. while döngüsü ile remove() ise daha az tercih edilen bir yoldur.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'[x for x in lst if x != val] şeklinde list comprehension kullanmak' FROM q UNION ALL SELECT id,1,'lst.removeAll(val) metodu çağırmak' FROM q UNION ALL SELECT id,2,'del lst[lst.index(val)] ifadesini döngü içinde tekrarlamak' FROM q UNION ALL SELECT id,3,'lst.clear() çağırıp ardından kalan elemanları tek tek eklemek' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','mid','Python''da decorator pattern nasıl çalışır ve ne için kullanılır?','Decorator, bir fonksiyon veya sınıfı argüman olarak alıp genişletilmiş davranışla saran (wrap eden) bir fonksiyondur. @decorator sözdizimi func = decorator(func) ile eşdeğerdir. Logging, caching, authentication gibi cross-cutting concern''ler için kullanılır.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Decorator, sınıf tanımına otomatik olarak __init__ ekleyen özel bir keyword''dür' FROM q UNION ALL SELECT id,1,'Decorator, bir fonksiyonu argüman alıp onu genişletilmiş davranışla sararak döndüren higher-order function''dır' FROM q UNION ALL SELECT id,2,'Decorator, Python''da tasarım deseni uygulamak için kullanılan bir import mekanizmasıdır' FROM q UNION ALL SELECT id,3,'Decorator yalnızca sınıf metodlarına uygulanabilir, bağımsız fonksiyonlara uygulanamaz' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','mid','Python''da generator ve normal fonksiyon arasındaki temel fark nedir?','Generator fonksiyonlar yield kullanır ve lazy evaluation ile değer üretir; tüm değerleri aynı anda bellekte tutmaz. Normal fonksiyonlar return ile tüm sonucu döndürür. Büyük veri setleri için bellek açısından generator çok daha verimlidir.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Generator fonksiyonlar yalnızca sayısal değerler üretebilir, normal fonksiyonlar her türlü değer döndürebilir' FROM q UNION ALL SELECT id,1,'Generator fonksiyonlar normal fonksiyonlardan her zaman daha yavaş çalışır çünkü ek overhead taşır' FROM q UNION ALL SELECT id,2,'Generator yield kullanarak lazy evaluation ile değer üretir; belleğe tüm sonuçları yüklemez' FROM q UNION ALL SELECT id,3,'Generator ve normal fonksiyon aynı şeydir, yield ile return birbirinin yerine kullanılabilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','mid','Python''da context manager (__enter__ / __exit__) nasıl çalışır?','with ifadesi __enter__ metodunu çağırır ve bloğa girildiğinde nesneyi as değişkenine atar. Blok bittiğinde (exception olsa da olmasa da) __exit__ metodu çağrılır. contextlib.contextmanager dekoratörü ile generator tabanlı context manager yazılabilir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Context manager yalnızca dosya işlemleri için kullanılabilir, diğer kaynaklar için try/finally kullanılmalıdır' FROM q UNION ALL SELECT id,1,'__enter__ ve __exit__ metodları yalnızca exception olduğunda çağrılır' FROM q UNION ALL SELECT id,2,'Context manager, with bloğundaki tüm exception''ları otomatik olarak yakalar ve yoksayar' FROM q UNION ALL SELECT id,3,'with bloğuna girilince __enter__, çıkılınca (exception olsa da olmasa da) __exit__ çağrılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','mid','Python''da copy.deepcopy() ve copy.copy() (shallow copy) arasındaki fark nedir?','Shallow copy, üst nesneyi kopyalar ancak iç içe nesnelere referans tutar. deepcopy ise tüm nesne ağacını özyinelemeli olarak kopyalar. İçi içe mutable nesneler içeren yapılarda shallow copy beklenmedik sonuçlar doğurabilir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'deepcopy tüm nesne ağacını özyinelemeli kopyalar; shallow copy üst nesneyi kopyalar, iç nesnelere referans tutar' FROM q UNION ALL SELECT id,1,'shallow copy daha güvenlidir çünkü circular reference sorunlarına yol açmaz' FROM q UNION ALL SELECT id,2,'deepcopy yalnızca primitive tipler için çalışır, shallow copy nesneleri de kopyalar' FROM q UNION ALL SELECT id,3,'shallow copy ve deepcopy arasında fark yoktur; ikisi de aynı bellek adresini işaret eder' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','mid','Python''da @staticmethod ve @classmethod arasındaki fark nedir?','@staticmethod sınıf veya örnek hakkında bilgi almaz; ne self ne de cls parametresi alır. @classmethod cls parametresiyle sınıfı alır ve sınıf düzeyinde davranışlar için kullanılır. classmethod miras alındığında alt sınıfı temsil eder.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'staticmethod yalnızca sınıf niteliklere, classmethod yalnızca instance niteliklere erişebilir' FROM q UNION ALL SELECT id,1,'staticmethod ne self ne cls alır; classmethod cls (sınıf) alır ve factory method olarak kullanılabilir' FROM q UNION ALL SELECT id,2,'classmethod ve staticmethod aynı işlevi görür, fark yalnızca sözdizimseldir' FROM q UNION ALL SELECT id,3,'staticmethod miras alınamaz, classmethod miras alınabilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','mid','Python''da __str__ ve __repr__ metodları arasındaki fark nedir?','__str__ insan tarafından okunabilir bir string döndürmek için kullanılır; print() ve str() tarafından çağrılır. __repr__ nesnenin tekrar oluşturulabilir temsilini döndürmelidir; repr() ve interaktif konsol tarafından kullanılır. __str__ tanımlı değilse __repr__ kullanılır.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'__str__ ve __repr__ aynı işlevi görür; yalnızca birini tanımlamak yeterlidir' FROM q UNION ALL SELECT id,1,'__repr__ yalnızca debugging için, __str__ yalnızca dosyaya yazma için kullanılır' FROM q UNION ALL SELECT id,2,'__str__ insan dostu çıktı için, __repr__ nesnenin yeniden oluşturulabilir teknik temsili için kullanılır' FROM q UNION ALL SELECT id,3,'__str__ print()''de, __repr__ yalnızca logging kütüphanelerinde çağrılır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','mid','Python''da @property dekoratörü nasıl kullanılır ve ne sağlar?','@property, bir metodu sanki bir nitelik (attribute) gibi erişilebilir kılar. Getter, setter ve deleter tanımlamayı sağlar. Nesne arayüzünü bozmadan iç uygulamayı değiştirme esnekliği sunar; encapsulation sağlar.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'@property yalnızca sınıf değişkenlerini koruma altına almak için kullanılır, hesaplama yapamaz' FROM q UNION ALL SELECT id,1,'@property, bir metodu sınıf metodu yerine örnek metodu olarak işaretler' FROM q UNION ALL SELECT id,2,'@property yalnızca readonly nitelikler tanımlar; setter eklemek için ayrı bir kütüphane gerekir' FROM q UNION ALL SELECT id,3,'@property bir metodu nitelik gibi erişilebilir kılar; getter/setter/deleter tanımlamaya olanak verir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','mid','Python''da collections.defaultdict ile normal dict arasındaki fark nedir?','defaultdict, var olmayan bir anahtara erişildiğinde KeyError fırlatmak yerine belirtilen varsayılan değeri otomatik olarak oluşturur. defaultdict(list) ile liste, defaultdict(int) ile 0 varsayılan değeri kullanılabilir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'defaultdict olmayan anahtara erişildiğinde otomatik varsayılan değer oluşturur; dict KeyError fırlatır' FROM q UNION ALL SELECT id,1,'defaultdict yalnızca string anahtarlar için çalışır, dict her tür anahtarı destekler' FROM q UNION ALL SELECT id,2,'defaultdict her işlemde dict''ten daha yavaştır çünkü ek kontrol mekanizması taşır' FROM q UNION ALL SELECT id,3,'defaultdict ve dict aynı davranışı sergiler; fark yalnızca import kaynağındadır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','mid','Python''da yield keyword''ü nasıl çalışır ve generator fonksiyondan nasıl farklıdır?','yield ifadesi fonksiyonu duraklatır, değeri çağırana döndürür ve bir sonraki next() çağrısında kaldığı yerden devam eder. yield içeren herhangi bir fonksiyon generator fonksiyonu olur ve bir generator nesnesi döndürür.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'yield, return''ün farklı bir sözdizimi olup fonksiyonu aynı şekilde sonlandırır' FROM q UNION ALL SELECT id,1,'yield fonksiyonu duraklatır ve değer döndürür; next() çağrısında kaldığı yerden devam eder' FROM q UNION ALL SELECT id,2,'yield yalnızca for döngüsü içinde kullanılabilir, while veya if bloklarında çalışmaz' FROM q UNION ALL SELECT id,3,'yield kullanılan fonksiyonlar her çağrıda sıfırdan başlar, durum bilgisi tutmaz' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','mid','Python''da __slots__ tanımlamak ne sağlar?','__slots__ sınıflarda izin verilen niteliklerin listesini tanımlar. Bu sayede __dict__ oluşturulmaz, bellek kullanımı azalır ve nitelik erişimi hızlanır. Milyonlarca nesne oluşturulan senaryolarda önemli performans avantajı sağlar.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'__slots__, sınıf metodlarının dışarıdan çağrılmasını engelleyen bir erişim kontrol mekanizmasıdır' FROM q UNION ALL SELECT id,1,'__slots__ tanımlandığında sınıf miras alınamaz ve alt sınıf oluşturulamaz' FROM q UNION ALL SELECT id,2,'__slots__ __dict__ oluşturulmasını önleyerek bellek kullanımını azaltır ve nitelik erişimini hızlandırır' FROM q UNION ALL SELECT id,3,'__slots__ yalnızca Python 2''de desteklenir; Python 3''te etkisi yoktur' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','mid','Python''da functools.lru_cache dekoratörü nasıl çalışır?','lru_cache (Least Recently Used Cache), fonksiyon çağrılarını argümana göre önbellekler. Aynı argümanlarla tekrar çağrıldığında hesaplama yapmadan önbellekten döndürür. Saf fonksiyonlar ve pahalı hesaplamalar için çok etkilidir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'lru_cache fonksiyon çağrılarını paralel olarak çalıştırarak performansı artırır' FROM q UNION ALL SELECT id,1,'lru_cache yalnızca recursive fonksiyonlarda çalışır, diğer fonksiyonlarda etkisi yoktur' FROM q UNION ALL SELECT id,2,'lru_cache fonksiyon sonuçlarını dosyaya kaydeder, uygulama yeniden başlatıldığında da geçerlidir' FROM q UNION ALL SELECT id,3,'lru_cache sonuçları argümana göre önbellekler; aynı argümanla tekrar çağrılınca önbellekten döndürür' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','mid','Python''da ABC (Abstract Base Class) kullanmanın amacı nedir?','ABC ile soyut metod tanımlayan sınıflar oluşturulabilir. Bu metodları implemente etmeyen alt sınıflar instantiate edilemez. isinstance() ve issubclass() kontrolleri için de kullanılır. Duck typing''in yanı sıra daha güçlü tip kontrolü sağlar.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Alt sınıfların implemente etmesi zorunlu arayüzler tanımlamak ve isinstance kontrollerini güçlendirmek için' FROM q UNION ALL SELECT id,1,'ABC yalnızca multiple inheritance problemlerini çözmek için kullanılır' FROM q UNION ALL SELECT id,2,'ABC, Java''daki interface''e tam eşdeğerdir ve performans açısından hiçbir fark yoktur' FROM q UNION ALL SELECT id,3,'ABC kullanıldığında sınıf instance oluşturulamaz; yalnızca static metodlar çalışabilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','senior','Python''da GIL (Global Interpreter Lock) nedir ve CPU-bound programlara etkisi nedir?','GIL, CPython''da aynı anda yalnızca bir thread''in Python bytecode çalıştırmasına izin veren bir mutex''tir. I/O-bound programlarda threading hâlâ işe yarar çünkü I/O sırasında GIL serbest bırakılır. CPU-bound için multiprocessing veya C extension kullanılmalıdır.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'GIL yalnızca Python 2''de vardı; Python 3.2''den itibaren tamamen kaldırıldı' FROM q UNION ALL SELECT id,1,'GIL aynı anda tek thread''in bytecode çalıştırmasına izin verir; CPU-bound''da threading''i etkisiz kılar' FROM q UNION ALL SELECT id,2,'GIL sayesinde Python threading her zaman C++ thread''lerine eşit performans gösterir' FROM q UNION ALL SELECT id,3,'GIL yalnızca I/O işlemlerini etkiler; CPU-bound programlar GIL''den tamamen bağımsızdır' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','senior','Python''da metaclass nedir ve ne zaman kullanılmalıdır?','Metaclass, sınıfların sınıfıdır; sınıfın nasıl oluşturulacağını tanımlar. type, Python''ın varsayılan metaclass''ıdır. ORM''ler, API framework''leri ve sınıf oluşturma sürecini özelleştirmek gereken ileri seviye senaryolarda kullanılır.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Metaclass, Python''da multiple inheritance sorunlarını çözmek için kullanılan özel bir sınıf türüdür' FROM q UNION ALL SELECT id,1,'Metaclass yalnızca abstract sınıflar oluştururken kullanılır ve ABC ile eşdeğerdir' FROM q UNION ALL SELECT id,2,'Metaclass sınıfların sınıfıdır; sınıf oluşturma sürecini özelleştirmek için ORM ve framework''lerde kullanılır' FROM q UNION ALL SELECT id,3,'Metaclass, Python 3.8 ile eklenen yeni bir özellik olup eski sürümlerde desteklenmez' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','senior','Python''da asyncio event loop nasıl çalışır ve async/await ne sağlar?','Event loop, coroutine''leri tek bir thread üzerinde zamanlar. await ifadesi bir coroutine''i duraklatır ve event loop''un başka coroutine''leri çalıştırmasına izin verir. I/O-bound concurrent işlemler için thread overhead olmadan yüksek performans sağlar.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'asyncio, GIL problemini çözerek gerçek paralel CPU çalıştırması sağlar' FROM q UNION ALL SELECT id,1,'async/await yalnızca network isteklerinde çalışır; dosya ve veritabanı işlemlerinde kullanılamaz' FROM q UNION ALL SELECT id,2,'asyncio her coroutine için yeni bir thread oluşturur; bu sayede paralel çalışma sağlanır' FROM q UNION ALL SELECT id,3,'Event loop coroutine''leri tek thread''de zamanlar; await duraklatarak diğer coroutine''lere çalışma fırsatı verir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','senior','Python''da descriptor protocol nedir ve __get__, __set__, __delete__ ne işe yarar?','Descriptor, __get__, __set__ veya __delete__ metodlarından en az birini tanımlayan bir nesnedir. Bir sınıf niteliğine erişildiğinde Python bu metodları çağırır. property, staticmethod ve classmethod bu protokol üzerine inşa edilmiştir.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'__get__/__set__/__delete__ tanımlayan nesneler descriptor''dır; nitelik erişimini özelleştirmek için kullanılır' FROM q UNION ALL SELECT id,1,'Descriptor protocol yalnızca C extension''larında kullanılır, pure Python''da gerekli değildir' FROM q UNION ALL SELECT id,2,'Descriptor protocol, Python''da encapsulation sağlamanın tek yoludur ve @property''nin yerini alır' FROM q UNION ALL SELECT id,3,'Descriptor yalnızca __get__ metoduyla tanımlanabilir; __set__ ve __delete__ isteğe bağlı değildir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','senior','Python''da bellek yönetimi nasıl çalışır ve reference counting ne anlama gelir?','CPython referans sayımı (reference counting) kullanır: bir nesneye yapılan referans sayısı 0''a düştüğünde bellek serbest bırakılır. Döngüsel referanslar için çöp toplayıcı (gc module) devreye girer. Bu sistem belirleyici (deterministic) kaynak temizleme sağlar.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'Python belleği yalnızca uygulama kapandığında serbest bırakır; çalışma sırasında temizleme yapılmaz' FROM q UNION ALL SELECT id,1,'CPython referans sayımı kullanır; referans 0''a düşünce bellek serbest bırakılır, döngüsel referanslar için gc devreye girer' FROM q UNION ALL SELECT id,2,'Python''da garbage collector her 1 saniyede bir çalışır ve tüm kullanılmayan nesneleri temizler' FROM q UNION ALL SELECT id,3,'Python JVM benzeri bir heap yönetimi kullanır; bellek yönetimi tamamen işletim sistemine delege edilir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','senior','Python''da __new__ ve __init__ arasındaki fark nedir?','__new__ nesneyi oluşturur (allocates memory) ve nesneyi döndürür; __init__ oluşturulan nesneyi başlatır (initializes). Singleton pattern veya immutable nesneler için __new__ özelleştirilir. __new__ genellikle cls, __init__ ise self alır.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'__new__ ve __init__ aynı anda çağrılır; ikisi de nesne başlatma için aynı işlevi görür' FROM q UNION ALL SELECT id,1,'__init__ nesne oluşturur ve bellek tahsis eder; __new__ oluşturulan nesneyi başlatır' FROM q UNION ALL SELECT id,2,'__new__ nesneyi oluşturup döndürür (cls alır); __init__ döndürülen nesneyi başlatır (self alır)' FROM q UNION ALL SELECT id,3,'__new__ yalnızca abstract sınıflarda tanımlanabilir; normal sınıflarda __init__ yeterlidir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','senior','Python''da multiprocessing ne zaman threading''e tercih edilmelidir?','CPU-bound görevlerde GIL nedeniyle threading gerçek parallelism sağlamaz; multiprocessing her süreç için ayrı Python interpreter ve bellek alanı kullanarak gerçek parallelism sağlar. I/O-bound görevler için threading veya asyncio daha verimlidir.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'multiprocessing her zaman threading''e göre daha hızlıdır; threading hiçbir zaman kullanılmamalıdır' FROM q UNION ALL SELECT id,1,'multiprocessing yalnızca Windows''ta kullanılabilir; Linux''ta threading tercih edilmelidir' FROM q UNION ALL SELECT id,2,'I/O-bound görevlerde multiprocessing zorunludur çünkü threading dosya sistemine erişemez' FROM q UNION ALL SELECT id,3,'CPU-bound görevlerde GIL nedeniyle threading etkisizdir; multiprocessing gerçek parallelism sağlar' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','senior','Python''da type hints ve statik tip kontrol araçları (mypy) kullanmanın avantajları nelerdir?','Type hints (Python 3.5+) kodu dokümante eder, IDE desteğini artırır ve mypy gibi araçlarla runtime öncesi hataları yakalar. Runtime davranışı değiştirmez; yalnızca statik analizde kullanılır. Büyük projelerde bakım maliyetini düşürür.',0,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'IDE desteği, erken hata tespiti ve kod okunabilirliği sağlar; runtime''ı etkilemeden statik analiz imkânı verir' FROM q UNION ALL SELECT id,1,'Type hints runtime''da tür dönüşümlerini otomatik yapar ve tip uyumsuzluklarını düzeltir' FROM q UNION ALL SELECT id,2,'Type hints kullanıldığında Python dinamik tipten statik tipe geçer; tüm değişkenler sabit tip alır' FROM q UNION ALL SELECT id,3,'Type hints yalnızca Python 3.10+ ile desteklenir ve eski sürümlerde syntax hatasına yol açar' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','senior','Python''da __call__ metodu ne işe yarar ve callable nesne nedir?','__call__ tanımlanan nesneler fonksiyon gibi çağrılabilir hale gelir: obj(args). Callable nesne, çağrılabilir (çalıştırılabilir) bir nesnedir. Durum tutan (stateful) fonksiyon benzeri nesneler, dekoratör sınıfları için kullanılır.',1,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'__call__ yalnızca async fonksiyonlarda tanımlanabilir ve await ile kullanılır' FROM q UNION ALL SELECT id,1,'__call__ tanımlanan nesneler fonksiyon gibi obj() sözdizimi ile çağrılabilir; stateful callable''lar için idealdir' FROM q UNION ALL SELECT id,2,'__call__ Python''da method overloading yapmanın tek yoludur' FROM q UNION ALL SELECT id,3,'__call__ sınıf instantiate edildiğinde otomatik çağrılır; __init__''in alternatifidir' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','senior','Python''da @dataclass dekoratörü hangi metodları otomatik olarak oluşturur?','@dataclass, sınıf nitelikleri için __init__, __repr__ ve __eq__ metodlarını otomatik oluşturur. eq=True, order=True, frozen=True gibi parametrelerle davranış özelleştirilebilir. Boilerplate kod miktarını önemli ölçüde azaltır.',2,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'@dataclass yalnızca __init__ metodunu oluşturur; diğer metodlar manuel tanımlanmalıdır' FROM q UNION ALL SELECT id,1,'@dataclass sınıfı immutable yapar; tüm nitelikler otomatik olarak readonly olur' FROM q UNION ALL SELECT id,2,'@dataclass __init__, __repr__ ve __eq__ oluşturur; frozen=True ile __hash__ da eklenir' FROM q UNION ALL SELECT id,3,'@dataclass yalnızca primitive tip nitelikleri destekler; list ve dict nitelikler için NamedTuple kullanılmalı' FROM q;

WITH q AS (INSERT INTO questions (category_id, language, difficulty, question_text, explanation, correct_index, active) VALUES ('python','tr','senior','Python''da __getattr__ ve __getattribute__ arasındaki fark nedir?','__getattribute__ her nitelik erişiminde çağrılır. __getattr__ ise yalnızca normal mekanizmalarla bulunamayan niteliklerde çağrılır (fallback). __getattribute__ override edilirken dikkatli olunmalıdır; yanlış kullanım infinite recursion yaratır.',3,true) RETURNING id)
INSERT INTO question_options (question_id, option_index, option_text) SELECT id,0,'__getattr__ her nitelik erişiminde çağrılır; __getattribute__ yalnızca sınıf niteliklerinde çalışır' FROM q UNION ALL SELECT id,1,'__getattr__ ve __getattribute__ aynı işlevi görür; yalnızca naming convention farkı vardır' FROM q UNION ALL SELECT id,2,'__getattribute__ yalnızca magic method erişimlerinde çağrılır, normal niteliklerde __getattr__ çalışır' FROM q UNION ALL SELECT id,3,'__getattribute__ her erişimde çağrılır; __getattr__ yalnızca nitelik bulunamadığında (fallback) devreye girer' FROM q;

